		Threads: -1, Work: 5,
		DitherGrain: Dim{W: 4, H: 4, HasW: true, HasH: true, Set: false},
	}
	o.DitherGrain.W = 4
	o.DitherGrain.H = 4
	return o
}

// scanner for dimension strings, emulating sscanf("%dx%d%c") attempts
func scanInt(s string, pos *int) (int, bool) {
	i := *pos
	for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r' || s[i] == '\v' || s[i] == '\f') {
		i++
	}
	start := i
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		i++
	}
	digits := i
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	if i == digits {
		// no digits
		*pos = start
		return 0, false
	}
	txt := s[start:i]
	*pos = i
	// sscanf %d clamps to int range on overflow in glibc
	v, err := strconv.ParseInt(txt, 10, 64)
	if err != nil {
		if strings.HasPrefix(txt, "-") {
			return -2147483648, true
		}
		return 2147483647, true
	}
	if v > 2147483647 {
		v = 2147483647
	}
	if v < -2147483648 {
		v = -2147483648
	}
	return int(v), true
}

func parseDimString(s string, kind string) (Dim, string) {
	// kind: "Size", "View size", "Grid size", "Grain" (special messages handled by caller)
	formatMsg := func() string {
		switch kind {
		case "View size":
			return "View size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25."
		case "Grid size":
			return "Grid size must be specified as [width]x[height], [width]x or x[height], e.g 4x4, 4x or x4."
		case "Grain":
			return "Grain size must be specified as [width]x[height] or [dim], e.g. 8x4 or 4."
		default:
			return "Size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25."
		}
	}
	atLeastMsg := func() string {
		switch kind {
		case "View size":
			return "View size must be at least 1x1."
		case "Grid size":
			return "Grid size must be at least 1x1."
		case "Grain":
			return "Grain dimensions must be exactly 1, 2, 4 or 8."
		default:
			return "Size must be at least 1x1."
		}
	}
	var d Dim
	d.Set = true
	d.W = -1
	d.H = -1
	pos := 0
	w, ok := scanInt(s, &pos)
	if ok {
		// try literal x
		if pos < len(s) && s[pos] == 'x' {
			pos++
			hpos := pos
			h, ok2 := scanInt(s, &pos)
			if ok2 {
				// %c extra
				if pos < len(s) {
					return d, formatMsg()
				}
				d.W, d.H = w, h
				d.HasW, d.HasH = true, true
				// validation below
			} else {
				_ = hpos
				d.W = w
				d.HasW = true
			}
		} else {
			d.W = w
			d.HasW = true
		}
	} else {
		// try xH
		if len(s) > 0 && s[0] == 'x' {
			pos = 1
			h, ok2 := scanInt(s, &pos)
			if !ok2 {
				return d, formatMsg()
			}
			if pos < len(s) {
				return d, formatMsg()
			}
			d.H = h
			d.HasH = true
		} else {
			return d, formatMsg()
		}
	}
	// both negative -> format error
	if d.W < 0 && d.H < 0 && (d.HasW || d.HasH) {
		// Careful: missing dims are -1 sentinel; a single negative width gives W<0,H=-1 => format
		// A single positive width gives H=-1 but W>=0 -> ok
		// HasW/HasH distinguish explicit negatives: if either explicit dim is negative and the other is negative or missing(-1), it's both <0 as in original
		return d, formatMsg()
	}
	if (d.HasW && d.W == 0) || (d.HasH && d.H == 0) {
		return d, atLeastMsg()
	}
	// For grain, handled by caller
	return d, ""
}

// real or fraction parsing
func parseRealOrFraction(s string) (float64, bool) {
	if strings.Contains(s, "/") {
		// fraction: integer / integer
		parts := strings.Split(s, "/")
		if len(parts) != 2 {
			return 0, false
		}
		num, ok1 := parseCSLong(parts[0])
		den, ok2 := parseCSLong(parts[1])
		if !ok1 || !ok2 || den == 0 {
			return 0, false
		}
		// denominator and numerator must be ??? fraction values are longs; 1.5/2 fails because parseCSLong will
		// require entire string (aside from spaces) to be integer.
		return float64(num) / float64(den), true
	}
	v, ok := parseCStrtod(s)
	return v, ok
}

func parseCSLong(s string) (int64, bool) {
	// emulate strtol with full consumption except leading/trailing whitespace
	t := strings.TrimSpace(s)
	if t == "" {
		return 0, false
	}
	// strtol allows leading spaces (trimmed) and sign
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

func parseCStrtod(s string) (float64, bool) {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0, false
	}
	low := strings.ToLower(t)
	// C strtod special values
	switch low {
	case "inf", "+inf", "infinity", "+infinity":
		return math.Inf(1), true
	case "-inf", "-infinity":
		return math.Inf(-1), true
	case "nan", "+nan", "-nan":
		return math.NaN(), true
	}
	// hex float: Go's ParseFloat accepts 0x...p... but also plain hex int may be like 0x10
	if strings.HasPrefix(low, "0x") || strings.HasPrefix(low, "+0x") || strings.HasPrefix(low, "-0x") {
		// try Go parse; if it lacks exponent, treat as hex integer value
		if v, err := strconv.ParseFloat(t, 64); err == nil {
			return v, true
		}
		// parse hex digits as integer float
		neg := false
		tt := t
		if strings.HasPrefix(tt, "+") {
			tt = tt[1:]
		} else if strings.HasPrefix(tt, "-") {
			neg = true
			tt = tt[1:]
		}
		hexpart := tt[2:]
		// only hex digits allowed (hex float with . / p would have been handled)
		isHex := len(hexpart) > 0
		var val float64
		for _, c := range hexpart {
			var d int
			switch {
			case c >= '0' && c <= '9':
				d = int(c - '0')
			case c >= 'a' && c <= 'f':
				d = int(c-'a') + 10
			case c >= 'A' && c <= 'F':
				d = int(c-'A') + 10
			default:
				isHex = false
			}
			if !isHex {
				break
			}
			val = val*16 + float64(d)
		}
		if isHex {
			if neg {
				val = -val
			}
			return val, true
		}
