		isHex := len(hexpart) > 0
		var val float64
		for _, c := range hexpart {
			var d int
			switch {
			case c >= '0' && c <= '9':
				d = int(c - '0')
			case c >= 'a' && c <= 'f':
				d = int(c-'a') + 10
			case c >= 'A' && c <= 'F':
				d = int(c-'A') + 10
			default:
				isHex = false
			}
			if !isHex {
				break
			}
			val = val*16 + float64(d)
		}
		if isHex {
			if neg {
				val = -val
			}
			return val, true
		}
		return 0, false
	}
	v, err := strconv.ParseFloat(t, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

func parseBoolWord(s string) (bool, bool) {
	switch strings.ToLower(s) {
	case "on", "true", "yes":
		return true, true
	case "off", "false", "no":
		return false, true
	}
	return false, false
}

// GLib integer parsing: base 0, leading spaces allowed, full consumption
func parseGLibInt(s string) (int64, int) {
	// return value, status 0 ok, 1 cannot parse, 2 out of range
	t := strings.TrimLeft(s, " \t\n\r\v\f")
	if t == "" {
		return 0, 1
	}
	orig := t
	// Use ParseInt with base 0 after trimming left spaces; Go requires no leading +? It accepts.
	// But Go base0 does not accept leading spaces (removed) and rejects "010" as? Go: base0 octal works.
	v, err := strconv.ParseInt(t, 0, 64)
	if err != nil {
		// Determine if out of range: try to see if it's a valid integer syntax
		if isIntegerSyntax(orig) {
			// may be out of int64 or int32 range
			return 0, 2
		}
		return 0, 1
	}
	if v > 2147483647 || v < -2147483648 {
		return 0, 2
	}
	return v, 0
}

func isIntegerSyntax(s string) bool {
	t := strings.TrimLeft(s, " \t\n\r\v\f")
	if t == "" {
		return false
	}
	// sign
	if t[0] == '+' || t[0] == '-' {
		t = t[1:]
		if t == "" {
			return false
		}
	}
	if strings.HasPrefix(strings.ToLower(t), "0x") {
		h := t[2:]
		if h == "" {
			return false
		}
		for _, c := range h {
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
				return false
			}
		}
		return true
	}
	for _, c := range t {
		if c < '0' || c > '9' {
			return false
		}
	}
	return len(t) > 0
}

func intOptionError(prog, spelling, value string, status int) string {
	if status == 2 {
		return fmt.Sprintf("Integer value \u201c%s\u201d for %s out of range", value, spelling)
	}
	return fmt.Sprintf("Cannot parse integer value \u201c%s\u201d for %s", value, spelling)
}
GO"}

