func findLong(name string) *optDef {
	for i := range optDefs {
		if optDefs[i].long == name {
			return &optDefs[i]
		}
	}
	return nil
}
func findShort(c byte) *optDef {
	for i := range optDefs {
		if optDefs[i].short == c && c != 0 {
			return &optDefs[i]
		}
	}
	return nil
}

func parseArgs(prog string, args []string) (*Opts, error) {
	o := defaultOpts()
	o.Prog = prog
	// positional collection
	var pos []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			// special -- handling inferred from GLib
			rest := args[i+1:]
			hasDash := false
			for _, r := range rest {
				if strings.HasPrefix(r, "-") {
					// any token starting with '-', including "-" itself
					if len(r) >= 1 {
						hasDash = true
						break
					}
				}
			}
			if hasDash {
				pos = append(pos, "--")
				pos = append(pos, rest...)
			} else {
				pos = append(pos, rest...)
			}
			break
		}
		if len(arg) >= 2 && strings.HasPrefix(arg, "--") {
			// long
			body := arg[2:]
			name := body
			var inlineVal string
			hasInline := false
			if idx := strings.IndexByte(body, '='); idx >= 0 {
				name = body[:idx]
				inlineVal = body[idx+1:]
				hasInline = true
			}
			def := findLong(name)
			if def == nil {
				return nil, &parseError{fmt.Sprintf("Unknown option %s", arg)}
			}
			if !def.hasArg {
				// ignore inline value
				if err := applyFlag(o, def.id); err != nil {
					return nil, err
				}
				i++
				continue
			}
			var val string
			if hasInline {
				val = inlineVal
				i++
			} else {
				if i+1 >= len(args) {
					return nil, &parseError{fmt.Sprintf("Missing argument for --%s", name)}
				}
				val = args[i+1]
				i += 2
			}
			if err := applyArg(o, def, val, "--"+name); err != nil {
				return nil, err
			}
			continue
		}
		if len(arg) >= 2 && arg[0] == '-' && arg != "-" {
			// short cluster
			consumedNext := false
			// iterate chars
			for j := 1; j < len(arg); j++ {
				c := arg[j]
				def := findShort(c)
				if def == nil {
					return nil, &parseError{fmt.Sprintf("Unknown option %s", arg)}
				}
				if !def.hasArg {
					if err := applyFlag(o, def.id); err != nil {
						return nil, err
					}
					continue
				}
				// has arg: take next argv
				if i+1 >= len(args) {
					return nil, &parseError{fmt.Sprintf("Missing argument for -%c", c)}
				}
				val := args[i+1]
				consumedNext = true
				if err := applyArg(o, def, val, "-"+string(c)); err != nil {
					return nil, err
				}
				break // ignore rest of token
			}
			i++
			if consumedNext {
				i++
			}
			continue
		}
		// positional (including "-", "", single dash etc)
		pos = append(pos, arg)
		i++
	}
	o.Positionals = pos
	if o.Invert {
		o.FgColor, o.BgColor = o.BgColor, o.FgColor
		// also swap Set flags? Background color used for blending is now former fg.
		// Mark bg as set if either was set, symmetrical.
		bs, fs := o.BgSet, o.FgSet
		o.BgSet, o.FgSet = fs, bs
	}
	return o, nil
}

func applyFlag(o *Opts, id string) error {
	switch id {
	case "help":
		o.Help = true
	case "version":
		o.Version = true
	case "verbose":
		o.Verbose = true
	case "clear":
		o.Clear = true
	case "fit-width":
		o.FitWidth = true
	case "stretch":
		o.Stretch = true
	case "watch":
		o.Watch = true
	case "invert":
		o.Invert = true
	case "fg-only":
		o.FgOnly = true
	case "grid-auto":
		o.GridAuto = true
		o.GridSet = true
		o.GridDim = Dim{Set: true, W: -1, H: -1} // auto sentinel
	case "label-on":
		o.Label = true
		o.LabelSet = true
	}
	return nil
}

func applyArg(o *Opts, def *optDef, val string, spelling string) error {
	id := def.id
	switch id {
	case "files", "files0":
		o.FilesSpecs = append(o.FilesSpecs, FilesSpec{Path: val, Zero: id == "files0", Order: len(o.FilesSpecs)})
	case "probe":
		low := strings.ToLower(val)
		if low == "auto" {
			o.ProbeStr = val
			return nil
		}
		if b, ok := parseBoolWord(val); ok {
			_ = b
			o.ProbeStr = val
			return nil
		}
		v, ok := parseRealOrFraction(val)
		if !ok || v == 0 || v < 0 {
			// NaN passes as in original (comparisons false)
			if ok && math.IsNaN(v) {
				o.ProbeStr = val
				return nil
			}
			return &parseError{"Probe duration must be a positive real number or one of [on, off, auto]."}
		}
		o.ProbeStr = val
	case "probe-mode":
		switch strings.ToLower(val) {
		case "any", "ctty", "stdio":
			o.ProbeModeStr = strings.ToLower(val)
		default:
			return &parseError{"Probe mode must be one of [any, ctty, stdio]."}
		}
	case "format":
		low := strings.ToLower(val)
		// original accepts prefixes? "symbol" was accepted as symbols. Implement: canonical names with prefix matching?
		// Observed: "SYMBOLS" and "symbol" both OK. Let's accept if low is a prefix of a format name or equals.
		matched := ""
		for _, f := range []string{"iterm", "kitty", "sixels", "symbols"} {
			if low == f || (low != "" && strings.HasPrefix(f, low)) {
				matched = f
				break
			}
		}
		if matched == "" {
			return &parseError{fmt.Sprintf("Output format given as '%s'. Must be one of [iterm, kitty, sixels, symbols].", val)}
		}
		o.FormatStr = matched
		o.FormatSet = true
	case "optimize":
		v, status := parseGLibInt(val)
		if status != 0 {
			return &parseError{intOptionError(o.Prog, spelling, val, status)}
		}
		if v < 0 || v > 9 {
			return &parseError{fmt.Sprintf("Optimization level %d is not in the range [0-9].", v)}
		}
		o.Optimize = int(v)
		o.OptimizeSet = true
	case "relative":
		b, ok := parseBoolWord(val)
		if !ok {
			return &parseError{"Relative positioning must be one of [on, off]."}
		}
		o.Relative = b
	case "passthrough":
		switch strings.ToLower(val) {
		case "auto", "none", "screen", "tmux":
			o.Passthrough = strings.ToLower(val)
		default:
			return &parseError{"Passthrough must be one of [auto, none, screen, tmux]."}
		}
	case "polite":
		b, ok := parseBoolWord(val)
		if !ok {
			return &parseError{"Polite mode must be one of [on, off]."}
		}
		o.Polite = b
	case "align":
		if errStr := validateAlign(val); errStr != "" {
			return &parseError{errStr}
		}
		o.AlignStr = val
	case "exact-size":
		low := strings.ToLower(val)
		if low == "auto" {
			o.ExactSize = "auto"
		} else if b, ok := parseBoolWord(val); ok {
			if b {
				o.ExactSize = "on"
			} else {
				o.ExactSize = "off"
			}
		} else {
			return &parseError{"Exact size selector must be one of [on, off, auto]."}
		}
	case "font-ratio":
		v, ok := parseRealOrFraction(val)
		if !ok || !(v > 0) {
			return &parseError{"Font ratio must be specified as a positive real number or fraction."}
		}
		o.FontRatio = v
	case "grid":
		if strings.ToLower(val) == "auto" {
			o.GridAuto = true
			o.GridSet = true
			o.GridDim = Dim{Set: true, W: -1, H: -1}
			return nil
		}
		d, errStr := parseDimString(val, "Grid size")
		if errStr != "" {
			return &parseError{errStr}
		}
		// Grid "auto" false
		o.GridAuto = false
		o.GridSet = true
		o.GridDim = d
	case "label":
		b, ok := parseBoolWord(val)
		if !ok {
			return &parseError{"Label mode must be one of [on, off]."}
		}
		o.Label = b
		o.LabelSet = true
	case "link":
		low := strings.ToLower(val)
		if low == "auto" {
			o.LinkStr = "auto"
		} else if b, ok := parseBoolWord(val); ok {
			if b {
				o.LinkStr = "on"
			} else {
				o.LinkStr = "off"
			}
		} else {
			return &parseError{"Link mode must be one of [auto, on, off]."}
		}
	case "margin-bottom", "margin-right":
		v, status := parseGLibInt(val)
		if status != 0 {
			return &parseError{intOptionError(o.Prog, spelling, val, status)}
		}
		if id == "margin-bottom" {
			o.MarginBottom = int(v)
		} else {
			o.MarginRight = int(v)
		}
	case "scale":
		if strings.ToLower(val) == "max" {
			o.ScaleMax = true
			o.ScaleSet = true
			o.ScaleStr = val
			return nil
		}
		v, ok := parseRealOrFraction(val)
		if !ok || !(v > 0) {
			return &parseError{"Scale must be specified as a positive real number or fraction."}
		}
		o.ScaleVal = v
		o.ScaleMax = false
		o.ScaleSet = true
		o.ScaleStr = val
	case "size":
		d, errStr := parseDimString(val, "Size")
		if errStr != "" {
			return &parseError{errStr}
		}
		o.SizeDim = d
	case "view-size":
		d, errStr := parseDimString(val, "View size")
		if errStr != "" {
			return &parseError{errStr}
		}
		o.ViewDim = d
	case "animate":
		b, ok := parseBoolWord(val)
		if !ok {
			return &parseError{"Animate mode must be one of [on, off]."}
		}
		o.Animate = b
	case "duration":
		low := strings.ToLower(val)
		if low == "inf" || low == "infinite" {
			o.Duration = math.Inf(1)
			o.DurationSet = true
			return nil
		}
		v, ok := parseRealOrFraction(val)
		if !ok || !(v >= 0) {
			return &parseError{"Duration must be a positive real number or fraction, \"inf\" or \"infinite\"."}
		}
		o.Duration = v
		o.DurationSet = true
	case "speed":
		if strings.ToLower(val) == "max" {
			o.SpeedMax = true
			o.SpeedVal = math.Inf(1)
			o.SpeedStr = val
			return nil
		}
		s := val
		isFPS := false
		low := strings.ToLower(s)
		if strings.HasSuffix(low, "fps") {
			isFPS = true
			s = s[:len(s)-3]
		}
		v, ok := parseCStrtod(strings.TrimSpace(s))
		// speed accepts real only, not fraction: parseCStrtod on "1/2" will fail b/c ParseFloat fails -> ok
		// But our parseCStrtod trims, so "10 fps" after stripping fps leaves "10 " ok.
		if !ok || !(v > 0) {
			return &parseError{"Animation speed must be either \"max\", a real multiplier, or a real framerate followed by \"fps\". It must be greater than zero."}
		}
		o.SpeedFPS = isFPS
		o.SpeedVal = v
		o.SpeedStr = val
	case "bg":
		c, ok := parseColorNameOrHex(val)
		if !ok {
			return &parseError{fmt.Sprintf("Unrecognized background color '%s'.", val)}
		}
		o.BgColor = c
		o.BgSet = true
		o.BgStr = val
	case "fg":
		c, ok := parseColorNameOrHex(val)
		if !ok {
			return &parseError{fmt.Sprintf("Unrecognized foreground color '%s'.", val)}
		}
		o.FgColor = c
		o.FgSet = true
		o.FgStr = val
	case "colors":
		low := strings.ToLower(val)
		// 16-8 accepted as alias to 16/8 in original
		if low == "16-8" {
			low = "16/8"
		}
		switch low {
		case "none", "2", "8", "16/8", "16", "240", "256", "full":
			o.ColorsStr = low
			o.ColorsSet = true
		default:
			return &parseError{"Colors must be one of [none, 2, 8, 16/8, 16, 240, 256, full]."}
		}
	case "color-extractor":
		switch strings.ToLower(val) {
		case "average", "median":
			o.ColorExtractor = strings.ToLower(val)
		default:
			return &parseError{"Color extractor must be one of [average, median]."}
		}
	case "color-space":
		switch strings.ToLower(val) {
		case "rgb", "din99d":
			o.ColorSpace = strings.ToLower(val)
		default:
			return &parseError{"Color space must be one of [rgb, din99d]."}
		}
	case "dither":
		switch strings.ToLower(val) {
		case "none", "ordered", "diffusion", "noise":
			o.DitherStr = strings.ToLower(val)
		default:
			return &parseError{"Dither must be one of [none, ordered, diffusion, noise]."}
		}
	case "dither-grain":
		d, errStr := parseDimString(val, "Grain")
		if errStr != "" {
			return &parseError{errStr}
		}
		// grain: width required; if only width, height = width
		if !d.HasW {
			return &parseError{"Grain size must be specified as [width]x[height] or [dim], e.g. 8x4 or 4."}
		}
		if !d.HasH {
			d.H = d.W
			d.HasH = true
		}
		if !isGrainDim(d.W) || !isGrainDim(d.H) {
			return &parseError{"Grain dimensions must be exactly 1, 2, 4 or 8."}
		}
		o.DitherGrain = d
	case "dither-intensity":
		v, ok := parseRealOrFraction(val)
		if !ok || v < 0 || math.IsNaN(v) {
			return &parseError{"Dither intensity must be a positive real number or fraction."}
		}
		o.DitherIntensity = v
	case "preprocess":
		b, ok := parseBoolWord(val)
		if !ok {
			return &parseError{"Preprocessing must be one of [on, off]."}
		}
		o.Preprocess = b
		o.PreprocessSet = true
	case "threshold":
		v, ok := parseRealOrFraction(val)
		if !ok || !(v >= 0 && v <= 1) {
			return &parseError{"Opacity threshold must be a real number or fraction in the range [0.0-1.0]."}
		}
		o.Threshold = v
		o.ThresholdSet = true
	case "threads":
		v, status := parseGLibInt(val)
		if status != 0 {
			return &parseError{intOptionError(o.Prog, spelling, val, status)}
		}
		o.Threads = int(v)
		o.ThreadsSet = true
	case "work":
		v, status := parseGLibInt(val)
		if status != 0 {
			return &parseError{intOptionError(o.Prog, spelling, val, status)}
		}
		if v < 1 || v > 9 {
			return &parseError{"Work factor must be in the range [1-9]."}
		}
		o.Work = int(v)
	case "fill":
		if errStr := validateSymbolSpec(val); errStr != "" {
			return &parseError{errStr}
		}
		o.FillSpecs = append(o.FillSpecs, val)
	case "symbols":
		if errStr := validateSymbolSpec(val); errStr != "" {
			return &parseError{errStr}
		}
		o.SymbolSpecs = append(o.SymbolSpecs, val)
	case "glyph-file":
		if !isValidGlyphFile(val) {
			return &parseError{fmt.Sprintf("Unable to load glyph file '%s'.", val)}
		}
		o.GlyphFile = val
	}
	return nil
}

func isGrainDim(v int) bool { return v == 1 || v == 2 || v == 4 || v == 8 }

func validateAlign(val string) string {
	if val == "" {
		return ""
	}
	parts := strings.Split(val, ",")
	if len(parts) > 2 {
		return fmt.Sprintf("Too many alignment specifiers in \"%s\". Must be at most two.", val)
	}
	for _, p := range parts {
		low := strings.ToLower(p)
		switch low {
		case "top", "bottom", "left", "right", "mid", "center":
		default:
			return fmt.Sprintf("Unknown alignment specifier \"%s\".", p)
		}
	}
	return ""
}

func isValidGlyphFile(path string) bool {
	data, err := os.ReadFile(path)
	if err != nil || len(data) < 4 {
		return false
	}
	// TTF / OTF / TTC / PCF sniffing
	if len(data) >= 4 {
		if data[0] == 0x00 && data[1] == 0x01 && data[2] == 0x00 && data[3] == 0x00 {
			return true
		}
		s := string(data[:4])
		if s == "OTTO" || s == "true" || s == "ttcf" || s == "\x01\xf6\x86\x81" {
			return true
		}
		if strings.HasPrefix(string(data), "\x01PCF") || strings.Contains(string(data[:min(64, len(data))]), "PCF") {
			_ = filepath.Base
			return true
		}
		// FreeType can load other formats (BDF, etc). Accept if it looks like BDF
		if strings.HasPrefix(string(data), "STARTFONT") {
			return true
		}
	}
	return false
}

func min(a, b int) int { if a < b { return a }; return b }
