type parseError struct{ msg string }

func (e *parseError) Error() string { return e.msg }

// option spec for parser
type optDef struct {
	long  string
	short byte // 0 if none
	hasArg bool
	// kind handler id
	id string
}

var optDefs = []optDef{
	{"files", 0, true, "files"},
