	return ss
}

// candidate list sorted: space first, then by coverage ascending, then by insertion order (stable)
func (ss *SymbolSet) candidates() []*Symbol {
	var out []*Symbol
	for _, s := range ss.set {
		out = append(out, s)
	}
	// Use master order as tie breaker
	order := make(map[rune]int)
	for i, s := range masterSymbols {
		order[s.Ch] = i
	}
	sort.SliceStable(out, func(i, j int) bool {
		a, b := out[i], out[j]
		if (a.Ch == ' ') != (b.Ch == ' ') {
			return a.Ch == ' '
		}
		if math.Abs(a.Coverage-b.Coverage) > 1e-9 {
			return a.Coverage < b.Coverage
		}
		return order[a.Ch] < order[b.Ch]
	})
	return out
}
