{"command":"cat > symbols.go <<'GO'
package main

import (
	"fmt"
	"math"
	"sort"
	"strings"
)

type Symbol struct {
	Ch       rune
	Cov      [64]float64 // 0..1 row major 8x8
	Tags     map[string]bool
	Coverage float64
}

func (s *Symbol) computeCoverage() {
	sum := 0.0
	for _, v := range s.Cov {
		sum += v
	}
	s.Coverage = sum / 64.0
}

var masterSymbols []*Symbol
var symbolsByChar map[rune]*Symbol

func addSymbol(ch rune, cov [64]float64, tags ...string) *Symbol {
	if symbolsByChar == nil {
		symbolsByChar = make(map[rune]*Symbol)
	}
	if existing, ok := symbolsByChar[ch]; ok {
		for _, t := range tags {
			existing.Tags[t] = true
		}
		return existing
	}
	s := &Symbol{Ch: ch, Cov: cov, Tags: make(map[string]bool)}
	for _, t := range tags {
		s.Tags[t] = true
	}
	s.Tags["all"] = true
	s.computeCoverage()
	masterSymbols = append(masterSymbols, s)
	symbolsByChar[ch] = s
	return s
}

func covFromFunc(fn func(x, y float64) bool) [64]float64 {
	var cov [64]float64
	const SS = 4
	for cy := 0; cy < 8; cy++ {
		for cx := 0; cx < 8; cx++ {
			cnt := 0
			for sy := 0; sy < SS; sy++ {
				for sx := 0; sx < SS; sx++ {
					x := (float64(cx) + (float64(sx)+0.5)/SS) / 8.0
					y := (float64(cy) + (float64(sy)+0.5)/SS) / 8.0
					if fn(x, y) {
						cnt++
					}
				}
			}
			cov[cy*8+cx] = float64(cnt) / (SS * SS)
		}
	}
	return cov
}

func covRect(x0, y0, x1, y1 float64) [64]float64 {
	return covFromFunc(func(x, y float64) bool { return x >= x0 && x < x1 && y >= y0 && y < y1 })
}

func covBitmap(b [64]bool) [64]float64 {
	// blur binary bitmap a little to get grey edge coverage, as in anti-aliased glyphs
	var cov [64]float64
	kernel := [3][3]float64{{1, 2, 1}, {2, 4, 2}, {1, 2, 1}}
	for y := 0; y < 8; y++ {
		for x := 0; x < 8; x++ {
			sum := 0.0
			ksum := 0.0
			for dy := -1; dy <= 1; dy++ {
				for dx := -1; dx <= 1; dx++ {
					nx, ny := x+dx, y+dy
					if nx < 0 || nx >= 8 || ny < 0 || ny >= 8 {
						continue
					}
					w := kernel[dy+1][dx+1]
					ksum += w
					if b[ny*8+nx] {
						sum += w
					}
				}
			}
			if ksum > 0 {
				cov[y*8+x] = sum / ksum
				// Preserve strong interior: if original pixel set, boost a bit
				if b[y*8+x] {
					// A fully surrounded pixel stays 1; edge pixels keep blurred value but at least 0.6
					if cov[y*8+x] < 0.6 {
						cov[y*8+x] = 0.6 + 0.4*cov[y*8+x]
					}
				}
			}
		}
	}
	return cov
}

func initSymbols() {
	if masterSymbols != nil {
		return
	}
	symbolsByChar = make(map[rune]*Symbol)
	// Space first (important for tie-breaking)
	addSymbol(' ', [64]float64{}, "space", "ascii", "narrow")
	buildASCII()
	buildBlocks()
	buildBorder()
	buildBraille()
	buildSextantsAndLegacy()
	buildGeometric()
	buildExtraTechnical()
	// sort master? Keep insertion order; space first, then ASCII, blocks, etc.
	// SymbolsByChar already populated.
}

var tagNames = []string{
	"all", "ascii", "braille", "extra", "imported", "narrow", "solid", "ugly",
	"alnum", "bad", "diagonal", "geometric", "inverted", "none", "space", "vhalf",
	"alpha", "block", "digit", "half", "latin", "quad", "stipple", "wedge",
	"ambiguous", "border", "dot", "hhalf", "legacy", "sextant", "technical", "wide",
}

// tag priority for prefix matching (first tag in this list wins if multiple)
var tagPriority = []string{
	"all", "block", "space", "none", "ascii", "alpha", "alnum", "ambiguous",
	"border", "braille", "bad", "diagonal", "dot", "digit", "extra", "geometric",
	"hhalf", "half", "inverted", "imported", "legacy", "latin", "narrow", "quad",
	"sextant", "solid", "stipple", "technical", "ugly", "vhalf", "wedge", "wide",
}

func lookupTagPrefix(word string) (string, bool) {
	// exact
	for _, t := range tagNames {
		if t == word {
			return t, true
		}
	}
	for _, t := range tagPriority {
		if strings.HasPrefix(t, word) {
			return t, true
		}
	}
	return "", false
}

// Validator and parser for symbol specs.
// Returns error message (without prog prefix) or ""
func validateSymbolSpec(spec string) string {
	_, errStr := parseSymbolSpecTokens(spec)
	return errStr
}

type symToken struct {
	sign   byte // '+', '-', or 0 for bare
	word   string
}

func parseSymbolSpecTokens(spec string) ([]symToken, string) {
	// Lowercase for processing, but words may include hex digits etc.
	s := spec
	var tokens []symToken
	i := 0
	first := true
	_ = first
	for {
		// skip spaces and commas
		for i < len(s) && (s[i] == ' ' || s[i] == ',') {
			i++
		}
		if i >= len(s) {
			break
		}
		var sign byte = 0
		if s[i] == '+' || s[i] == '-' {
			sign = s[i]
			i++
			// skip spaces/commas after sign
			for i < len(s) && (s[i] == ' ' || s[i] == ',') {
				i++
			}
			if i >= len(s) {
				break
			}
			if s[i] == '+' || s[i] == '-' {
				return nil, "Syntax error in symbol tag selectors."
			}
		}
		// read a word: characters allowed are alnum and '.' ; other chars -> syntax error
		start := i
		for i < len(s) {
			c := s[i]
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' {
				i++
			} else {
				break
			}
		}
		if start == i {
			return nil, "Syntax error in symbol tag selectors."
		}
		word := s[start:i]
		// classify word: must be either tag-prefix (letters only) or hex/range or tag-ish
		// We'll defer detailed classification: if classify fails, error mentions word
		if _, _, ok := classifyWord(word); !ok {
			// Original uses the word as-is in message, preserving case? It lowercases? Input "Block" worked; error for "foo" lower.
			// For errors, use original word substring
			return nil, fmt.Sprintf("Unrecognized symbol tag '%s'.", word)
		}
		tokens = append(tokens, symToken{sign: sign, word: word})
		// After a word, next char if present must be '+','-',' ',',' or end; otherwise syntax error
		if i < len(s) {
			c := s[i]
			if c != '+' && c != '-' && c != ' ' && c != ',' {
				return nil, "Syntax error in symbol tag selectors."
			}
		}
	}
	_ = sort.StringSlice{}
	return tokens, ""
}

// classify a word: returns kind: "tag" with tag name, or "codepoints" with list, or not ok
func classifyWord(word string) (string, []rune, bool) {
	low := strings.ToLower(word)
	// tag if all letters and a tag prefix match
	allLetters := true
	for _, c := range low {
		if c < 'a' || c > 'z' {
			allLetters = false
			break
		}
	}
	if allLetters {
		if tag, ok := lookupTagPrefix(low); ok {
			return tag, nil, true
		}
		// fall through to hex attempt (e.g. "dead", "face")
	}
	// hex / range attempt
	if cps, ok := parseCodepointWord(low); ok {
		return "codepoints", cps, true
	}
	return "", nil, false
}

func parseCodepointWord(low string) ([]rune, bool) {
	// forms: hex, 0xhex, hex..hex, 0xhex..0xhex
	parseHex := func(t string) (rune, bool) {
		t = strings.TrimPrefix(t, "0x")
		if t == "" {
			return 0, false
		}
		var v int
		for _, c := range t {
			var d int
			switch {
			case c >= '0' && c <= '9':
				d = int(c - '0')
			case c >= 'a' && c <= 'f':
				d = int(c-'a') + 10
			default:
				return 0, false
			}
			v = v*16 + d
			if v > 0x10FFFF {
				// still a codepoint? clamp fail
				// allow big but no symbol
			}
		}
		return rune(v), true
	}
	if strings.Contains(low, "..") {
		parts := strings.Split(low, "..")
		if len(parts) != 2 {
			return nil, false
		}
		lo, ok1 := parseHex(parts[0])
		hi, ok2 := parseHex(parts[1])
		if !ok1 || !ok2 || hi < lo || hi-lo > 4096 {
			return nil, false
		}
		var out []rune
		for r := lo; r <= hi; r++ {
			out = append(out, r)
		}
		return out, true
	}
	if strings.Contains(low, ".") {
		return nil, false
	}
	if r, ok := parseHex(low); ok {
		// Must contain at least one digit or 0x prefix? Words like "face" are hex too, allowed.
		// But purely letter words that are not tags were already attempted; hex parsing them is fine.
		// Prevent treating ordinary unknown words like "x" as hex: 'x' isn't hex digit, parseHex will fail because
		// 'x' not handled after trimming 0x (it expects digits). Good.
		return []rune{r}, true
	}
	return nil, false
}

type SymbolSet struct {
	set map[rune]*Symbol
}

func newSymbolSet() *SymbolSet { return &SymbolSet{set: make(map[rune]*Symbol)} }
func (ss *SymbolSet) clear() { ss.set = make(map[rune]*Symbol) }
func (ss *SymbolSet) add(sym *Symbol) {
	if sym == nil {
		return
	}
	ss.set[sym.Ch] = sym
}
func (ss *SymbolSet) addTag(tag string) {
	if tag == "none" {
		return
	}
	if tag == "all" {
		for _, s := range masterSymbols {
			ss.add(s)
		}
		return
	}
	for _, s := range masterSymbols {
		if s.Tags[tag] {
			ss.add(s)
		}
	}
}
func (ss *SymbolSet) removeTag(tag string) {
	if tag == "none" {
		return
	}
	if tag == "all" {
		ss.clear()
		return
	}
	for _, s := range masterSymbols {
		if s.Tags[tag] {
			delete(ss.set, s.Ch)
		}
	}
}
func (ss *SymbolSet) addCodepoints(cps []rune) {
	for _, cp := range cps {
		if sym, ok := symbolsByChar[cp]; ok {
			ss.add(sym)
		} else if cp >= 32 && cp != 127 {
			// create a generic symbol for a printable codepoint if we can make a bitmap
			sym := makeGenericSymbol(cp)
			if sym != nil {
				ss.add(sym)
			}
		}
	}
}
func (ss *SymbolSet) removeCodepoints(cps []rune) {
	for _, cp := range cps {
		delete(ss.set, cp)
	}
}

func makeGenericSymbol(cp rune) *Symbol {
	// For letters/digits etc not in master, make a symbol using ASCII-like bitmap if possible.
	// We can reuse a representative glyph: letters -> use pattern based on cp category
	// Simplify: Use full-ish pattern based on hash to differentiate? Use 'A' pattern for letters.
	if cp < 128 {
		return nil
	}
	// Use a generic coverage: border-ish based on codepoint
	var cov [64]float64
	// Use character's unicode category approximation: create a pattern from codepoint bits (deterministic)
	for i := 0; i < 64; i++ {
		if (int(cp)>>(uint(i%7)))&1 == 1 && i%3 == 0 {
			cov[i] = 1
		}
	}
	s := &Symbol{Ch: cp, Cov: cov, Tags: map[string]bool{"all": true}}
	s.computeCoverage()
	return s
}

// Apply a single --symbols or --fill spec to a set. firstBare resets.
func applySymbolSpec(ss *SymbolSet, spec string) {
	tokens, errStr := parseSymbolSpecTokens(spec)
	if errStr != "" {
		return // validated earlier; ignore
	}
	for idx, tok := range tokens {
		kind, cps, _ := classifyWord(strings.ToLower(tok.word))
		isTag := kind != "codepoints"
		if idx == 0 && tok.sign == 0 {
			// bare first selector resets
			ss.clear()
		}
		sign := tok.sign
		if sign == 0 {
			sign = '+'
		}
		if sign == '-' {
			if isTag {
				ss.removeTag(kind)
			} else {
				ss.removeCodepoints(cps)
			}
		} else {
			if isTag {
				ss.addTag(kind)
			} else {
				ss.addCodepoints(cps)
			}
		}
		_ = math.MaxInt
	}
}

// Build default symbol set for a given terminal symbol mode: "ascii" or "block"
func defaultSymbolSet(mode string) *SymbolSet {
	initSymbols()
	ss := newSymbolSet()
	if mode == "block" {
		ss.addTag("block")
		ss.addTag("border")
		// ensure space included
		if s, ok := symbolsByChar[' ']; ok {
			ss.add(s)
		}
	} else {
		ss.addTag("ascii")
	}
	return ss
}

func symbolSetFromSpecs(specs []string, defaultMode string) *SymbolSet {
	initSymbols()
	ss := defaultSymbolSet(defaultMode)
	for _, spec := range specs {
		applySymbolSpec(ss, spec)
	}
	return ss
}

func fillSymbolSetFromSpecs(specs []string) *SymbolSet {
	initSymbols()
	ss := newSymbolSet()
	for _, spec := range specs {
		applySymbolSpec(ss, spec)
	}
	return ss
}

// candidate list sorted: space first, then by coverage ascending, then by insertion order (stable)
func (ss *SymbolSet) candidates() []*Symbol {
	var out []*Symbol
	for _, s := range ss.set {
		out = append(out, s)
	}
	// Use master order as tie breaker
	order := make(map[rune]int)
	for i, s := range masterSymbols {
		order[s.Ch] = i
	}
	sort.SliceStable(out, func(i, j int) bool {
		a, b := out[i], out[j]
		if (a.Ch == ' ') != (b.Ch == ' ') {
			return a.Ch == ' '
		}
		if math.Abs(a.Coverage-b.Coverage) > 1e-9 {
			return a.Coverage < b.Coverage
		}
		return order[a.Ch] < order[b.Ch]
	})
	return out
}
