func covFrom5x7(pat []string, lower bool) [64]float64 {
	var b [64]bool
	yoff := 0
	if lower {
		yoff = 1
	}
	for y := 0; y < 7 && y+yoff < 8; y++ {
		row := pat[y]
		for x := 0; x < 5 && x < len(row); x++ {
			if row[x] == '#' {
				// place at columns 1..5
				b[(y+yoff)*8+(x+1)] = true
			}
		}
	}
	return covBitmap(b)
}

func buildASCII() {
	for r := rune(32); r <= 126; r++ {
		if r == ' ' {
			continue
		}
		tags := []string{"ascii", "narrow"}
		if r >= 'A' && r <= 'Z' || r >= 'a' && r <= 'z' {
			tags = append(tags, "alpha", "latin", "alnum")
		}
		if r >= '0' && r <= '9' {
			tags = append(tags, "digit", "alnum")
		}
		if r == '.' || r == ',' || r == ':' || r == ';' {
			tags = append(tags, "dot")
		}
		var cov [64]float64
		if pat, ok := font5x7[r]; ok {
			cov = covFrom5x7(pat, false)
		} else if r >= 'a' && r <= 'z' {
			up := r - 'a' + 'A'
			if pat, ok := font5x7[up]; ok {
				cov = covFrom5x7(pat, true)
			}
		} else {
			// generic pattern
			cov = covFromFunc(func(x, y float64) bool { return x > 0.3 && x < 0.7 && y > 0.3 && y < 0.7 })
