		'α': "A", 'β': "B", 'γ': "G", 'δ': "D", 'ε': "E", 'λ': "L", 'μ': "M", 'π': "P", 'σ': "S", 'τ': "T", 'φ': "F", 'ω': "O",
		'А': "A", 'В': "B", 'С': "C", 'Е': "E", 'К': "K", 'М': "M", 'Н': "H", 'О': "O", 'Р': "P", 'Т': "T", 'Х': "X",
		'а': "A", 'е': "E", 'о': "O", 'р': "P", 'с': "C", 'х': "X",
	}
	for ch, baseStr := range extra {
		base := []rune(baseStr)[0]
		if pat, ok := font5x7[base]; ok {
			isLower := ch > 127 && strings.ToLower(string(ch)) == string(ch) && strings.ToUpper(string(ch)) != string(ch)
			cov := covFrom5x7(pat, isLower)
			addSymbol(ch, cov, "alpha", "latin", "alnum", "narrow", "ambiguous")
