	add('▔', covRect(0, 0, 1, 0.125), "block", "narrow")
	add('▕', covRect(0.875, 0, 1, 1), "block", "narrow")
	// quadrants
	q := func(ch rune, ul, ur, ll, lr bool) {
		cov := covFromFunc(func(x, y float64) bool {
			left := x < 0.5
			top := y < 0.5
			if top && left { return ul }
			if top && !left { return ur }
			if !top && left { return ll }
			return lr
		})
		addSymbol(ch, cov, "block", "quad", "narrow")
	}
	q('▖', false, false, true, false)
	q('▗', false, false, false, true)
