	q('▛', true, true, true, false)
	q('▜', true, true, false, true)
	q('▟', false, true, true, true)
	q('▛', true, true, true, false)
	// shades (stipple)
	shade := func(ch rune, pattern int) {
		cov := covFromFunc(func(x, y float64) bool {
			ix := int(x * 4)
			iy := int(y * 4)
			switch pattern {
			case 0: // light ~25%
				return (ix+iy)%4 == 0
			case 1: // medium 50% checker
				return (ix+iy)%2 == 0
			default: // dark 75%
				return (ix+iy)%4 != 0
			}
		})
		addSymbol(ch, cov, "block", "stipple", "narrow")
	}
	shade('░', 0)
	shade('▒', 1)
	shade('▓', 2)
	// stipple additional: use shade chars already.
}

func buildBorder() {
	type arm struct{ up, down, left, right bool }
	thick := 0.18
	mk := func(a arm, heavy bool) [64]float64 {
		w := 0.12
		if heavy {
			w = 0.22
		}
		_ = thick
		return covFromFunc(func(x, y float64) bool {
			inH := y > 0.5-w && y < 0.5+w
			inV := x > 0.5-w && x < 0.5+w
			res := false
			if a.left && inH && x < 0.5 { res = true }
			if a.right && inH && x >= 0.5 { res = true }
			if a.up && inV && y < 0.5 { res = true }
			if a.down && inV && y >= 0.5 { res = true }
			// centre square
			if (a.left || a.right) && (a.up || a.down) && inH && inV { res = true }
			return res
		})
	}
	add := func(ch rune, a arm, heavy bool, extra ...string) {
		tags := []string{"border", "narrow"}
		tags = append(tags, extra...)
		addSymbol(ch, mk(a, heavy), tags...)
	}
	add('─', arm{left: true, right: true}, false)
	add('━', arm{left: true, right: true}, true)
	add('│', arm{up: true, down: true}, false)
	add('┃', arm{up: true, down: true}, true)
	add('┌', arm{down: true, right: true}, false)
	add('┐', arm{down: true, left: true}, false)
	add('└', arm{up: true, right: true}, false)
	add('┘', arm{up: true, left: true}, false)
	add('┏', arm{down: true, right: true}, true)
	add('┓', arm{down: true, left: true}, true)
	add('┗', arm{up: true, right: true}, true)
	add('┛', arm{up: true, left: true}, true)
	add('├', arm{up: true, down: true, right: true}, false)
	add('┤', arm{up: true, down: true, left: true}, false)
	add('┬', arm{left: true, right: true, down: true}, false)
	add('┴', arm{left: true, right: true, up: true}, false)
	add('┼', arm{up: true, down: true, left: true, right: true}, false)
	add('┝', arm{up: true, down: true, right: true}, true)
	add('┥', arm{up: true, down: true, left: true}, true)
	add('┯', arm{left: true, right: true, down: true}, true)
	add('┷', arm{left: true, right: true, up: true}, true)
	add('╋', arm{up: true, down: true, left: true, right: true}, true)
	add('╔', arm{down: true, right: true}, true)
	add('╗', arm{down: true, left: true}, true)
	add('╚', arm{up: true, right: true}, true)
	add('╝', arm{up: true, left: true}, true)
	add('╠', arm{up: true, down: true, right: true}, true)
	add('╣', arm{up: true, down: true, left: true}, true)
	add('╦', arm{left: true, right: true, down: true}, true)
	add('╩', arm{left: true, right: true, up: true}, true)
	add('╬', arm{up: true, down: true, left: true, right: true}, true)
	add('═', arm{left: true, right: true}, true)
	add('║', arm{up: true, down: true}, true)
	// half lines
	add('╴', arm{left: true}, false)
	add('╵', arm{up: true}, false)
	add('╶', arm{right: true}, false)
	add('╷', arm{down: true}, false)
	add('╸', arm{left: true}, true)
	add('╹', arm{up: true}, true)
	add('╺', arm{right: true}, true)
	add('╻', arm{down: true}, true)
	// diagonals
	diag := func(ch rune, kind int) {
		cov := covFromFunc(func(x, y float64) bool {
			switch kind {
			case 0: // ╱  ( / )
				d := (1 - x) - y // line from bottom-left to top-right: x + y =1? Wait shape: ╱ goes from bottom left to top right
				_ = d
				return absf((x+y)-1.0) < 0.18 // that is anti-diagonal? Use as approx
			case 1: // ╲
				return absf(x-y) < 0.18
			default: // ╳
				return absf(x-y) < 0.18 || absf((x+y)-1.0) < 0.18
			}
		})
		addSymbol(ch, cov, "border", "diagonal", "narrow")
	}
	diag('╱', 0)
	diag('╲', 1)
	diag('╳', 2)
}

func absf(v float64) float64 { if v < 0 { return -v }; return v }

func buildBraille() {
	// bit mapping for braille dots: dot positions in unicode encoding
	// Unicode: bit0 dot1 (row0 left), bit1 dot2 (row1 left), bit2 dot3 (row2 left), bit3 dot7 (row3 left)
	// bit4 dot4 (row0 right), bit5 dot5, bit6 dot6, bit7 dot8
	for code := 0; code < 256; code++ {
		ch := rune(0x2800 + code)
		cov := covFromFunc(func(x, y float64) bool {
			col := 0
			if x >= 0.5 { col = 1 }
			row := int(y * 4)
			if row > 3 { row = 3 }
			var bit int
			if col == 0 {
				if row == 3 { bit = 3 } else { bit = row } // dot1,2,3,7
			} else {
				if row == 3 { bit = 7 } else { bit = 4 + row } // dot4,5,6,8
			}
			return (code>>uint(bit))&1 == 1
		})
		addSymbol(ch, cov, "braille", "narrow")
	}
}

var sextantSubsets = []string{"1","2","12","3","13","23","123","4","14","24","124","34","134","234","1234","5","15","25","125","35","235","1235","45","145","245","1245","345","1345","2345","12345","6","16","26","126","36","136","236","1236","46","146","1246","346","1346","2346","12346","56","156","256","1256","356","1356","2356","12356","456","1456","2456","12456","3456","13456","23456"}

func buildSextantsAndLegacy() {
	// Map subset string (digits are sextant numbers Row-major: 1 LT,2 RT,3 LM,4 RM,5 LB,6 RB)
	// Need convert our geometric positions: Row major: cells: (0,0)=1,(1,0)=2,(0,1)=3,(1,1)=4,(0,2)=5,(1,2)=6
	for idx, subset := range sextantSubsets {
		ch := rune(0x1FB00 + idx)
		set := make(map[int]bool)
		for _, d := range subset { set[int(d-'0')] = true }
		cov := covFromFunc(func(x, y float64) bool {
			col := 0
			if x >= 0.5 { col = 1 }
			row := int(y * 3)
			if row > 2 { row = 2 }
			num := row*2 + col + 1
			return set[num]
		})
		addSymbol(ch, cov, "sextant", "legacy", "narrow")
	}
	// Wedges / triangular legacy 1FB68 onward
	tri := func(ch rune, pts [][2]float64, tags ...string) {
		cov := covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, pts) })
		addSymbol(ch, cov, tags...)
	}
	// triangular three quarters etc.
	tri('🭨', [][2]float64{{0,0},{1,0},{1,1}}, "wedge", "legacy", "narrow") // approx upper+right+lower? Actually polygon covering all but lower left triangle
	// Better: shapes are cell minus a triangle. Use explicit functions via addSymbol with covFromFunc
	addSymbol('🭩', covFromFunc(func(x, y float64) bool { return !(x < 0.5 && y > 0.5 && (y-0.5) > x) }), "wedge", "legacy", "narrow")
	// Quarter triangles
	tri('🭬', [][2]float64{{0,0},{0,1},{1,1}}, "wedge", "legacy", "narrow")
	tri('🭭', [][2]float64{{0,0},{1,0},{0,1}}, "wedge", "legacy", "narrow")
	tri('🭮', [][2]float64{{0,0},{1,0},{1,1}}, "wedge", "legacy", "narrow")
	tri('🭯', [][2]float64{{1,0},{1,1},{0,1}}, "wedge", "legacy", "narrow")
	// diagonals legacy misc (1FB3C ...) approximate with diagonal strips
	for ch := rune(0x1FB3C); ch <= 0x1FB67; ch++ {
		// assign a diagonal triangle pattern deterministically based on offset - gives shapes similar to wedges
		offset := int(ch - 0x1FB3C)
		cov := covFromFunc(func(x, y float64) bool {
			// vary triangles
			switch offset % 4 {
			case 0: return x + y < 1.0
			case 1: return x + y > 1.0
			case 2: return x > y
			default: return x < y
			}
		})
		addSymbol(ch, cov, "legacy", "wedge", "diagonal", "narrow")
	}
}

func pointInPolygon(x, y float64, pts [][2]float64) bool {
	inside := false
	n := len(pts)
	for i, j := 0, n-1; i < n; j = i, i++ {
		xi, yi := pts[i][0], pts[i][1]
		xj, yj := pts[j][0], pts[j][1]
		if (yi > y) != (yj > y) {
			xInt := (xj-xi)*(y-yi)/(yj-yi) + xi
			if x < xInt { inside = !inside }
		}
	}
	return inside
}

func buildGeometric() {
	add := func(ch rune, cov [64]float64, tags ...string) { addSymbol(ch, cov, tags...) }
	// squares
	add('■', covRect(0.1, 0.1, 0.9, 0.9), "geometric", "solid", "narrow")
	add('□', covFromFunc(func(x, y float64) bool { return (x>0.1 && x<0.9 && y>0.1 && y<0.9) && !(x>0.25 && x<0.75 && y>0.25 && y<0.75) }), "geometric", "narrow")
	add('▮', covRect(0.15, 0.05, 0.85, 0.95), "geometric", "dot", "narrow")
	add('▯', covRect(0.15, 0.05, 0.4, 0.95), "geometric", "narrow")
	add('▲', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0.5, 0.05}, {0.95, 0.9}, {0.05, 0.9}}) }), "geometric", "wedge", "bad", "ambiguous", "narrow")
	add('▼', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0.05, 0.1}, {0.95, 0.1}, {0.5, 0.95}}) }), "geometric", "wedge", "bad", "ambiguous", "narrow")
	add('◀', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0.9, 0.05}, {0.9, 0.95}, {0.05, 0.5}}) }), "geometric", "wedge", "bad", "ambiguous", "narrow")
	add('▶', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0.1, 0.05}, {0.1, 0.95}, {0.95, 0.5}}) }), "geometric", "wedge", "bad", "ambiguous", "narrow")
	add('●', covFromFunc(func(x, y float64) bool { dx:=x-0.5; dy:=y-0.5; return dx*dx+dy*dy < 0.18 }), "geometric", "dot", "narrow")
	add('○', covFromFunc(func(x, y float64) bool { dx:=x-0.5; dy:=y-0.5; d:=dx*dx+dy*dy; return d < 0.20 && d > 0.08 }), "geometric", "dot", "narrow")
	add('◆', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0.5,0.05},{0.95,0.5},{0.5,0.95},{0.05,0.5}}) }), "geometric", "narrow")
	add('◢', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0,1},{1,1},{1,0}}) }), "geometric", "wedge", "diagonal", "narrow")
	add('◣', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0,0},{0,1},{1,1}}) }), "geometric", "wedge", "diagonal", "narrow")
	add('◤', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0,0},{1,0},{0,1}}) }), "geometric", "wedge", "diagonal", "narrow")
	add('◥', covFromFunc(func(x, y float64) bool { return pointInPolygon(x, y, [][2]float64{{0,0},{1,0},{1,1}}) }), "geometric", "wedge", "diagonal", "narrow")
	// small dot symbols
	add('·', covFromFunc(func(x, y float64) bool { dx:=x-0.5; dy:=y-0.5; return dx*dx+dy*dy < 0.02 }), "dot", "narrow", "ascii")
	add('•', covFromFunc(func(x, y float64) bool { dx:=x-0.5; dy:=y-0.5; return dx*dx+dy*dy < 0.05 }), "dot", "narrow")
	add('∙', covFromFunc(func(x, y float64) bool { dx:=x-0.5; dy:=y-0.5; return dx*dx+dy*dy < 0.01 }), "dot", "narrow")
	// inverted: symbols that are blocks with inverted halves etc - approximate using existing chars tagged inverted
	for _, ch := range []rune{'▔','▁','▂','▃','▄','▅','▆','▇','🮋','🮊','🮌','🮍'} {
		cov := covRect(0, 0, 1, 0.25)
		// reuse real cov if char exists, else create
		if s, ok := symbolsByChar[ch]; ok {
			s.Tags["inverted"] = true
		} else {
			addSymbol(ch, cov, "inverted", "narrow")
		}
	}
	// wedge standard triangles already added; ensure wedge includes them.
	// Wide symbols: a few Japanese kana (wide). Represent with generic patterns tagged wide (and not narrow)
	wideChars := []rune{'あ','い','う','え','お','か','き','く','け','こ','さ','し','す','せ','そ','た','ち','つ','て','と','な','に','ぬ','ね','の','日','本','語','漢','字','Ａ','Ｂ','Ｃ','１','２','３'}
	for idx, ch := range wideChars {
		cov := covFromFunc(func(x, y float64) bool {
			// pseudo pattern based on index
			return ((int(x*8)+int(y*8)+idx)%3 == 0) || (x > 0.2 && x < 0.8 && y > 0.2 && y < 0.8 && (idx%2==0))
		})
		s := addSymbol(ch, cov, "wide")
		// wide symbols are not narrow; addSymbol merged may have narrow from elsewhere, ensure delete
		delete(s.Tags, "narrow")
	}
	// Ensure narrow tag for most non-wide symbols: already assigned in many; add narrow to those lacking and not wide
	for _, s := range masterSymbols {
		if !s.Tags["wide"] {
			// many symbols built with narrow already; add if it's a typical char
			if _, ok := s.Tags["narrow"]; !ok {
				// do not arbitrarily add? Original narrow includes most single-width symbols.
				s.Tags["narrow"] = true
			}
		}
	}
}

