}

func decodeQOI(data []byte) (*Frame, error) {
	if len(data) < 14 { return nil, errors.New("bad qoi") }
	w := int(data[4])<<24 | int(data[5])<<16 | int(data[6])<<8 | int(data[7])
	h := int(data[8])<<24 | int(data[9])<<16 | int(data[10])<<8 | int(data[11])
	channels := data[12]
	if w <= 0 || h <= 0 || w*h > 100_000_000 { return nil, errors.New("bad qoi size") }
	px := make([]RGBA, w*h)
	var cur RGBA = RGBA{0,0,0,255}
	var index [64]RGBA
	pos := 14
	run := 0
	for i := 0; i < w*h; i++ {
		if run > 0 {
			run--
			px[i] = cur
			continue
		}
		if pos >= len(data) { return nil, errors.New("truncated qoi") }
		b1 := data[pos]; pos++
		if b1 == 0xFE { // RGB
			if pos+2 >= len(data) { return nil, errors.New("trunc") }
			cur.R, cur.G, cur.B = data[pos], data[pos+1], data[pos+2]; pos+=3
			if channels == 4 { cur.A = 255 }
		} else if b1 == 0xFF { // RGBA
			if pos+3 >= len(data) { return nil, errors.New("trunc") }
			cur.R, cur.G, cur.B, cur.A = data[pos], data[pos+1], data[pos+2], data[pos+3]; pos+=4
		} else if b1 & 0xC0 == 0x00 { // INDEX
			cur = index[b1 & 0x3F]
		} else if b1 & 0xC0 == 0x40 { // DIFF
			cur.R = byte(int(cur.R) + int((b1>>4)&0x03) - 2)
			cur.G = byte(int(cur.G) + int((b1>>2)&0x03) - 2)
			cur.B = byte(int(cur.B) + int(b1&0x03) - 2)
		} else if b1 & 0xC0 == 0x80 { // LUMA
			if pos >= len(data) { return nil, errors.New("trunc") }
			b2 := data[pos]; pos++
			dg := int(b1&0x3F) - 32
			dr := dg + int((b2>>4)&0x0F) - 8
			db := dg + int(b2&0x0F) - 8
			cur.R = byte(int(cur.R) + dr)
			cur.G = byte(int(cur.G) + dg)
			cur.B = byte(int(cur.B) + db)
		} else { // RUN
			run = int(b1 & 0x3F)
			// this pixel is current, subsequent run copies; mimic: set run for following
			// QOI run: repeat current pixel run+1 times total. We output this one, remaining run.
			// Our loop: run variable counts extra repeats
		}
		px[i] = cur
		idx := (int(cur.R)*3 + int(cur.G)*5 + int(cur.B)*7 + int(cur.A)*11) % 64
		index[idx] = cur
	}
	return &Frame{W: w, H: h, Pix: px}, nil
}
