			cnt := n+1
			for j:=0;j<cnt && i < len(data); j++ { out = append(out, data[i]); i++ }
		} else if n >= -127 {
			cnt := -n+1
			if i < len(data) { b:=data[i]; i++; for j:=0;j<cnt;j++ { out = append(out,b) } }
