// ---- WebP (Lossless VP8L only, plus simple lossless/ARGB fallback) ----
func decodeWebP(data []byte) (*Frame, error) {
	// parse chunks
	pos := 12
	var vp8l []byte
	var isLossless bool
	// VP8 (lossy) not implemented
	for pos+8 <= len(data) {
		typ := string(data[pos:pos+4]); sz := int(binary.LittleEndian.Uint32(data[pos+4:pos+8])); pos+=8
		if pos+sz > len(data) { break }
		chunk := data[pos:pos+sz]
		switch typ {
		case "VP8L":
			isLossless = true; vp8l = chunk
		case "VP8 ":
			return nil, errors.New("vp8 lossy not supported")
		case "ALPH", "ANMF", "ANIM":
			// animated/alpha chunks: try to find VP8L inside? ignore
		}
		pos += sz
		if sz%2==1 { pos++ }
	}
	if isLossless && vp8l != nil {
		return decodeVP8L(vp8l)
	}
	return nil, errors.New("unsupported webp")
}

func decodeVP8L(data []byte) (*Frame, error) {
	// Minimal VP8L decoder: handles 1-pixel / simple images and general no-transform cases best-effort.
	// For many cases this will fail, and caller will report unknown format.
	// Implemented per spec simplified: bit reader LSB.
	if len(data)<5 || data[0]!=0x2f { return nil, errors.New("bad vp8l signature") }
	br := &bitReader{data: data, pos: 1}
	width := int(br.readBits(14))+1
	height := int(br.readBits(14))+1
	alphaUsed := br.readBits(1)
	version := br.readBits(3)
	if version != 0 { return nil, errors.New("bad vp8l version") }
	_ = alphaUsed
	// transform / etc handling is complex; attempt simple top-level image decode with no meta prefix
	// We implement full VP8L simple header: transform present flags
	// For the common tiny lossless case generated by encoders, there may be no transforms.
	// We'll attempt to parse using a simplified Huffman image decoder. If complexity detected, bail.
	fr, err := vp8lDecodeImage(br, width, height)
	if err != nil { return nil, err }
	return fr, nil
}

type bitReader struct { data []byte; pos int; bitPos uint; acc uint32; accBits uint }
func (b *bitReader) readBits(n uint) uint32 {
	for b.accBits < n {
		if b.pos >= len(b.data) { b.acc |= 0; b.accBits += 8; continue }
		b.acc |= uint32(b.data[b.pos]) << b.accBits; b.pos++; b.accBits+=8
	}
	v := b.acc & ((1<<n)-1)
	b.acc >>= n; b.accBits -= n
	return v
}

// Huffman canonical code
type huff struct {
	counts [16]int
	symbols []int
}
func buildHuff(lengths []int) *huff {
	h := &huff{}
	for _, l := range lengths { if l>0 { h.counts[l]++ } }
	// order symbols by (length, symbol)
	type ls struct{l,s int}
	var arr []ls
	for s,l := range lengths { if l>0 { arr = append(arr, ls{l,s}) } }
	// sort by l then s
	for i:=0;i<len(arr);i++ { for j:=i+1;j<len(arr);j++ { if arr[j].l < arr[i].l || (arr[j].l==arr[i].l && arr[j].s<arr[i].s) { arr[i],arr[j]=arr[j],arr[i] } } }
	for _, e := range arr { h.symbols = append(h.symbols, e.s) }
	return h
}
func (h *huff) decode(br *bitReader) int {
	code := 0; first := 0; idx:=0
	for l:=1;l<=15;l++ {
		code = (code<<1) | int(br.readBits(1))
		cnt := h.counts[l]
		if code - first < cnt {
			return h.symbols[idx + (code-first)]
		}
		idx += cnt; first = (first+cnt)<<1
	}
	return 0
}

func vp8lDecodeImage(br *bitReader, w,h int) (*Frame, error) {
	// This is a pragmatic subset: no transforms, Huffman groups =1, no LZ backrefs except copy?
	// Encountering transforms leads to failure.
	// Read: transform present?
	// According to spec, if image is not (meta) ... first bit: transform_present?
	// For simplicity, check bits: many encoders write transforms. We'll try to detect.
	// We'll implement reading of simple image header as in libwebp's VP8LReadHeader etc is too much.
