func clampInt(v int) int { if v<0 {return 0}; if v>255 {return 255}; return v }

func packBitsDecode(data []byte) []byte {
	var out []byte
	i:=0
	for i < len(data) {
		n := int(int8(data[i])); i++
		if n >= 0 {
			cnt := n+1
			for j:=0;j<cnt && i < len(data); j++ { out = append(out, data[i]); i++ }
		} else if n >= -127 {
			cnt := -n+1
			if i < len(data) { b:=data[i]; i++; for j:=0;j<cnt;j++ { out = append(out,b) } }
