type bitReader struct { data []byte; pos int; bitPos uint; acc uint32; accBits uint }
func (b *bitReader) readBits(n uint) uint32 {
	for b.accBits < n {
		if b.pos >= len(b.data) { b.acc |= 0; b.accBits += 8; continue }
		b.acc |= uint32(b.data[b.pos]) << b.accBits; b.pos++; b.accBits+=8
	}
	v := b.acc & ((1<<n)-1)
	b.acc >>= n; b.accBits -= n
