}

// Huffman canonical code
type huff struct {
	counts [16]int
	symbols []int
}
func buildHuff(lengths []int) *huff {
	h := &huff{}
	for _, l := range lengths { if l>0 { h.counts[l]++ } }
	// order symbols by (length, symbol)
	type ls struct{l,s int}
