func decodeVP8L(data []byte) (*Frame, error) {
	// Minimal VP8L decoder: handles 1-pixel / simple images and general no-transform cases best-effort.
	// For many cases this will fail, and caller will report unknown format.
	// Implemented per spec simplified: bit reader LSB.
	if len(data)<5 || data[0]!=0x2f { return nil, errors.New("bad vp8l signature") }
	br := &bitReader{data: data, pos: 1}
	width := int(br.readBits(14))+1
	height := int(br.readBits(14))+1
	alphaUsed := br.readBits(1)
	version := br.readBits(3)
	if version != 0 { return nil, errors.New("bad vp8l version") }
	_ = alphaUsed
