			// LZ77 back reference: length symbol etc
			lengthSym := sym - (256+24)
			_ = lengthSym
			return nil, errors.New("vp8l lz unsupported in subset")
		}
		_ = math.MaxInt
	}
	return &Frame{W:w,H:h,Pix:pix}, nil
