			if len(parts)>=1 { if f,err:=strconv.ParseFloat(parts[0],64); err==nil { sx*=f; sy*=f } }
			if len(parts)>=2 { if f,err:=strconv.ParseFloat(parts[1],64); err==nil { sy = (sy/ (func() float64 { if len(parts)>=1 { fv,_:=strconv.ParseFloat(parts[0],64); _=fv; return 1 }; return 1 }())) } }
			// Actually second scale handling above is messy; if 2 parts, recompute: we already multiplied both by first, need adjust sy:
			if len(parts)>=2 {
				// sy currently = old_sy * first; want old_sy * second. We can't know old; approximate by re-parsing: sy = sy / first * second
				if f1,err1:=strconv.ParseFloat(parts[0],64); err1==nil && f1!=0 { if f2,err2:=strconv.ParseFloat(parts[1],64); err2==nil { sy = sy / f1 * f2 } }
			}
		}}
	}
	return sx,sy,tx,ty
}

func (ctx *svgCtx) mapPt(x,y float64) (float64,float64) {
	return x*ctx.sx+ctx.tx, y*ctx.sy+ctx.ty
}
func (ctx *svgCtx) plot(px,py int, col Color, alpha float64) {
	if px<0||py<0||px>=ctx.w||py>=ctx.h { return }
	a := uint8(clampInt(int(alpha*255+0.5)))
	// source over compositing (simple replace if opaque-ish, else blend)
	old := ctx.pix[py*ctx.w+px]
	if a==255 || old.A==0 {
		ctx.pix[py*ctx.w+px]=RGBA{uint8(col.R),uint8(col.G),uint8(col.B),a}
		return
	}
	af:=float64(a)/255; oaf:=float64(old.A)/255
	outA := af + oaf*(1-af)
	if outA<=0 { ctx.pix[py*ctx.w+px]=RGBA{0,0,0,0}; return }
	r := (float64(col.R)*af + float64(old.R)*oaf*(1-af))/outA
	g := (float64(col.G)*af + float64(old.G)*oaf*(1-af))/outA
	b := (float64(col.B)*af + float64(old.B)*oaf*(1-af))/outA
	ctx.pix[py*ctx.w+px]=RGBA{uint8(r+0.5),uint8(g+0.5),uint8(b+0.5),uint8(outA*255+0.5)}
}

func renderSVGShape(ctx *svgCtx, name string, attrs map[string]string, fill Color, fillSet bool, opacity float64) {
	if !fillSet {
		// stroke only shapes like line might use stroke; handle below stroke fallback
		// For rect etc with fill none, nothing
		if name!="line" && name!="polyline" && name!="path" {
			// check stroke
		}
	}
	getF := func(k string, def float64) float64 { if v,ok:=attrs[k]; ok { if f,err:=strconv.ParseFloat(strings.TrimSpace(strings.TrimSuffix(v,"px")),64); err==nil { return f } }; return def }
	strokeCol := fill; strokeSet:=false; strokeW:=1.0
	if v,ok:=attrs["stroke"]; ok && strings.ToLower(v)!="none" { if c,ok2:=parseSVGColor(v); ok2 { strokeCol=c; strokeSet=true } }
	if v,ok:=attrs["stroke-width"]; ok { if f,err:=strconv.ParseFloat(v,64); err==nil { strokeW=f } }
	// point sampling with supersampling 2x
	contains := func(x,y float64) bool { return false }
	isStrokeShape := false
	switch name {
	case "rect":
		x:=getF("x",0); y:=getF("y",0); w:=getF("width",0); h:=getF("height",0)
		contains = func(px,py float64) bool { return px>=x && px < x+w && py>=y && py < y+h }
	case "circle":
		cx:=getF("cx",0); cy:=getF("cy",0); r:=getF("r",0)
		contains = func(px,py float64) bool { dx:=px-cx; dy:=py-cy; return dx*dx+dy*dy <= r*r }
	case "ellipse":
		cx:=getF("cx",0); cy:=getF("cy",0); rx:=getF("rx",0); ry:=getF("ry",0)
		if rx==0||ry==0 { return }
		contains = func(px,py float64) bool { dx:=(px-cx)/rx; dy:=(py-cy)/ry; return dx*dx+dy*dy <= 1 }
	case "polygon", "polyline":
		pts := parsePoints(attrs["points"])
		if name=="polygon" {
			contains = func(px,py float64) bool { return pointInPolygonF(px,py,pts) }
		} else {
			isStrokeShape=true
			renderPolyline(ctx, pts, false, strokeCol, opacity, strokeW)
			return
		}
	case "line":
		x1:=getF("x1",0); y1:=getF("y1",0); x2:=getF("x2",0); y2:=getF("y2",0)
		renderLine(ctx,x1,y1,x2,y2,strokeCol,opacity,strokeW)
		return
	case "path":
		renderPath(ctx, attrs["d"], fill, fillSet, opacity, strokeCol, strokeSet, strokeW)
		return
	default:
		return
	}
	if !fillSet && !strokeSet { return }
	// Bounding box scan: scan whole canvas (small) with supersample
	SS:=3
	for py:=0; py<ctx.h; py++ {
		for px:=0; px<ctx.w; px++ {
			// transform pixel back to user coords: inverse map
			count:=0
			for sy:=0; sy<SS; sy++ {
				for sx:=0; sx<SS; sx++ {
					// canvas coords
					cx := float64(px)+(float64(sx)+0.5)/float64(SS); cy := float64(py)+(float64(sy)+0.5)/float64(SS)
					ux := (cx-ctx.tx)/ctx.sx; uy := (cy-ctx.ty)/ctx.sy
					if contains(ux,uy) { count++ }
				}
			}
			if count>0 {
				a := opacity * float64(count)/float64(SS*SS)
				if fillSet { ctx.plot(px,py,fill,a) }
			}
		}
	}
	_ = isStrokeShape
}

func pointInPolygonF(x,y float64, pts [][2]float64) bool {
	inside:=false
	n:=len(pts); if n<3 { return false }
	for i,j:=0,n-1;i<n;j=i,i++ {
		xi, yi:=pts[i][0],pts[i][1]; xj, yj:=pts[j][0],pts[j][1]
		if (yi>y)!=(yj>y) {
			xInt := (xj-xi)*(y-yi)/(yj-yi)+xi
			if x < xInt { inside=!inside }
		}
	}
	return inside
}

func parsePoints(s string) [][2]float64 {
	s=strings.ReplaceAll(s,","," ")
	f:=strings.Fields(s)
	var pts [][2]float64
	for i:=0;i+1<len(f);i+=2 { x,_:=strconv.ParseFloat(f[i],64); y,_:=strconv.ParseFloat(f[i+1],64); pts=append(pts,[2]float64{x,y}) }
	return pts
}

func renderLine(ctx *svgCtx, x1,y1,x2,y2 float64, col Color, opacity float64, w float64) {
	// draw line sampled along length
	x1c,y1c:=ctx.mapPt(x1,y1); x2c,y2c:=ctx.mapPt(x2,y2)
	length:=math.Hypot(x2c-x1c, y2c-y1c); steps:=int(length*2)+1; if steps<1 { steps=1 }
	radius:=w*ctx.sx/2; if radius<0.5 { radius=0.5 }
	for i:=0;i<=steps;i++ {
		t:=float64(i)/float64(steps); cx:=x1c+(x2c-x1c)*t; cy:=y1c+(y2c-y1c)*t
		for dy:=-int(radius)-1; dy<=int(radius)+1; dy++ { for dx:=-int(radius)-1; dx<=int(radius)+1; dx++ {
			if float64(dx*dx+dy*dy) <= radius*radius { ctx.plot(int(cx)+dx,int(cy)+dy,col,opacity) }
		}}
	}
}
func renderPolyline(ctx *svgCtx, pts [][2]float64, close bool, col Color, opacity float64, w float64) {
	for i:=0;i+1<len(pts);i++ { renderLine(ctx,pts[i][0],pts[i][1],pts[i+1][0],pts[i+1][1],col,opacity,w) }
	if close && len(pts)>1 { renderLine(ctx,pts[len(pts)-1][0],pts[len(pts)-1][1],pts[0][0],pts[0][1],col,opacity,w) }
}

func renderPath(ctx *svgCtx, d string, fill Color, fillSet bool, opacity float64, strokeCol Color, strokeSet bool, strokeW float64) {
	// tokenize path
	type pt struct{x,y float64}
	var cur pt; var start pt; var polys [][]pt; var curPoly []pt
	var lastCmd byte
	// simple parser for M L H V Z C Q and implicit
	i:=0
	readNum := func() (float64,bool) {
		for i<len(d) && (d[i]==' '||d[i]==','||d[i]=='\n'||d[i]=='\t') { i++ }
		if i>=len(d) { return 0,false }
		j:=i
		if d[j]=='-'||d[j]=='+' { j++ }
		for j<len(d) && ((d[j]>='0'&&d[j]<='9')||d[j]=='.'||d[j]=='e'||d[j]=='E') {
			// transition exponent sign; simplistic
			j++
			if j-1<len(d) && (d[j-1]=='e'||d[j-1]=='E') && j<len(d) && (d[j]=='-'||d[j]=='+') { j++ }
		}
		if j==i { return 0,false }
		v,err:=strconv.ParseFloat(d[i:j],64); i=j; return v,err==nil
	}
	isCmd := func(c byte) bool { return strings.ContainsRune("MLHVZCSQTAmlhvzcsqta", rune(c)) }
	for i < len(d) {
		for i<len(d) && (d[i]==' '||d[i]==','||d[i]=='\n'||d[i]=='\t') { i++ }
		if i>=len(d) { break }
		var cmd byte
		if isCmd(d[i]) { cmd=d[i]; i++; lastCmd=cmd } else { cmd=lastCmd; if cmd=='M' { cmd='L' } else if cmd=='m' { cmd='l' } }
		rel := cmd>='a' && cmd<='z'
		up := cmd; if rel { up = cmd-'a'+'A' }
		switch up {
		case 'M':
			x,ok1:=readNum(); y,ok2:=readNum(); if !ok1||!ok2 { i++; continue }
			if rel { x+=cur.x; y+=cur.y }
			cur=pt{x,y}; start=cur; curPoly=[]pt{cur}
			lastCmd='L'; if rel { lastCmd='l' }
		case 'L':
			x,ok1:=readNum(); y,ok2:=readNum(); if !ok1||!ok2 { i++; continue }
			if rel { x+=cur.x; y+=cur.y }
			cur=pt{x,y}; curPoly=append(curPoly,cur)
		case 'H':
			x,ok:=readNum(); if !ok { i++; continue }
			if rel { x+=cur.x }
			cur.x=x; curPoly=append(curPoly,cur)
		case 'V':
			y,ok:=readNum(); if !ok { i++; continue }
			if rel { y+=cur.y }
			cur.y=y; curPoly=append(curPoly,cur)
		case 'Z':
			if len(curPoly)>0 {
				polys=append(polys, append([]pt{},curPoly...)); curPoly=nil
			}
			cur=start
		case 'C':
			x1,_:=readNum(); y1,_:=readNum(); x2,_:=readNum(); y2,_:=readNum(); x,_:=readNum(); y,_:=readNum()
			if rel { x1+=cur.x; y1+=cur.y; x2+=cur.x; y2+=cur.y; x+=cur.x; y+=cur.y }
			// sample cubic 10 steps
			p0:=cur
			for s:=1;s<=10;s++ { t:=float64(s)/10; mt:=1-t; px:=mt*mt*mt*p0.x+3*mt*mt*t*x1+3*mt*t*t*x2+t*t*t*x; py:=mt*mt*mt*p0.y+3*mt*mt*t*y1+3*mt*t*t*y2+t*t*t*y; curPoly=append(curPoly,pt{px,py}) }
			cur=pt{x,y}
		case 'S','Q','T','A':
			// skip required numbers; enough approximation: treat as line to final point (last 2 numbers) - parsing count differs
			// To avoid infinite loop, consume two numbers and line
			x,ok1:=readNum(); y,ok2:=readNum(); if !ok1||!ok2 { i++; continue }
			if rel { x+=cur.x; y+=cur.y }
			// For A, there are more params, but simplistic skip might mis-align; accept
			cur=pt{x,y}; curPoly=append(curPoly,cur)
		default:
			i++
		}
	}
	if len(curPoly)>0 { polys=append(polys,curPoly) }
	// fill polygons using even-odd scan if fillSet
	if fillSet {
		SS:=2
		for py:=0; py<ctx.h; py++ {
			for px:=0; px<ctx.w; px++ {
				count:=0
				for sy:=0;sy<SS;sy++ { for sx:=0;sx<SS;sx++ {
					cx:=float64(px)+(float64(sx)+0.5)/float64(SS); cy:=float64(py)+(float64(sy)+0.5)/float64(SS)
					ux:=(cx-ctx.tx)/ctx.sx; uy:=(cy-ctx.ty)/ctx.sy
					for _, poly := range polys {
						// convert to [][2]
						var pf [][2]float64; for _,p:=range poly { pf=append(pf,[2]float64{p.x,p.y}) }
						if pointInPolygonF(ux,uy,pf) { count++; break }
					}
				}}
				if count>0 { ctx.plot(px,py,fill, opacity*float64(count)/float64(SS*SS)) }
			}
		}
	}
	if strokeSet || !fillSet {
		col:=strokeCol; if !strokeSet { col=fill }
		for _, poly:=range polys {
			var pf [][2]float64; for _,p:=range poly { pf=append(pf,[2]float64{p.x,p.y}) }
			renderPolyline(ctx, pf, false, col, opacity, strokeW)
		}
	}
}
GO"}

