package main

import (
	"encoding/xml"
	"errors"
	"math"
	"strconv"
	"strings"
)

type svgNode struct {
	XMLName xml.Name
	Attrs []xml.Attr `xml:",any,attr"`
	Children []*svgNode `xml:",any"`
	Content string `xml:",innerxml"`
}
func (n *svgNode) attr(name string) string {
	for _, a := range n.Attrs { if a.Name.Local==name { return a.Value } }
	return ""
}

func decodeSVG(data []byte) (*Frame, error) {
	// Use decoder to build tree manually via xml decoder tokens is complex; use Unmarshal into recursive struct may not work with ,any.
	// Simpler: parse with custom token walk rendering shapes in order.
	return renderSVG(data)
}

// Very small SVG rasterizer: supports rect, circle, ellipse, line, polyline, polygon, path(M,L,H,V,Z,C, etc), g, svg, defs ignored, use
type svgCtx struct {
	w,h int
	pix []RGBA
	viewBox [4]float64
	hasVB bool
	// current transform scale/translate (only scale+translate supported)
	sx, sy, tx, ty float64
}

func renderSVG(data []byte) (*Frame, error) {
	dec := xml.NewDecoder(bytesReader(data))
	// Find root svg attrs first pass: we need size. We'll do two passes: first scan for <svg> token attrs.
	width, height, vb, hasVB := scanSVGSize(data)
	if width <= 0 { width = 300 }
	if height <= 0 { height = 150 }
	// Limit size
	if width > 4096 { width = 4096 }
	if height > 4096 { height = 4096 }
	// If viewBox present and no width/height, use viewBox dims
	if hasVB && (width==300 && height==150) {
		// will be set in scan if missing
	}
	ctx := &svgCtx{w:width,h:height,pix:make([]RGBA,width*height), sx:1, sy:1}
	if hasVB {
		ctx.viewBox = vb; ctx.hasVB = true
		ctx.sx = float64(width)/vb[2]; ctx.sy = float64(height)/vb[3]; ctx.tx = -vb[0]*ctx.sx; ctx.ty = -vb[1]*ctx.sy
	}
	// background transparent
	type elemState struct { fill Color; fillSet bool; opacity float64; transform [4]float64 } // not full
	_ = elemState{}
	// Token walk
	var fill Color = Color{0,0,0}
	var fillSet = true
	var opacity = 1.0
	// stack for g transforms/fill
	type stackItem struct { sx, sy, tx, ty float64; fill Color; fillSet bool; opacity float64 }
	var stack []stackItem
	skipDepth := 0
	for {
		tok, err := dec.Token()
		if err != nil { break }
		switch t := tok.(type) {
		case xml.StartElement:
			name := strings.ToLower(t.Name.Local)
			if name=="defs" || name=="title" || name=="desc" || name=="metadata" || name=="style" {
				skipDepth++
				// push dummy to keep stack balanced? Use stack push on start for g only; for skip, just depth.
				continue
			}
			if skipDepth>0 { skipDepth++; continue }
			// apply attrs for fill etc local
			localFill := fill; localFillSet := fillSet; localOpacity := opacity
			localSX, localSY, localTX, localTY := ctx.sx, ctx.sy, ctx.tx, ctx.ty
			// We'll handle transform per element by temporarily adjusting ctx during its rendering (shapes are leaf, no children except g)
			attrs := map[string]string{}
			for _, a := range t.Attr { attrs[strings.ToLower(a.Name.Local)] = a.Value }
			if v, ok := attrs["fill"]; ok {
				if strings.ToLower(v)=="none" { localFillSet=false } else if c, ok2 := parseSVGColor(v); ok2 { localFill=c; localFillSet=true }
			}
			if v, ok := attrs["opacity"]; ok { if f, err:=strconv.ParseFloat(v,64); err==nil { localOpacity = f } }
			if v, ok := attrs["fill-opacity"]; ok { if f, err:=strconv.ParseFloat(v,64); err==nil { localOpacity *= f } }
			// style attr may contain fill:
			if v, ok := attrs["style"]; ok {
				for _, part := range strings.Split(v, ";") {
					kv:=strings.SplitN(part,":",2); if len(kv)==2 {
						k:=strings.TrimSpace(strings.ToLower(kv[0])); vv:=strings.TrimSpace(kv[1])
						if k=="fill" { if strings.ToLower(vv)=="none" { localFillSet=false } else if c, ok2:=parseSVGColor(vv); ok2 { localFill=c; localFillSet=true } }
						if k=="opacity" { if f,err:=strconv.ParseFloat(vv,64); err==nil { localOpacity=f } }
					}
				}
			}
			if name=="g" || name=="svg" {
				// push current ctx
				stack = append(stack, stackItem{ctx.sx,ctx.sy,ctx.tx,ctx.ty,fill,fillSet,opacity})
				if tr, ok := attrs["transform"]; ok {
					nsx,nsy,ntx,nty := parseTransform(tr, ctx.sx,ctx.sy,ctx.tx,ctx.ty)
					ctx.sx,ctx.sy,ctx.tx,ctx.ty = nsx,nsy,ntx,nty
				}
				fill, fillSet, opacity = localFill, localFillSet, localOpacity
				continue
			}
			// For leaf shapes, apply its own transform temporarily
			saveSX,saveSY,saveTX,saveTY := ctx.sx,ctx.sy,ctx.tx,ctx.ty
			if tr, ok := attrs["transform"]; ok {
				ctx.sx,ctx.sy,ctx.tx,ctx.ty = parseTransform(tr, ctx.sx,ctx.sy,ctx.tx,ctx.ty)
			}
			renderSVGShape(ctx, name, attrs, localFill, localFillSet, localOpacity)
			ctx.sx,ctx.sy,ctx.tx,ctx.ty = saveSX,saveSY,saveTX,saveTY
		case xml.EndElement:
			name := strings.ToLower(t.Name.Local)
			if skipDepth>0 { skipDepth--; continue }
			if name=="g" || name=="svg" {
				if len(stack)>0 {
					it:=stack[len(stack)-1]; stack=stack[:len(stack)-1]
					ctx.sx,ctx.sy,ctx.tx,ctx.ty = it.sx,it.sy,it.tx,it.ty; fill,fillSet,opacity = it.fill,it.fillSet,it.opacity
				}
			}
		}
	}
	if ctx.w<=0 || ctx.h<=0 { return nil, errors.New("bad svg size") }
	return &Frame{W:ctx.w,H:ctx.h,Pix:ctx.pix}, nil
}

func bytesReader(b []byte) *bytesReaderImpl { return &bytesReaderImpl{b:b} }
type bytesReaderImpl struct { b []byte; pos int }
func (r *bytesReaderImpl) Read(p []byte) (int, error) {
	if r.pos>=len(r.b) { return 0, errEOF }
	n:=copy(p, r.b[r.pos:]); r.pos+=n; return n, nil
}
var errEOF = errors.New("EOF")

func scanSVGSize(data []byte) (int,int,[4]float64,bool) {
	// find <svg ...>
	s := string(data)
	idx := strings.Index(strings.ToLower(s), "<svg")
	if idx<0 { return 300,150,[4]float64{},false }
	end := strings.Index(s[idx:], ">")
	if end<0 { return 300,150,[4]float64{},false }
	tag := s[idx:idx+end]
	// crude attr extraction
	getAttr := func(name string) string {
		// look for name=
		low:=strings.ToLower(tag)
		i:=strings.Index(low, name+"=")
		if i<0 { return "" }
		rest:=tag[i+len(name)+1:]
		rest=strings.TrimSpace(rest)
		if len(rest)==0 { return "" }
		q:=rest[0]
		if q=='"' || q=='\'' {
			j:=strings.IndexByte(rest[1:], q); if j<0 { return "" }; return rest[1:1+j]
		}
		// unquoted
		j:=strings.IndexAny(rest, " \t\r\n/>")
		if j<0 { return rest }; return rest[:j]
	}
	parseDim := func(v string) int {
		v=strings.TrimSpace(v); v=strings.TrimSuffix(v,"px")
		if strings.HasSuffix(v,"%") { return 0 }
		f,err:=strconv.ParseFloat(v,64); if err!=nil { return 0 }; return int(math.Round(f))
	}
	w:=parseDim(getAttr("width")); h:=parseDim(getAttr("height"))
	var vb [4]float64; has:=false
	if v:=getAttr("viewBox"); v!="" {
		fields:=strings.Fields(strings.ReplaceAll(v,","," "))
		if len(fields)==4 {
			for i,f:=range fields { if fv,err:=strconv.ParseFloat(f,64); err==nil { vb[i]=fv } }
			has=true
			if w<=0 { w=int(math.Round(vb[2])) }
			if h<=0 { h=int(math.Round(vb[3])) }
		}
	}
	if w<=0 { w=300 }
	if h<=0 { h=150 }
	return w,h,vb,has
}

func parseSVGColor(v string) (Color,bool) {
	v=strings.TrimSpace(v)
	if strings.HasPrefix(v,"rgb") {
		// rgb(r,g,b) or rgba
		l:=strings.Index(v,"("); r:=strings.LastIndex(v,")")
		if l<0||r<0 { return Color{},false }
		parts:=strings.Split(v[l+1:r],",")
		if len(parts)<3 { return Color{},false }
		var vals [3]int
		for i:=0;i<3;i++ {
			p:=strings.TrimSpace(parts[i])
			if strings.HasSuffix(p,"%") {
				f,_:=strconv.ParseFloat(strings.TrimSuffix(p,"%"),64); vals[i]=int(f*255/100)
			} else { f,_:=strconv.ParseFloat(p,64); vals[i]=int(f) }
		}
		return Color{vals[0],vals[1],vals[2]},true
	}
	// url(...) not supported
	if strings.HasPrefix(v,"url") { return Color{},false }
	return parseColorNameOrHex(v)
}

func parseTransform(tr string, sx,sy,tx,ty float64) (float64,float64,float64,float64) {
	// supports translate(x,y), scale(s) / scale(sx,sy). Composition approximate.
	tr = strings.TrimSpace(tr)
	low:=strings.ToLower(tr)
	if strings.HasPrefix(low,"translate") {
		if l:=strings.Index(tr,"("); l>=0 { if r:=strings.Index(tr[l:],")"); r>=0 {
			inside:=tr[l+1:l+r]; parts:=strings.Fields(strings.ReplaceAll(inside,","," "))
			if len(parts)>=1 { if f,err:=strconv.ParseFloat(parts[0],64); err==nil { tx += f*sx } }
			if len(parts)>=2 { if f,err:=strconv.ParseFloat(parts[1],64); err==nil { ty += f*sy } }
		}}
	} else if strings.HasPrefix(low,"scale") {
		if l:=strings.Index(tr,"("); l>=0 { if r:=strings.Index(tr[l:],")"); r>=0 {
			inside:=tr[l+1:l+r]; parts:=strings.Fields(strings.ReplaceAll(inside,","," "))
			if len(parts)>=1 { if f,err:=strconv.ParseFloat(parts[0],64); err==nil { sx*=f; sy*=f } }
			if len(parts)>=2 { if f,err:=strconv.ParseFloat(parts[1],64); err==nil { sy = (sy/ (func() float64 { if len(parts)>=1 { fv,_:=strconv.ParseFloat(parts[0],64); _=fv; return 1 }; return 1 }())) } }
			// Actually second scale handling above is messy; if 2 parts, recompute: we already multiplied both by first, need adjust sy:
			if len(parts)>=2 {
				// sy currently = old_sy * first; want old_sy * second. We can't know old; approximate by re-parsing: sy = sy / first * second
				if f1,err1:=strconv.ParseFloat(parts[0],64); err1==nil && f1!=0 { if f2,err2:=strconv.ParseFloat(parts[1],64); err2==nil { sy = sy / f1 * f2 } }
			}
		}}
	}
	return sx,sy,tx,ty
}

func (ctx *svgCtx) mapPt(x,y float64) (float64,float64) {
	return x*ctx.sx+ctx.tx, y*ctx.sy+ctx.ty
}
func (ctx *svgCtx) plot(px,py int, col Color, alpha float64) {
	if px<0||py<0||px>=ctx.w||py>=ctx.h { return }
	a := uint8(clampInt(int(alpha*255+0.5)))
	// source over compositing (simple replace if opaque-ish, else blend)
	old := ctx.pix[py*ctx.w+px]
	if a==255 || old.A==0 {
		ctx.pix[py*ctx.w+px]=RGBA{uint8(col.R),uint8(col.G),uint8(col.B),a}
		return
	}
	af:=float64(a)/255; oaf:=float64(old.A)/255
	outA := af + oaf*(1-af)
	if outA<=0 { ctx.pix[py*ctx.w+px]=RGBA{0,0,0,0}; return }
	r := (float64(col.R)*af + float64(old.R)*oaf*(1-af))/outA
	g := (float64(col.G)*af + float64(old.G)*oaf*(1-af))/outA
	b := (float64(col.B)*af + float64(old.B)*oaf*(1-af))/outA
	ctx.pix[py*ctx.w+px]=RGBA{uint8(r+0.5),uint8(g+0.5),uint8(b+0.5),uint8(outA*255+0.5)}
}

func renderSVGShape(ctx *svgCtx, name string, attrs map[string]string, fill Color, fillSet bool, opacity float64) {
	if !fillSet {
		// stroke only shapes like line might use stroke; handle below stroke fallback
		// For rect etc with fill none, nothing
		if name!="line" && name!="polyline" && name!="path" {
			// check stroke
		}
	}
	getF := func(k string, def float64) float64 { if v,ok:=attrs[k]; ok { if f,err:=strconv.ParseFloat(strings.TrimSpace(strings.TrimSuffix(v,"px")),64); err==nil { return f } }; return def }
	strokeCol := fill; strokeSet:=false; strokeW:=1.0
	if v,ok:=attrs["stroke"]; ok && strings.ToLower(v)!="none" { if c,ok2:=parseSVGColor(v); ok2 { strokeCol=c; strokeSet=true } }
	if v,ok:=attrs["stroke-width"]; ok { if f,err:=strconv.ParseFloat(v,64); err==nil { strokeW=f } }
	// point sampling with supersampling 2x
	contains := func(x,y float64) bool { return false }
	isStrokeShape := false
	switch name {
	case "rect":
		x:=getF("x",0); y:=getF("y",0); w:=getF("width",0); h:=getF("height",0)
		contains = func(px,py float64) bool { return px>=x && px < x+w && py>=y && py < y+h }
	case "circle":
		cx:=getF("cx",0); cy:=getF("cy",0); r:=getF("r",0)
		contains = func(px,py float64) bool { dx:=px-cx; dy:=py-cy; return dx*dx+dy*dy <= r*r }
	case "ellipse":
		cx:=getF("cx",0); cy:=getF("cy",0); rx:=getF("rx",0); ry:=getF("ry",0)
		if rx==0||ry==0 { return }
		contains = func(px,py float64) bool { dx:=(px-cx)/rx; dy:=(py-cy)/ry; return dx*dx+dy*dy <= 1 }
	case "polygon", "polyline":
		pts := parsePoints(attrs["points"])
		if name=="polygon" {
			contains = func(px,py float64) bool { return pointInPolygonF(px,py,pts) }
		} else {
			isStrokeShape=true
			renderPolyline(ctx, pts, false, strokeCol, opacity, strokeW)
			return
		}
	case "line":
		x1:=getF("x1",0); y1:=getF("y1",0); x2:=getF("x2",0); y2:=getF("y2",0)
		renderLine(ctx,x1,y1,x2,y2,strokeCol,opacity,strokeW)
		return
	case "path":
		renderPath(ctx, attrs["d"], fill, fillSet, opacity, strokeCol, strokeSet, strokeW)
		return
	default:
		return
	}
	if !fillSet && !strokeSet { return }
	// Bounding box scan: scan whole canvas (small) with supersample
	SS:=3
	for py:=0; py<ctx.h; py++ {
		for px:=0; px<ctx.w; px++ {
			// transform pixel back to user coords: inverse map
			count:=0
			for sy:=0; sy<SS; sy++ {
				for sx:=0; sx<SS; sx++ {
					// canvas coords
					cx := float64(px)+(float64(sx)+0.5)/float64(SS); cy := float64(py)+(float64(sy)+0.5)/float64(SS)
					ux := (cx-ctx.tx)/ctx.sx; uy := (cy-ctx.ty)/ctx.sy
					if contains(ux,uy) { count++ }
				}
			}
			if count>0 {
				a := opacity * float64(count)/float64(SS*SS)
				if fillSet { ctx.plot(px,py,fill,a) }
			}
		}
	}
	_ = isStrokeShape
}

func pointInPolygonF(x,y float64, pts [][2]float64) bool {
	inside:=false
	n:=len(pts); if n<3 { return false }
	for i,j:=0,n-1;i<n;j=i,i++ {
		xi, yi:=pts[i][0],pts[i][1]; xj, yj:=pts[j][0],pts[j][1]
		if (yi>y)!=(yj>y) {
			xInt := (xj-xi)*(y-yi)/(yj-yi)+xi
			if x < xInt { inside=!inside }
		}
	}
	return inside
}

func parsePoints(s string) [][2]float64 {
	s=strings.ReplaceAll(s,","," ")
	f:=strings.Fields(s)
	var pts [][2]float64
	for i:=0;i+1<len(f);i+=2 { x,_:=strconv.ParseFloat(f[i],64); y,_:=strconv.ParseFloat(f[i+1],64); pts=append(pts,[2]float64{x,y}) }
	return pts
}

func renderLine(ctx *svgCtx, x1,y1,x2,y2 float64, col Color, opacity float64, w float64) {
	// draw line sampled along length
	x1c,y1c:=ctx.mapPt(x1,y1); x2c,y2c:=ctx.mapPt(x2,y2)
	length:=math.Hypot(x2c-x1c, y2c-y1c); steps:=int(length*2)+1; if steps<1 { steps=1 }
	radius:=w*ctx.sx/2; if radius<0.5 { radius=0.5 }
	for i:=0;i<=steps;i++ {
		t:=float64(i)/float64(steps); cx:=x1c+(x2c-x1c)*t; cy:=y1c+(y2c-y1c)*t
		for dy:=-int(radius)-1; dy<=int(radius)+1; dy++ { for dx:=-int(radius)-1; dx<=int(radius)+1; dx++ {
			if float64(dx*dx+dy*dy) <= radius*radius { ctx.plot(int(cx)+dx,int(cy)+dy,col,opacity) }
		}}
	}
}
func renderPolyline(ctx *svgCtx, pts [][2]float64, close bool, col Color, opacity float64, w float64) {
	for i:=0;i+1<len(pts);i++ { renderLine(ctx,pts[i][0],pts[i][1],pts[i+1][0],pts[i+1][1],col,opacity,w) }
	if close && len(pts)>1 { renderLine(ctx,pts[len(pts)-1][0],pts[len(pts)-1][1],pts[0][0],pts[0][1],col,opacity,w) }
}

func renderPath(ctx *svgCtx, d string, fill Color, fillSet bool, opacity float64, strokeCol Color, strokeSet bool, strokeW float64) {
	// tokenize path
	type pt struct{x,y float64}
	var cur pt; var start pt; var polys [][]pt; var curPoly []pt
	var lastCmd byte
	// simple parser for M L H V Z C Q and implicit
	i:=0
	readNum := func() (float64,bool) {
		for i<len(d) && (d[i]==' '||d[i]==','||d[i]=='\n'||d[i]=='\t') { i++ }
		if i>=len(d) { return 0,false }
		j:=i
		if d[j]=='-'||d[j]=='+' { j++ }
		for j<len(d) && ((d[j]>='0'&&d[j]<='9')||d[j]=='.'||d[j]=='e'||d[j]=='E') {
			// transition exponent sign; simplistic
			j++
			if j-1<len(d) && (d[j-1]=='e'||d[j-1]=='E') && j<len(d) && (d[j]=='-'||d[j]=='+') { j++ }
		}
		if j==i { return 0,false }
		v,err:=strconv.ParseFloat(d[i:j],64); i=j; return v,err==nil
	}
	isCmd := func(c byte) bool { return strings.ContainsRune("MLHVZCSQTAmlhvzcsqta", rune(c)) }
	for i < len(d) {
		for i<len(d) && (d[i]==' '||d[i]==','||d[i]=='\n'||d[i]=='\t') { i++ }
		if i>=len(d) { break }
		var cmd byte
		if isCmd(d[i]) { cmd=d[i]; i++; lastCmd=cmd } else { cmd=lastCmd; if cmd=='M' { cmd='L' } else if cmd=='m' { cmd='l' } }
		rel := cmd>='a' && cmd<='z'
		up := cmd; if rel { up = cmd-'a'+'A' }
		switch up {
		case 'M':
			x,ok1:=readNum(); y,ok2:=readNum(); if !ok1||!ok2 { i++; continue }
			if rel { x+=cur.x; y+=cur.y }
			cur=pt{x,y}; start=cur; curPoly=[]pt{cur}
			lastCmd='L'; if rel { lastCmd='l' }
		case 'L':
			x,ok1:=readNum(); y,ok2:=readNum(); if !ok1||!ok2 { i++; continue }
			if rel { x+=cur.x; y+=cur.y }
			cur=pt{x,y}; curPoly=append(curPoly,cur)
		case 'H':
			x,ok:=readNum(); if !ok { i++; continue }
			if rel { x+=cur.x }
			cur.x=x; curPoly=append(curPoly,cur)
		case 'V':
			y,ok:=readNum(); if !ok { i++; continue }
			if rel { y+=cur.y }
			cur.y=y; curPoly=append(curPoly,cur)
		case 'Z':
			if len(curPoly)>0 {
				polys=append(polys, append([]pt{},curPoly...)); curPoly=nil
			}
			cur=start
		case 'C':
			x1,_:=readNum(); y1,_:=readNum(); x2,_:=readNum(); y2,_:=readNum(); x,_:=readNum(); y,_:=readNum()
			if rel { x1+=cur.x; y1+=cur.y; x2+=cur.x; y2+=cur.y; x+=cur.x; y+=cur.y }
			// sample cubic 10 steps
			p0:=cur
			for s:=1;s<=10;s++ { t:=float64(s)/10; mt:=1-t; px:=mt*mt*mt*p0.x+3*mt*mt*t*x1+3*mt*t*t*x2+t*t*t*x; py:=mt*mt*mt*p0.y+3*mt*mt*t*y1+3*mt*t*t*y2+t*t*t*y; curPoly=append(curPoly,pt{px,py}) }
			cur=pt{x,y}
		case 'S','Q','T','A':
			// skip required numbers; enough approximation: treat as line to final point (last 2 numbers) - parsing count differs
			// To avoid infinite loop, consume two numbers and line
			x,ok1:=readNum(); y,ok2:=readNum(); if !ok1||!ok2 { i++; continue }
			if rel { x+=cur.x; y+=cur.y }
			// For A, there are more params, but simplistic skip might mis-align; accept
			cur=pt{x,y}; curPoly=append(curPoly,cur)
		default:
			i++
		}
	}
	if len(curPoly)>0 { polys=append(polys,curPoly) }
	// fill polygons using even-odd scan if fillSet
	if fillSet {
		SS:=2
		for py:=0; py<ctx.h; py++ {
			for px:=0; px<ctx.w; px++ {
				count:=0
				for sy:=0;sy<SS;sy++ { for sx:=0;sx<SS;sx++ {
					cx:=float64(px)+(float64(sx)+0.5)/float64(SS); cy:=float64(py)+(float64(sy)+0.5)/float64(SS)
					ux:=(cx-ctx.tx)/ctx.sx; uy:=(cy-ctx.ty)/ctx.sy
					for _, poly := range polys {
						// convert to [][2]
						var pf [][2]float64; for _,p:=range poly { pf=append(pf,[2]float64{p.x,p.y}) }
						if pointInPolygonF(ux,uy,pf) { count++; break }
					}
				}}
				if count>0 { ctx.plot(px,py,fill, opacity*float64(count)/float64(SS*SS)) }
			}
		}
	}
	if strokeSet || !fillSet {
		col:=strokeCol; if !strokeSet { col=fill }
		for _, poly:=range polys {
			var pf [][2]float64; for _,p:=range poly { pf=append(pf,[2]float64{p.x,p.y}) }
			renderPolyline(ctx, pf, false, col, opacity, strokeW)
		}
	}
}
