func bytesReader(b []byte) *bytesReaderImpl { return &bytesReaderImpl{b:b} }
type bytesReaderImpl struct { b []byte; pos int }
func (r *bytesReaderImpl) Read(p []byte) (int, error) {
	if r.pos>=len(r.b) { return 0, errEOF }
	n:=copy(p, r.b[r.pos:]); r.pos+=n; return n, nil
}
var errEOF = errors.New("EOF")

func scanSVGSize(data []byte) (int,int,[4]float64,bool) {
