	s := string(data)
	idx := strings.Index(strings.ToLower(s), "<svg")
	if idx<0 { return 300,150,[4]float64{},false }
	end := strings.Index(s[idx:], ">")
	if end<0 { return 300,150,[4]float64{},false }
	tag := s[idx:idx+end]
	// crude attr extraction
	getAttr := func(name string) string {
		// look for name=
		low:=strings.ToLower(tag)
		i:=strings.Index(low, name+"=")
		if i<0 { return "" }
		rest:=tag[i+len(name)+1:]
		rest=strings.TrimSpace(rest)
		if len(rest)==0 { return "" }
		q:=rest[0]
		if q=='"' || q=='\'' {
			j:=strings.IndexByte(rest[1:], q); if j<0 { return "" }; return rest[1:1+j]
		}
