package main

import (
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type TermCaps struct {
	Format string // default format if not set
	Color string // resolved color mode if not set
	SymbolMode string // "ascii" or "block"
	SixelExtra bool // foot/mlterm style extra sequences
}

func detectTermCaps() TermCaps {
	caps := TermCaps{Format: "symbols", SymbolMode: "ascii"}
	termVal, termPresent := os.LookupEnv("TERM")
	if !termPresent {
		caps.Color = "none"
	} else {
		_ = termVal
		caps.Color = "16/8"
	}
	term := termVal
	low := strings.ToLower(term)
	// env identifiers that upgrade
	applyModern := func() {
		caps.Color = "full"
		caps.SymbolMode = "block"
	}
	if _, ok := os.LookupEnv("KONSOLE_VERSION"); ok {
		applyModern()
	}
	if _, ok := os.LookupEnv("VTE_VERSION"); ok {
		applyModern()
	}
	// TERM_PROGRAM
	switch os.Getenv("TERM_PROGRAM") {
	case "iTerm.app":
		caps.Format = "iterm"
		caps.Color = "full"
	case "WezTerm":
		caps.Format = "sixels"
		caps.Color = "full"
		caps.SixelExtra = true
	case "Apple_Terminal":
		caps.Color = "256"
		caps.SymbolMode = "block"
	}
	if _, ok := os.LookupEnv("WEZTERM_EXECUTABLE"); ok {
		caps.Format = "sixels"; caps.Color = "full"; caps.SixelExtra = true
	}
	// TERM-based
	if termPresent {
		switch {
		case strings.Contains(low, "kitty"):
			caps.Format = "kitty"; caps.Color = "full"; caps.SymbolMode = "block"
		case strings.HasPrefix(low, "foot") || strings.HasPrefix(low, "mlterm"):
			caps.Format = "sixels"; caps.Color = "full"; caps.SixelExtra = true
		case low == "linux":
			caps.Color = "16"; caps.SymbolMode = "ascii"
		case strings.HasPrefix(low, "screen"):
			caps.Color = "256"; caps.SymbolMode = "ascii"
		case low == "xterm" || (strings.HasPrefix(low, "xterm-") && !strings.HasPrefix(low, "xterm-color")):
			applyModern()
		case low == "alacritty":
			applyModern()
		case strings.HasPrefix(low, "rxvt-unicode"):
			applyModern()
		case low == "st-256color":
			applyModern()
		}
	}
	return caps
}

type winsize struct {
	Rows, Cols, Xpixel, Ypixel uint16
}
func terminalSize() (int,int,int,int) {
	// returns cols, rows, cellPixelW?? Actually return cols, rows, xpixel, ypixel total
	for _, fd := range []uintptr{os.Stdout.Fd(), os.Stdin.Fd(), os.Stderr.Fd()} {
		ws := &winsize{}
		_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
		if errno==0 && ws.Cols>0 && ws.Rows>0 {
			return int(ws.Cols), int(ws.Rows), int(ws.Xpixel), int(ws.Ypixel)
		}
	}
	// try /dev/tty
	if f, err := os.Open("/dev/tty"); err==nil {
		defer f.Close()
		ws := &winsize{}
		_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
