import "math"

type GeomResult struct {
	CellsW, CellsH int
}

// fitToBox: given image w,h, box w,h, fontRatio, returns cells that fit box preserving aspect.
// Uses formulas: if fitting by width: h = ceil(w * (H/W) * fr) ??? let's verify: card w10 -> h= ceil(10*827/1100*0.5)=ceil(3.75)=4.
// If that exceeds boxH, fit by height: w= ceil(h * (W/H) / fr) ??? square h10 -> w= ceil(10*1/0.5)=20.
func fitToBox(imgW, imgH, boxW, boxH int, fr float64) (int,int) {
	if imgW<=0||imgH<=0 { return 1,1 }
	if boxW<=0 { boxW=1 }
	if boxH<=0 { boxH=1 }
	// try width-driven
	w := boxW
	h := int(math.Ceil(float64(w) * float64(imgH) / float64(imgW) * fr))
	if h > boxH {
		h = boxH
		w = int(math.Ceil(float64(h) * float64(imgW) / float64(imgH) / fr))
		if w > boxW {
			// due to ceil, reduce ?
			w = boxW
			h = int(math.Ceil(float64(w) * float64(imgH) / float64(imgW) * fr))
			if h > boxH { h = boxH }
		}
	}
	if w < 1 { w=1 }
	if h < 1 { h=1 }
	return w,h
}

func computeCells(o *Opts, imgW, imgH int, format string) GeomResult {
	caps := detectTermCaps()
	_ = caps
	effViewW, effViewH, _, _ := effectiveView(o)
	fr := o.FontRatio
	isPixel := format != "symbols"
	// default scale
	scaleVal := o.ScaleVal
	if !o.ScaleSet {
		if isPixel { scaleVal = 1.0 } else { scaleVal = 4.0 }
	}
	// Exact size mode
	if o.ExactSize == "on" {
		w := int(math.Ceil(float64(imgW)*1.0/10.0))
		h := int(math.Ceil(float64(imgH)*1.0/20.0))
		// note for fonts ratio non-default exact may still use 10x20? Original sixel exact gave 40x40 for 32.
		if w<1 { w=1 }; if h<1 { h=1 }
		return GeomResult{w,h}
	}
	// Stretch
	boxW, boxH := targetBox(o, effViewW, effViewH)
	if o.Stretch {
		return GeomResult{boxW, boxH}
	}
