	// For inf scale, width becomes huge -> will be capped to view.
	var wf, hf float64
	if math.IsInf(scaleVal, 1) {
		wf, hf = float64(effViewW), float64(effViewH) // will be fitted
		// Actually inf scale should result in fitting view like max? Original scale inf for pixel image gave 10x5 etc for 1px? Wait earlier pixel scale inf: gave 48wide? For symbols 1px, scale inf gave ... Let's approximate fit view.
		w,h := fitToBox(imgW,imgH,effViewW,effViewH,fr)
		return GeomResult{w,h}
	} else {
		wf = float64(imgW) * scaleVal / cellPW
		hf = float64(imgH) * scaleVal / cellPH
	}
