		fw, fh := fitToBox(imgW, imgH, effViewW, effViewH, fr)
		w, h = fw, fh
	}
	return GeomResult{w,h}
}

func cellPixelSize(fr float64) (float64,float64) {
	// Model inferred: cw = 10*max(1,fr), ch=10*max(1,1/fr) - for default 0.5 gives 10x20.
	// This matches many defaults and simplifies.
	if fr <= 1 {
		return 10, 10/fr
	}
	return 10*fr, 10
}

func targetBox(o *Opts, effViewW, effViewH int) (int,int) {
	if o.SizeDim.Set {
		bw, bh := effViewW, effViewH
		if o.SizeDim.HasW && o.SizeDim.HasH {
			bw, bh = o.SizeDim.W, o.SizeDim.H
		} else if o.SizeDim.HasW {
			bw = o.SizeDim.W
			bh = 100000
		} else if o.SizeDim.HasH {
			bh = o.SizeDim.H
			bw = 100000
		} else {
			// single number? parseDim sets HasW true for "5"
		}
		if bw < 0 { bw = 100000 }
		if bh < 0 { bh = 100000 }
		return bw, bh
	}
	return effViewW, effViewH
}
