	// sRGB to Lab D65
	f := func(c float64) float64 {
		c/=255
		if c>0.04045 { return math.Pow((c+0.055)/1.055,2.4) }
		return c/12.92
	}
	rr,gg,bb := f(r),f(g),f(b)
	x := rr*0.4124+gg*0.3576+bb*0.1805
	y := rr*0.2126+gg*0.7152+bb*0.0722
	z := rr*0.0193+gg*0.1192+bb*0.9505
	x/=0.95047; z/=1.08883
	fl := func(t float64) float64 { if t>0.008856 { return math.Cbrt(t) }; return 7.787*t+16.0/116 }
	fx,fy,fz:=fl(x),fl(y),fl(z)
	return 116*fy-16, 500*(fx-fy), 200*(fy-fz)
}
