package main

import (
	"math"
	"sort"
	"strings"
)

// Internal colour representation for a cluster
type CellColor struct {
	Transparent bool
	R, G, B int // 0-255 output colour (pre-quant)
	// After quantisation, representation depends on mode; we keep RGB and also palette info in Cell
	HasColor bool
}

type Cell struct {
	Ch rune
	Fg CellColor
	Bg CellColor
	// For palette modes, quantized representation
	FgPal *PalColor
	BgPal *PalColor
	Fill bool // fg==bg fill case (symbol space)
}

type PalColor struct {
	Kind string // "rgb","pal256","pal16fg","pal8bg" etc, or "none"
	RGB Color
	Index int // palette index for 256/16 etc
	// For 16/8 fg bright via bold, etc handled in encoder
}

// Resample frame to subpixel grid: width = cellsW*sub, height=cellsH*sub
// sub is 8 normally, 4 for low work? We'll use 8.
type PixF struct {
	PR, PG, PB float64 // premultiplied 0-255
	A float64 // 0-255
	R, G, B float64 // non-premul original (if A>0)
}

func frameToGrid(fr *Frame, cellsW, cellsH int, o *Opts, caps TermCaps) [][]PixF {
	sub := 8
	if o.Work <= 2 {
		sub = 4
	}
	gw, gh := cellsW*sub, cellsH*sub
	grid := make([][]PixF, gh)
	for y := range grid { grid[y]=make([]PixF, gw) }
	// Threshold cutoff
	cutoff := int((1.0 - o.Threshold) * 256) // as deduced
	if cutoff < 0 { cutoff = 0 }
	if cutoff > 256 { cutoff = 256 }
	// Prepare source pixels as float premul with transparency handling
	// For each destination cell, compute source rect
	for dy := 0; dy < gh; dy++ {
		srcY0 := float64(dy) * float64(fr.H) / float64(gh)
		srcY1 := float64(dy+1) * float64(fr.H) / float64(gh)
		for dx := 0; dx < gw; dx++ {
			srcX0 := float64(dx) * float64(fr.W) / float64(gw)
			srcX1 := float64(dx+1) * float64(fr.W) / float64(gw)
			grid[dy][dx] = sampleArea(fr, srcX0, srcY0, srcX1, srcY1, cutoff, o)
		}
	}
	return grid
}

func sampleArea(fr *Frame, x0,y0,x1,y1 float64, cutoff int, o *Opts) PixF {
	// If area < 1px in either dimension, sample bilinear at centre
	if (x1-x0) < 1.0 || (y1-y0) < 1.0 {
		cx := (x0+x1)/2; cy := (y0+y1)/2
		return sampleBilinear(fr, cx, cy, cutoff)
	}
	var sumPR, sumPG, sumPB, sumA, sumR, sumG, sumB, total float64
	ix0 := int(math.Floor(x0)); ix1 := int(math.Ceil(x1))
	iy0 := int(math.Floor(y0)); iy1 := int(math.Ceil(y1))
	for iy := iy0; iy < iy1; iy++ {
		if iy < 0 || iy >= fr.H { continue }
		oy := overlap(float64(iy), float64(iy+1), y0, y1)
		if oy <= 0 { continue }
		for ix := ix0; ix < ix1; ix++ {
			if ix < 0 || ix >= fr.W { continue }
			ox := overlap(float64(ix), float64(ix+1), x0, x1)
			w := ox*oy
			if w <= 0 { continue }
			p := fr.Pix[iy*fr.W+ix]
			a := int(p.A)
			if a < cutoff {
				// transparent: contributes 0 premul and 0 alpha, but total area still counts for average alpha
				total += w
				continue
			}
			af := float64(a)
			sumPR += float64(p.R)*af/255 * w
			sumPG += float64(p.G)*af/255 * w
			sumPB += float64(p.B)*af/255 * w
			sumA += af * w
			sumR += float64(p.R) * w // not used separately
			sumG += float64(p.G) * w
			sumB += float64(p.B) * w
			total += w
			_ = sumR; _ = sumG; _ = sumB
		}
	}
	if total == 0 { return PixF{} }
	return PixF{PR: sumPR/total, PG: sumPG/total, PB: sumPB/total, A: sumA/total}
}

func sampleBilinear(fr *Frame, cx, cy float64, cutoff int) PixF {
	// cx,cy in pixel coordinates where pixel centres are at (i+0.5)
	x := cx - 0.5; y := cy - 0.5
	x0 := int(math.Floor(x)); y0 := int(math.Floor(y))
	fx := x - float64(x0); fy := y - float64(y0)
	var sumPR,sumPG,sumPB,sumA float64
	for dy:=0; dy<2; dy++ {
		for dx:=0; dx<2; dx++ {
			ix := x0+dx; iy:= y0+dy
			w := (1-math.Abs(float64(dx)-fx)) // not correct bilinear weight when fx ... use standard
			// compute bilinear weight
			wx := 1 - math.Abs(float64(dx)-fx - func() float64 { if dx==0 { return 0 }; return 0 }()) // placeholder
			_ = wx; _ = w
			weight := bilinearWeight(dx, fx) * bilinearWeight(dy, fy)
			if weight==0 { continue }
			// clamp pixel
			cxix := ix; if cxix < 0 { cxix=0 }; if cxix >= fr.W { cxix=fr.W-1 }
			cyiy := iy; if cyiy < 0 { cyiy=0 }; if cyiy >= fr.H { cyiy=fr.H-1 }
			p := fr.Pix[cyiy*fr.W+cxix]
			a := int(p.A)
			if a < cutoff { continue }
			af:=float64(a)
			sumPR += float64(p.R)*af/255*weight
			sumPG += float64(p.G)*af/255*weight
			sumPB += float64(p.B)*af/255*weight
			sumA += af*weight
		}
	}
	// weights may not sum to 1 at edges due missing pixels treated transparent; keep sum as is (premul average)
	return PixF{PR: sumPR, PG: sumPG, PB: sumPB, A: sumA}
}
func bilinearWeight(d int, f float64) float64 {
	if d==0 { return 1-f }
	return f
}
func overlap(a0,a1,b0,b1 float64) float64 {
	lo := math.Max(a0,b0); hi := math.Min(a1,b1)
	if hi>lo { return hi-lo }; return 0
}

// Cluster colour computation for weighted subpixels
type clusterInfo struct {
	color CellColor
	alpha float64 // mean alpha 0-255
	premulR, premulG, premulB float64 // mean premul
	weight float64
	count int
}

func computeCluster(grid [][]PixF, cellsX, cellsY int, sym *Symbol, foreground bool, o *Opts, sub int) clusterInfo {
	var sumPR,sumPG,sumPB,sumA,sumW float64
	var count int
	// For median extractor, collect
	type sample struct{pr,pg,pb,a,w float64}
	var samples []sample
	for sy:=0; sy<sub; sy++ {
		for sx:=0; sx<sub; sx++ {
			cov := sym.Cov[sy*8+sx] // note if sub !=8, we map cov index? If sub 4, downsample cov below handled outside
			if sub != 8 {
				// map subpixel coordinate to 8 grid: take cov at (sy*8/sub, sx*8/sub)
				cov = sym.Cov[(sy*8/sub)*8+(sx*8/sub)]
			}
			var w float64
			if foreground { w = cov } else { w = 1-cov }
			if w <= 0.0001 { continue }
			y := cellsY*sub+sy; x := cellsX*sub+sx
			if y<0||y>=len(grid)||x<0||x>=len(grid[0]) { continue }
			p := grid[y][x]
			sumPR += p.PR*w; sumPG += p.PG*w; sumPB += p.PB*w; sumA += p.A*w; sumW += w
			count++
			samples = append(samples, sample{p.PR,p.PG,p.PB,p.A,w})
		}
	}
	if sumW==0 {
		return clusterInfo{color: CellColor{Transparent:true}, weight:0}
	}
	ci := clusterInfo{premulR: sumPR/sumW, premulG: sumPG/sumW, premulB: sumPB/sumW, alpha: sumA/sumW, weight: sumW, count: count}
