	cutoff := (1.0 - o.Threshold) * 256 // float comparison vs alpha?
	// Mean alpha below cutoff -> transparent
	if ci.alpha < cutoff {
		ci.color = CellColor{Transparent:true}
		return ci
	}
	// Output colour: blend premul over background color (o.BgColor effective)
	// raw blended = premul + bg*(1-alpha/255)
	af := ci.alpha/255.0
	r := ci.premulR + float64(o.BgColor.R)*(1-af)
	g := ci.premulG + float64(o.BgColor.G)*(1-af)
	b := ci.premulB + float64(o.BgColor.B)*(1-af)
	if o.ColorExtractor == "median" && len(samples)>0 {
		// median of effective colours per sample (approx)
		// Compute median premul components weighted? Simplify: median of PR etc per sample
		rs := make([]float64, len(samples)); gs:=make([]float64,len(samples)); bs:=make([]float64,len(samples))
		for i,s:=range samples { rs[i]=s.pr; gs[i]=s.pg; bs[i]=s.pb }
		sort.Float64s(rs); sort.Float64s(gs); sort.Float64s(bs)
