		r = med(rs) + float64(o.BgColor.R)*(1-af)
		g = med(gs) + float64(o.BgColor.G)*(1-af)
		b = med(bs) + float64(o.BgColor.B)*(1-af)
	}
	ci.color = CellColor{Transparent:false, HasColor:true, R: clamp255(r), G: clamp255(g), B: clamp255(b)}
