func clamp255(v float64) int {
	iv := int(math.Round(v))
	if iv<0 { return 0 }; if iv>255 { return 255 }; return iv
}

func colorDistanceSq(pr,pg,pb,a float64, exp clusterInfo, o *Opts) float64 {
	var er, eg, eb, ea float64
	if exp.color.Transparent {
		er, eg, eb, ea = 0,0,0,0
