package main

import (
	"math"
	"strings"
)

// Render frame to cells
func renderSymbolsFrame(fr *Frame, cellsW, cellsH int, o *Opts, caps TermCaps, resolvedColor string, format string) [][]Cell {
	initSymbols()
	sub := 8
	if o.Work <= 2 { sub = 4 }
	grid := frameToGrid(fr, cellsW, cellsH, o, caps)
	// Symbol set
	defaultMode := caps.SymbolMode
	symSet := symbolSetFromSpecs(o.SymbolSpecs, defaultMode)
	fillSet := fillSymbolSetFromSpecs(o.FillSpecs)
	candidates := symSet.candidates()
	// Fill candidates are merged as additional candidates (approx)
	if len(o.FillSpecs)>0 {
		seen := make(map[rune]bool)
		for _, c := range candidates { seen[c.Ch]=true }
		for _, fc := range fillSet.candidates() {
			if !seen[fc.Ch] { candidates = append(candidates, fc); seen[fc.Ch]=true }
		}
	}
	if len(candidates)==0 {
		// space fallback
		candidates = []*Symbol{symbolsByChar[' ']}
	}
	// Determine colour handling
	isNone := resolvedColor=="none"
	is2 := resolvedColor=="2"
	fgOnly := o.FgOnly
	cells := make([][]Cell, cellsH)
	for cy:=0; cy<cellsH; cy++ {
		cells[cy]=make([]Cell, cellsW)
		for cx:=0; cx<cellsW; cx++ {
			cells[cy][cx]=pickCell(grid, cx, cy, candidates, o, resolvedColor, isNone, is2, fgOnly, sub)
		}
	}
	return cells
}

func pickCell(grid [][]PixF, cx, cy int, candidates []*Symbol, o *Opts, resolvedColor string, isNone, is2, fgOnly bool, sub int) Cell {
	bestCell := Cell{Ch:' '}
	bestErr := math.Inf(1)
	// Fixed colours for none/2 and fgOnly evaluation
	fixedFg := Color(o.FgColor); fixedBg := Color(o.BgColor)
	for _, sym := range candidates {
		fgCl := computeCluster(grid, cx, cy, sym, true, o, sub)
		bgCl := computeCluster(grid, cx, cy, sym, false, o, sub)
		var err float64
		if isNone || is2 {
			// fixed fg/bg colours
			err = errorFixed(grid,cx,cy,sym, fixedFg, fixedBg, o, sub)
		} else if fgOnly {
			// fg extracted, bg fixed to user bg for error
			err = errorFGOnly(grid,cx,cy,sym, fgCl, fixedBg, o, sub)
		} else {
			err = errorExtracted(grid,cx,cy,sym, fgCl, bgCl, o, resolvedColor, sub)
		}
		// Tiny tie / popularity adjustment? Keep strict < so first (space/low coverage) wins ties
		if err < bestErr - 1e-9 {
			bestErr = err
			// Build cell
			cell := Cell{Ch: sym.Ch}
			if isNone {
				cell.Fg = CellColor{Transparent:true}
				cell.Bg = CellColor{Transparent:true}
			} else if is2 {
				// Quantize fg/bg clusters to fixed pair based on their colours? Use extracted to decide orientation:
				// fg cluster colour quantized to nearest of fg/bg user colours
				cell.Fg = quantToFixed(fgCl, fixedFg, fixedBg)
				cell.Bg = quantToFixed(bgCl, fixedFg, fixedBg)
				// store as Pal for encoder: use RGB
				cell.FgPal = &PalColor{Kind:"rgb", RGB: Color{cell.Fg.R,cell.Fg.G,cell.Fg.B}}
				cell.BgPal = &PalColor{Kind:"rgb", RGB: Color{cell.Bg.R,cell.Bg.G,cell.Bg.B}}
				if fgCl.color.Transparent { cell.Fg = CellColor{Transparent:true}; cell.FgPal=nil }
				if bgCl.color.Transparent { cell.Bg = CellColor{Transparent:true}; cell.BgPal=nil }
			} else if fgOnly {
				cell.Fg = fgCl.color
				cell.Bg = CellColor{Transparent:true}
				if !fgCl.color.Transparent {
					cell.FgPal = quantizeColor(fgCl.color, resolvedColor, true, o)
				}
			} else {
				cell.Fg = fgCl.color
				cell.Bg = bgCl.color
				if !fgCl.color.Transparent {
					cell.FgPal = quantizeColor(fgCl.color, resolvedColor, true, o)
				}
				if !bgCl.color.Transparent {
					cell.BgPal = quantizeColor(bgCl.color, resolvedColor, false, o)
				}
			}
			// special: if symbol has no foreground or no background, colours may be transparent as computed.
			bestCell = cell
		}
	}
	// Post-process: if not none/2/fgOnly and fg and bg are same output RGB (and symbol not ...), turn into fill space
	if !isNone && !is2 && !fgOnly {
		if bestCell.FgPal != nil && bestCell.BgPal != nil {
			if palRGBEqual(bestCell.FgPal, bestCell.BgPal) {
				// fill cell
				bestCell.Ch = ' '
				bestCell.Fill = true
				// Keep FgPal as fill colour, Bg cleared for encoder reverse logic (encoder decides per mode)
				// Store BgPal also so 16/8 encoder can use pair; keep both
			}
		}
		if bestCell.FgPal != nil && bestCell.BgPal == nil && bestCell.Ch==' ' {
			// space with only fg? treat as fill if fg has color
			// This arises when bg cluster transparent but fg ... For transparent cell, both should be nil.
		}
	}
	// If symbol is space and fg is transparent and bg is a colour, encoder will handle as fill using bg.
	if bestCell.Ch==' ' && bestCell.FgPal==nil && bestCell.BgPal!=nil && !isNone && !fgOnly {
		// convert to fill with bg colour as fg for reverse logic, but note 16/8 needs pair
		// Keep as is; encoder handles
	}
	return bestCell
}

func palRGBEqual(a,b *PalColor) bool {
	if a==nil||b==nil { return false }
	// If both have indices, compare index and kind family; else compare RGB
	if a.Kind==b.Kind && a.Index==b.Index && a.Kind!="" && a.Kind!="rgb" {
		// For palettes, same index but fg/bg may use different actual RGB? Still treat as equal for fill detection when indexes equal and RGB equal
		return a.RGB==b.RGB
	}
	return a.RGB==b.RGB
}

func quantToFixed(cl clusterInfo, fg, bg Color) CellColor {
	if cl.color.Transparent { return CellColor{Transparent:true} }
	// nearest of fg / bg by RGB distance
	dFg := distRGB(cl.color, fg); dBg := distRGB(cl.color, bg)
	if dFg <= dBg { return CellColor{HasColor:true,R:fg.R,G:fg.G,B:fg.B} }
	return CellColor{HasColor:true,R:bg.R,G:bg.G,B:bg.B}
}
func distRGB(c CellColor, col Color) float64 {
	dr:=float64(c.R-col.R); dg:=float64(c.G-col.G); db:=float64(c.B-col.B)
	return dr*dr+dg*dg+db*db
}

func errorFixed(grid [][]PixF, cx,cy int, sym *Symbol, fg,bg Color, o *Opts, sub int) float64 {
	// expected colours fixed fg/bg as opaque (alpha255), with premul = colour
	fgExp := clusterInfo{color: CellColor{HasColor:true,R:fg.R,G:fg.G,B:fg.B}, alpha:255, premulR:float64(fg.R), premulG:float64(fg.G), premulB:float64(fg.B)}
	bgExp := clusterInfo{color: CellColor{HasColor:true,R:bg.R,G:bg.G,B:bg.B}, alpha:255, premulR:float64(bg.R), premulG:float64(bg.G), premulB:float64(bg.B)}
	return errorWithExps(grid,cx,cy,sym, fgExp, bgExp, o, sub)
}
func errorFGOnly(grid [][]PixF, cx,cy int, sym *Symbol, fgCl clusterInfo, bg Color, o *Opts, sub int) float64 {
	bgExp := clusterInfo{color: CellColor{HasColor:true,R:bg.R,G:bg.G,B:bg.B}, alpha:255, premulR:float64(bg.R), premulG:float64(bg.G), premulB:float64(bg.B)}
	return errorWithExps(grid,cx,cy,sym, fgCl, bgExp, o, sub)
}
func errorExtracted(grid [][]PixF, cx,cy int, sym *Symbol, fgCl,bgCl clusterInfo, o *Opts, resolved string, sub int) float64 {
	// If colour mode has palette quantisation, quantize clusters before error
	fgExp := fgCl; bgExp := bgCl
	if resolved != "full" && resolved != "none" {
		if !fgCl.color.Transparent {
			pal := quantizeColor(fgCl.color, resolved, true, o)
			fgExp = clusterInfo{color: CellColor{HasColor:true,R:pal.RGB.R,G:pal.RGB.G,B:pal.RGB.B}, alpha:255, premulR:float64(pal.RGB.R), premulG:float64(pal.RGB.G), premulB:float64(pal.RGB.B)}
		}
		if !bgCl.color.Transparent {
			pal := quantizeColor(bgCl.color, resolved, false, o)
			bgExp = clusterInfo{color: CellColor{HasColor:true,R:pal.RGB.R,G:pal.RGB.G,B:pal.RGB.B}, alpha:255, premulR:float64(pal.RGB.R), premulG:float64(pal.RGB.G), premulB:float64(pal.RGB.B)}
		}
	}
	return errorWithExps(grid,cx,cy,sym, fgExp, bgExp, o, sub)
}

func errorWithExps(grid [][]PixF, cx,cy int, sym *Symbol, fgExp,bgExp clusterInfo, o *Opts, sub int) float64 {
	var err float64
	for sy:=0; sy<sub; sy++ {
		for sx:=0; sx<sub; sx++ {
			var cov float64
			if sub==8 { cov = sym.Cov[sy*8+sx] } else { cov = sym.Cov[(sy*8/sub)*8+(sx*8/sub)] }
			y:=cy*sub+sy; x:=cx*sub+sx
			if y<0||y>=len(grid)||x<0||x>=len(grid[0]) { continue }
			p:=grid[y][x]
			// Rendered expected: cov*fg + (1-cov)*bg in premul/alpha space
			var er,eg,eb,ea float64
			// helper to get premul/alpha of exp
			fgr,fgg,fgb,fga := expPremul(fgExp)
			bgr,bgg,bgb,bga := expPremul(bgExp)
			er = cov*fgr + (1-cov)*bgr
			eg = cov*fgg + (1-cov)*bgg
			eb = cov*fgb + (1-cov)*bgb
			ea = cov*fga + (1-cov)*bga
			if o.ColorSpace=="din99d" {
				// convert diff in Lab for RGB(premul) parts
				l1,a1,b1 := rgbToLab(p.PR,p.PG,p.PB)
				l2,a2,b2 := rgbToLab(er,eg,eb)
				dr,dg,db := l1-l2,a1-a2,b1-b2
				da := p.A-ea
				err += (dr*dr+dg*dg+db*db)*6.5 + da*da*0.25
			} else {
				dr:=p.PR-er; dg:=p.PG-eg; db:=p.PB-eb; da:=p.A-ea
				err += dr*dr+dg*dg+db*db + da*da
			}
		}
	}
	// optional preprocess contrast boost: if preprocess on and low colours, this error calculation already reflects? 
	// We apply a small penalty based on symbol complexity? Not.
	_ = strings.TrimSpace
	return err
}

func expPremul(ci clusterInfo) (float64,float64,float64,float64) {
	if ci.color.Transparent { return 0,0,0,0 }
	return float64(ci.color.R), float64(ci.color.G), float64(ci.color.B), 255
}
GO"}

