				cell.BgPal = &PalColor{Kind:"rgb", RGB: Color{cell.Bg.R,cell.Bg.G,cell.Bg.B}}
				if fgCl.color.Transparent { cell.Fg = CellColor{Transparent:true}; cell.FgPal=nil }
				if bgCl.color.Transparent { cell.Bg = CellColor{Transparent:true}; cell.BgPal=nil }
