func errorExtracted(grid [][]PixF, cx,cy int, sym *Symbol, fgCl,bgCl clusterInfo, o *Opts, resolved string, sub int) float64 {
	// If colour mode has palette quantisation, quantize clusters before error
	fgExp := fgCl; bgExp := bgCl
	if resolved != "full" && resolved != "none" {
		if !fgCl.color.Transparent {
			pal := quantizeColor(fgCl.color, resolved, true, o)
			fgExp = clusterInfo{color: CellColor{HasColor:true,R:pal.RGB.R,G:pal.RGB.G,B:pal.RGB.B}, alpha:255, premulR:float64(pal.RGB.R), premulG:float64(pal.RGB.G), premulB:float64(pal.RGB.B)}
		}
		if !bgCl.color.Transparent {
			pal := quantizeColor(bgCl.color, resolved, false, o)
			bgExp = clusterInfo{color: CellColor{HasColor:true,R:pal.RGB.R,G:pal.RGB.G,B:pal.RGB.B}, alpha:255, premulR:float64(pal.RGB.R), premulG:float64(pal.RGB.G), premulB:float64(pal.RGB.B)}
		}
	}
	return errorWithExps(grid,cx,cy,sym, fgExp, bgExp, o, sub)
}

func errorWithExps(grid [][]PixF, cx,cy int, sym *Symbol, fgExp,bgExp clusterInfo, o *Opts, sub int) float64 {
	var err float64
	for sy:=0; sy<sub; sy++ {
		for sx:=0; sx<sub; sx++ {
			var cov float64
			if sub==8 { cov = sym.Cov[sy*8+sx] } else { cov = sym.Cov[(sy*8/sub)*8+(sx*8/sub)] }
			y:=cy*sub+sy; x:=cx*sub+sx
			if y<0||y>=len(grid)||x<0||x>=len(grid[0]) { continue }
			p:=grid[y][x]
			// Rendered expected: cov*fg + (1-cov)*bg in premul/alpha space
			var er,eg,eb,ea float64
			// helper to get premul/alpha of exp
			fgr,fgg,fgb,fga := expPremul(fgExp)
			bgr,bgg,bgb,bga := expPremul(bgExp)
			er = cov*fgr + (1-cov)*bgr
			eg = cov*fgg + (1-cov)*bgg
			eb = cov*fgb + (1-cov)*bgb
			ea = cov*fga + (1-cov)*bga
			if o.ColorSpace=="din99d" {
				// convert diff in Lab for RGB(premul) parts
				l1,a1,b1 := rgbToLab(p.PR,p.PG,p.PB)
				l2,a2,b2 := rgbToLab(er,eg,eb)
				dr,dg,db := l1-l2,a1-a2,b1-b2
				da := p.A-ea
				err += (dr*dr+dg*dg+db*db)*6.5 + da*da*0.25
			} else {
				dr:=p.PR-er; dg:=p.PG-eg; db:=p.PB-eb; da:=p.A-ea
				err += dr*dr+dg*dg+db*db + da*da
			}
		}
	}
	// optional preprocess contrast boost: if preprocess on and low colours, this error calculation already reflects? 
	// We apply a small penalty based on symbol complexity? Not.
	_ = strings.TrimSpace
	return err
}

func expPremul(ci clusterInfo) (float64,float64,float64,float64) {
	if ci.color.Transparent { return 0,0,0,0 }
	return float64(ci.color.R), float64(ci.color.G), float64(ci.color.B), 255
}
