package main

import "math"

// Palettes
var ansiNormal = []Color{
	{0,0,0},{170,0,0},{0,170,0},{170,85,0},{0,0,170},{170,0,170},{0,170,170},{170,170,170},
}
var ansiBright = []Color{
	{85,85,85},{255,85,85},{85,255,85},{255,255,85},{85,85,255},{255,85,255},{85,255,255},{255,255,255},
}
// Alternative VGA-like palettes for quantization (used internally). The encoder uses indices, so exact RGB
// chosen here only affects which index is selected.
func palette16() []Color {
	out := make([]Color, 16)
	copy(out, ansiNormal)
	copy(out[8:], ansiBright)
	return out
}
func xtermPalette() []Color {
	pal := make([]Color, 256)
	// 0-15
	copy(pal, palette16())
	// cube
	levels := []int{0,95,135,175,215,255}
	idx:=16
	for r:=0;r<6;r++ { for g:=0;g<6;g++ { for b:=0;b<6;b++ { pal[idx]=Color{levels[r],levels[g],levels[b]}; idx++ } } }
	// grayscale 232-255: 8+10*i
	for i:=0;i<24;i++ { v:=8+10*i; pal[232+i]=Color{v,v,v} }
	return pal
}

func nearestColor(col CellColor, palette []Color, o *Opts) int {
	best:=0; bestD:=math.Inf(1)
	target := Color{col.R,col.G,col.B}
	for i,c := range palette {
		var d float64
		if o != nil && o.ColorSpace=="din99d" {
			l1,a1,b1 := rgbToLab(float64(target.R),float64(target.G),float64(target.B))
			l2,a2,b2 := rgbToLab(float64(c.R),float64(c.G),float64(c.B))
			d = (l1-l2)*(l1-l2)+(a1-a2)*(a1-a2)+(b1-b2)*(b1-b2)
		} else {
			dr:=float64(target.R-c.R); dg:=float64(target.G-c.G); db:=float64(target.B-c.B)
