{"command":"cat > encode.go <<'GO'
package main

import (
	"fmt"
	"strings"
)

// Encode cells to a string (without final newline handling; caller decides)
// Returns representation for one frame, rows separated by row terminator logic.
// This function implements non/animation still: rows joined with "\n" and trailing "\n" if addFinalNewline
func encodeSymbols(cells [][]Cell, o *Opts, resolved string, relative bool, isFinalFrame bool, includeFinalNewline bool) string {
	var sb strings.Builder
	// Initial reset/39
	// fgOnly mode uses \x1b[39m at start instead of \x1b[0m in optimized modes, and in opt0 it still has \x1b[39m before per-cell?
	// We'll be handled inside per row encoder
	h := len(cells)
	for y:=0; y<h; y++ {
		row := cells[y]
		sb.WriteString(encodeRow(row, o, resolved, y==0))
		if relative {
			w := visibleWidth(row, o)
			// also account align padding handled by caller via a prefix? Align handled outside by transforming cells/string separately.
			if y < h-1 {
				sb.WriteString(fmt.Sprintf("\x1b[%dD\x1bD", w))
			} else {
				if includeFinalNewline {
					// final row for relative: \x1bD\x1b[wD
					sb.WriteString(fmt.Sprintf("\x1bD\x1b[%dD", w))
				} else {
					sb.WriteString(fmt.Sprintf("\x1bD\x1b[%dD", w))
				}
			}
		} else {
			if y < h-1 {
				sb.WriteString("\n")
			} else if includeFinalNewline {
				sb.WriteString("\n")
			}
		}
	}
	return sb.String()
}

func visibleWidth(row []Cell, o *Opts) int {
	// width in terminal columns: wide runes count 2? Chafa symbols wide are 2 cells? But candidates may be wide char that still occupies 1 in output stream? For relative movement, original counts bytes? Simplified rune count considering wide map.
	w:=0
	for _, c := range row {
		if isWideRune(c.Ch) { w+=2 } else { w+=1 }
	}
	return w
}
func isWideRune(r rune) bool {
	// East Asian wide ranges roughly
	return (r>=0x1100 && r<=0x115F) || (r>=0x2E80 && r<=0xA4CF) || (r>=0xAC00 && r<=0xD7A3) || (r>=0xF900 && r<=0xFAFF) || (r>=0xFF00 && r<=0xFF60) || (r>=0x20000 && r<=0x2FFFF) || (r>=0x3040 && r<=0x30FF) || (r>=0x4E00 && r<=0x9FFF)
}

type ansiState struct {
	fgKey string
	bgKey string
	bold bool
	reverse bool
	// fgOnly special
}

func encodeRow(row []Cell, o *Opts, resolved string, firstRow bool) string {
	if resolved=="none" && !o.FgOnly {
		var sb strings.Builder
		for _, c := range row { sb.WriteRune(c.Ch) }
		return sb.String()
	}
	if o.Optimize==0 || (resolved=="none" && o.FgOnly) {
		// fgOnly with none: original returns just characters (no escapes at any opt)
		if resolved=="none" {
			var sb strings.Builder
			for _, c := range row { sb.WriteRune(c.Ch) }
			return sb.String()
		}
		return encodeRowOpt0(row, o, resolved)
	}
	return encodeRowOpt(row, o, resolved)
}

// sequence fragment for a PalColor as FG or BG under mode
func sgrForPal(p *PalColor, isFG bool, mode string, o *Opts) (seq string, boldNeeded bool, key string) {
	if p==nil { return "", false, "none" }
	switch p.Kind {
	case "rgb":
		if isFG { return fmt.Sprintf("38;2;%d;%d;%d", p.RGB.R,p.RGB.G,p.RGB.B), false, fmt.Sprintf("fgrgb%d,%d,%d",p.RGB.R,p.RGB.G,p.RGB.B) }
		return fmt.Sprintf("48;2;%d;%d;%d", p.RGB.R,p.RGB.G,p.RGB.B), false, fmt.Sprintf("bgrgb%d,%d,%d",p.RGB.R,p.RGB.G,p.RGB.B)
	case "pal256":
		if isFG { return fmt.Sprintf("38;5;%d", p.Index), false, fmt.Sprintf("fg256%d",p.Index) }
		return fmt.Sprintf("48;5;%d", p.Index), false, fmt.Sprintf("bg256%d",p.Index)
	case "ansi8fg":
		return fmt.Sprintf("%d", 30+p.Index), false, fmt.Sprintf("fg8%d",p.Index)
	case "ansi8bg":
		return fmt.Sprintf("%d", 40+p.Index), false, fmt.Sprintf("bg8%d",p.Index)
	case "ansi16fg":
		if mode=="16/8" {
			// bright via bold + normal
			if p.Index>=8 {
				return fmt.Sprintf("%d", 30+(p.Index-8)), true, fmt.Sprintf("fg168b%d",p.Index)
			}
			return fmt.Sprintf("%d", 30+p.Index), false, fmt.Sprintf("fg168%d",p.Index)
		}
		// mode 16
		if p.Index>=8 {
			return fmt.Sprintf("%d", 90+(p.Index-8)), false, fmt.Sprintf("fg16%d",p.Index)
		}
		return fmt.Sprintf("%d", 30+p.Index), false, fmt.Sprintf("fg16%d",p.Index)
	}
	return "", false, ""
}

// For 16/8 etc, handling fill etc.

func encodeRowOpt0(row []Cell, o *Opts, resolved string) string {
	var sb strings.Builder
	// In opt0, first cell of whole image has an extra \x1b[0m handled by caller (initial). Per row, original starts each row with \x1b[0m? Looking: Opt0 row2 began with \x1b[0m before first cell.
	// Caller handles initial global; we'll add a leading \x1b[0m at start of each row in encodeSymbols? Simpler: this function returns per-cell sequences each ending with \x1b[0m, and first cell also prefixed with \x1b[0m if fgonly? We'll emulate: Each cell: colour seq (without leading reset except fgonly start)
	if o.FgOnly {
		sb.WriteString("\x1b[39m")
	}
	sb.WriteString("\x1b[0m")
	for _, c := range row {
		// build attributes for this cell
		seq := cellSGR(c, o, resolved, true)
		if seq != "" {
			sb.WriteString(seq)
		}
		sb.WriteRune(c.Ch)
		if o.FgOnly {
			// Actually opt0 fgonly: after each cell \x1b[0m? Observed: cells ended \x1b[0m then next cell. But initial 39 replaced? Sequence was \x1b[39m \x1b[0m fg @ \x1b[0m fg $ ... \x1b[39m\n
			// So per cell trailing is \x1b[0m except last where \x1b[39m before newline caller handles? Our row encoder is called per row, we'll output \x1b[0m after each cell and caller will handle row end?
			sb.WriteString("\x1b[0m")
		} else {
			sb.WriteString("\x1b[0m")
		}
	}
	if o.FgOnly {
		// row end in opt0: replace last trailing? It ends with \x1b[39m (handled by removing last \x1b[0m? Simpler append \x1b[39m ; extra reset before that may differ.
		// We'll leave: caller in encodeSymbols for fgOnly opt0 may adjust.
	}
	return sb.String()
}

func cellSGR(c Cell, o *Opts, resolved string, opt0 bool) string {
	// Return a SGR sequence \x1b[...m for this cell based on its type. For opt>=1, caller does diffing, not this.
	if resolved=="2" {
		// reverse if fg is user bg (dark) and bg is user fg (light)
		if c.FgPal!=nil && c.BgPal!=nil {
			// Determine if fgPal RGB equals original bg (swapped)
		}
		if isCellReverse2(c,o) { return "\x1b[7m" }
		return ""
	}
	if c.Fill {
		// fill case
		if resolved=="16/8" {
			// fg normal, bg normal
			fgSeq,_,_ := sgrForPal(normalize16_8FG(c.FgPal), true, resolved, o)
			bgSeq,_,_ := sgrForPal(c.BgPal, false, resolved, o)
			parts:=[]string{}
			if fgSeq!="" { parts=append(parts,fgSeq) }
			if bgSeq!="" { parts=append(parts,bgSeq) }
			if len(parts)>0 { return "\x1b["+strings.Join(parts,";")+"m" }
			return ""
		}
		// other modes: reverse + fg
		if c.FgPal!=nil {
			fgSeq, bold,_ := sgrForPal(c.FgPal, true, resolved, o)
			parts:=[]string{"7"}
			if bold { parts=append([]string{"1"}, parts...) } // order? original has \x1b[1m separately for 16/8; for 16 mode reverse is in own seq before fg seq
			// Original sequences for such cell often are \x1b[7m\x1b[38;...m (separate)
			// To reproduce, return two sequences:
			if bold {
				return "\x1b[1m\x1b[7m\x1b["+fgSeq+"m"
			}
			return "\x1b[7m\x1b["+fgSeq+"m"
		}
		return ""
	}
	if o.FgOnly {
		if c.FgPal!=nil {
			fgSeq, bold,_ := sgrForPal(c.FgPal, true, resolved, o)
			if bold { return "\x1b[1m\x1b["+fgSeq+"m" }
			return "\x1b["+fgSeq+"m"
		}
		return ""
	}
	// Normal cell
	parts:=[]string{}
	boldNeeded:=false
	// Space with only bg colour: original often converts to reverse+fg. Our Fill detection handles fg==bg case; this case is bg only.
	if c.Ch==' ' && c.FgPal==nil && c.BgPal!=nil {
		// Use reverse trick for most modes except 16/8 (where fg+bg pair may be used) - but here fg missing, so reverse using bg colour as fg
		if resolved=="16/8" {
			// emit bg only? Original for transparent? For space bg only, they might emit fg+bg both with fg default... We'll emit bg sequence normalised as fg? Simpler: emit bg as bg.
			bgSeq,_,_:=sgrForPal(c.BgPal,false,resolved,o)
			return "\x1b["+bgSeq+"m"
		}
		// create a pal with same RGB/Index but as fg
		fgPal := palAsFG(c.BgPal, resolved)
		fgSeq,b,_:=sgrForPal(fgPal,true,resolved,o)
		if b { return "\x1b[1m\x1b[7m\x1b["+fgSeq+"m" }
		return "\x1b[7m\x1b["+fgSeq+"m"
	}
	if c.FgPal!=nil {
		fgSeq,b,_:=sgrForPal(c.FgPal,true,resolved,o)
		if fgSeq!="" { parts=append(parts,fgSeq) }
		if b { boldNeeded=true }
	}
	if c.BgPal!=nil {
		bgSeq,_,_:=sgrForPal(c.BgPal,false,resolved,o)
		if bgSeq!="" { parts=append(parts,bgSeq) }
	}
	if len(parts)==0 && !boldNeeded { return "" }
	seq := "\x1b["+strings.Join(parts,";")+"m"
	if boldNeeded {
		// original emits \x1b[1m as separate sequence before main, example: \x1b[1m\x1b[36;47m
		seq = "\x1b[1m"+seq
	}
	return seq
}

func normalize16_8FG(p *PalColor) *PalColor {
	if p==nil { return nil }
	if p.Kind=="ansi16fg" && p.Index>=8 {
		// for fill in 16/8, they use normal fg (not bold) when bg is also present
		return &PalColor{Kind:"ansi16fg", RGB:p.RGB, Index:p.Index-8}
	}
	return p
}
func palAsFG(bg *PalColor, mode string) *PalColor {
	if bg==nil { return nil }
	// convert bg pal to fg equivalent retaining RGB/index/type
	switch bg.Kind {
	case "pal256": return &PalColor{Kind:"pal256", RGB:bg.RGB, Index:bg.Index}
	case "rgb": return &PalColor{Kind:"rgb", RGB:bg.RGB}
	case "ansi8bg":
		// fg with same normal index
		if mode=="16" || mode=="16/8" {
			return &PalColor{Kind:"ansi16fg", RGB:bg.RGB, Index:bg.Index}
		}
		return &PalColor{Kind:"ansi8fg", RGB:bg.RGB, Index:bg.Index}
	case "ansi8fg", "ansi16fg": return bg
	}
	return bg
}

func isCellReverse2(c Cell, o *Opts) bool {
	if c.FgPal==nil || c.BgPal==nil { return false }
	// In palette 2, if fg colour equals user bg colour (dark side) then glyph is inverted relative to default
	// fgPal RGB stores the quantized fixed colour. Compare to o.BgColor (effective after invert)
	fgIsBg := c.FgPal.RGB == o.BgColor
	bgIsFg := c.BgPal.RGB == o.FgColor
	// If fg is bg colour (black by default) and bg is fg (white) => reverse
	if fgIsBg && bgIsFg { return true }
	// Also if char's fg cluster was dark while bg light, our quantToFixed will give fg=bgUser, bg=fgUser.
	return false
}
GO"}

