{"command":"cat > pixel.go <<'GO'
package main

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"math"
	"strings"
)

type PixelCanvas struct {
	W,H int // pixels
	CellsW, CellsH int
	Pix []RGBA // row major W*H, transparent zero
}

func makePixelCanvas(fr *Frame, cellsW, cellsH int, o *Opts, format string, caps TermCaps) *PixelCanvas {
	// Kitty width adjustment: limit cells width to effViewW-1 if exceeds
	if format=="kitty" {
		effW,_,_,_ := effectiveView(o)
		if effW>1 && cellsW >= effW {
			cellsW = effW-1
			if cellsW<1 { cellsW=1 }
		}
	}
	pw, ph := cellsW*10, cellsH*20
	canvas := &PixelCanvas{W:pw,H:ph,CellsW:cellsW,CellsH:cellsH,Pix:make([]RGBA,pw*ph)}
	// Determine if we should scale image to canvas
	scaleNeeded := false
	if o.SizeDim.Set || o.ScaleMax || o.Stretch || o.FitWidth {
		scaleNeeded = true
	}
	if o.ExactSize=="on" {
		scaleNeeded = false
	}
	// exact-size auto with size set acts as size mode (tested)
	if o.ExactSize=="auto" && o.SizeDim.Set {
		scaleNeeded = true
	}
	if !scaleNeeded {
		// place native, cropped
		for y:=0; y<fr.H && y<ph; y++ {
			for x:=0; x<fr.W && x<pw; x++ {
				canvas.Pix[y*pw+x]=fr.Pix[y*fr.W+x]
			}
		}
		return canvas
	}
	// scaling
	if fr.H==1 {
		// original bug/feature: height 1 images are not scaled in size mode
		for y:=0; y<fr.H && y<ph; y++ {
			for x:=0; x<fr.W && x<pw; x++ {
				canvas.Pix[y*pw+x]=fr.Pix[y*fr.W+x]
			}
		}
		return canvas
	}
	var sw, sh int
	if o.Stretch {
		sw, sh = pw, ph
	} else {
		s := math.Min(float64(pw)/float64(fr.W), float64(ph)/float64(fr.H))
		if s<=0 { s=1 }
		sw = int(math.Ceil(float64(fr.W)*s - 1e-9))
		sh = int(math.Ceil(float64(fr.H)*s - 1e-9))
		if sw<1 { sw=1 }
		if sh<1 { sh=1 }
		if sw>pw { sw=pw }
		if sh>ph { sh=ph }
	}
	scaled := resizeFrame(fr, sw, sh, o)
	for y:=0; y<scaled.H && y<ph; y++ {
		for x:=0; x<scaled.W && x<pw; x++ {
			canvas.Pix[y*pw+x]=scaled.Pix[y*scaled.W+x]
		}
	}
	return canvas
}

func resizeFrame(fr *Frame, dw, dh int, o *Opts) *Frame {
	if dw<=0||dh<=0 { return fr }
	out := &Frame{W:dw,H:dh,Pix:make([]RGBA,dw*dh), DelayMs: fr.DelayMs}
	// Use area average when downscaling in either dimension, bilinear when upscaling
	// We'll do a generic source-rect sample per dest pixel with premul handling for alpha, but return non-premul colours:
	// For each dest, compute source rect, average premul + alpha, then unpremultiply if alpha>0.
	for dy:=0; dy<dh; dy++ {
		y0 := float64(dy)*float64(fr.H)/float64(dh); y1:=float64(dy+1)*float64(fr.H)/float64(dh)
		for dx:=0; dx<dw; dx++ {
			x0 := float64(dx)*float64(fr.W)/float64(dw); x1:=float64(dx+1)*float64(fr.W)/float64(dw)
			// If upscaling (rect <1), bilinear centre sample will be used inside sampleArea-like logic
			out.Pix[dy*dw+dx]=sampleResize(fr,x0,y0,x1,y1)
		}
	}
	return out
}

func sampleResize(fr *Frame, x0,y0,x1,y1 float64) RGBA {
	if (x1-x0)<1 || (y1-y0)<1 {
		// bilinear
		cx:=(x0+x1)/2 - 0.5; cy:=(y0+y1)/2 - 0.5
		ix:=int(math.Floor(cx)); iy:=int(math.Floor(cy)); fx:=cx-float64(ix); fy:=cy-float64(iy)
		var sumR,sumG,sumB,sumA,sumPR,sumPG,sumPB float64
		for dy:=0;dy<2;dy++ { for dx:=0;dx<2;dx++ {
			wx:=0.0; if dx==0 { wx=1-fx } else { wx=fx }
			wy:=0.0; if dy==0 { wy=1-fy } else { wy=fy }
			w:=wx*wy
			px:=ix+dx; if px<0{px=0}; if px>=fr.W{px=fr.W-1}
			py:=iy+dy; if py<0{py=0}; if py>=fr.H{py=fr.H-1}
			p:=fr.Pix[py*fr.W+px]
			af:=float64(p.A)
			sumPR+=float64(p.R)*af/255*w; sumPG+=float64(p.G)*af/255*w; sumPB+=float64(p.B)*af/255*w; sumA+=af*w
			_ = sumR; _=sumG; _=sumB
		}}
		if sumA<=0 { return RGBA{0,0,0,0} }
		// unpremultiply: colour = premul *255 / alpha
		r:=sumPR*255/sumA; g:=sumPG*255/sumA; b:=sumPB*255/sumA
		return RGBA{uint8(clamp255(r)),uint8(clamp255(g)),uint8(clamp255(b)),uint8(clamp255(sumA))}
	}
	var sumPR,sumPG,sumPB,sumA,total float64
	ix0:=int(math.Floor(x0)); ix1:=int(math.Ceil(x1)); iy0:=int(math.Floor(y0)); iy1:=int(math.Ceil(y1))
	for iy:=iy0; iy<iy1; iy++ {
		if iy<0||iy>=fr.H{continue}
		oy:=overlap(float64(iy),float64(iy+1),y0,y1)
		for ix:=ix0; ix<ix1; ix++ {
			if ix<0||ix>=fr.W{continue}
			ox:=overlap(float64(ix),float64(ix+1),x0,x1); w:=ox*oy
			p:=fr.Pix[iy*fr.W+ix]; af:=float64(p.A)
			sumPR+=float64(p.R)*af/255*w; sumPG+=float64(p.G)*af/255*w; sumPB+=float64(p.B)*af/255*w; sumA+=af*w; total+=w
		}
	}
	if total==0||sumA<=0 { return RGBA{0,0,0,0} }
	avgA:=sumA/total
	r:= (sumPR/total)*255/avgA; g:=(sumPG/total)*255/avgA; b:=(sumPB/total)*255/avgA
	// Actually premul avg = sumPR/total, unpremul division by avgA/255 => *255/avgA correct
	return RGBA{uint8(clamp255(r)),uint8(clamp255(g)),uint8(clamp255(b)),uint8(clamp255(avgA))}
}

// Quantize colours for sixel based on mode
func sixelPaletteAndMap(pc *PixelCanvas, o *Opts, resolved string) ([]Color, []int) {
	// map pixel index -> palette index, -1 for transparent (alpha below cutoff?)
	// Alpha handling: pixel with A ==0 is transparent (no bits). Semi: treat as colour (its RGB)
	indices := make([]int, pc.W*pc.H)
	for i,p := range pc.Pix {
		if p.A==0 { indices[i]=-1 } else { indices[i]=0 }
	}
	if resolved=="none" {
		// fg = user fg, bg = user bg (default white/black)
		pal := []Color{o.FgColor, o.BgColor}
		for i,p := range pc.Pix {
			if p.A==0 { indices[i]=-1; continue }
			// determine nearest of fg/bg by luminance? Use color distance of premul colour
			// Pixel effective colour = blend over bg? For sixel none, original converted to grey based on... Use RGB distance to fg/bg colours
			col := CellColor{R:int(p.R),G:int(p.G),B:int(p.B)}
			// blend with alpha
			if p.A<255 {
				af:=float64(p.A)/255; col.R=clamp255(float64(p.R)*af); col.G=clamp255(float64(p.G)*af); col.B=clamp255(float64(p.B)*af)
			}
			df:=distRGB(col, o.FgColor); db:=distRGB(col, o.BgColor)
			if df<=db { indices[i]=0 } else { indices[i]=1 }
		}
		return pal, indices
	}
	if resolved=="2" {
		pal := []Color{o.FgColor, o.BgColor}
		for i,p := range pc.Pix {
			if p.A==0 { indices[i]=-1; continue }
			col := CellColor{R:int(p.R),G:int(p.G),B:int(p.B)}
			df:=distRGB(col, o.FgColor); db:=distRGB(col, o.BgColor)
			if df<=db { indices[i]=0 } else { indices[i]=1 }
		}
		return pal, indices
	}
	if resolved=="256" || resolved=="240" {
		pal := xtermPalette()
		if resolved=="240" {
			// still define all 256 in header? Original for 256 mode defined all; for 240 mode check: likely also defines all 240? We'll generate mapping only 16-255 but palette header will be as per encoder logic.
			// We'll return full palette and map to 16+
			for i,p := range pc.Pix {
				if p.A==0 { indices[i]=-1; continue }
				col:=CellColor{R:int(p.R),G:int(p.G),B:int(p.B)}
				idx:=nearestColor(col, pal[16:], o)+16
				indices[i]=idx
			}
			return pal, indices
		}
		for i,p := range pc.Pix {
			if p.A==0 { indices[i]=-1; continue }
			col:=CellColor{R:int(p.R),G:int(p.G),B:int(p.B)}
			indices[i]=nearestColor(col, pal, o)
		}
		return pal, indices
	}
	if resolved=="8" || resolved=="16" || resolved=="16/8" {
		// use 16 palette (foreground) for sixel? Sixel palette entries are colours irrespective fg/bg.
		pal := palette16()
		if resolved=="8" { pal = ansiNormal }
		for i,p := range pc.Pix {
			if p.A==0 { indices[i]=-1; continue }
			col:=CellColor{R:int(p.R),G:int(p.G),B:int(p.B)}
			indices[i]=nearestColor(col, pal, o)
		}
		return pal, indices
	}
	// full: quantize distinct colours to <=256
	// Collect distinct colours (with dither maybe?)
	// Apply dithering for sixels if mode is noise/ordered/diffusion (default noise)
	// We operate on pixel colours copy
	colorsWork := make([]Color, pc.W*pc.H)
	for i,p := range pc.Pix { colorsWork[i]=Color{int(p.R),int(p.G),int(p.B)} }
	// Simple dither if requested / default: for full mode sixel, dithering affects quantisation to 256 colours.
	// If number distinct <=256, no dither effect needed.
	distinct := map[Color]bool{}
	for i,p := range pc.Pix { if p.A!=0 { distinct[colorsWork[i]]=true } }
	if len(distinct) <= 255 {
		// quantizer in original always adds a dummy colour as last entry (237). It sorts colours by... we'll use first appearance order.
		palMap := map[Color]int{}
		var pal []Color
		for i,p := range pc.Pix {
			if p.A==0 { indices[i]=-1; continue }
			c:=colorsWork[i]
			if idx,ok:=palMap[c]; ok { indices[i]=idx } else { palMap[c]=len(pal); pal=append(pal,c); indices[i]=len(pal)-1 }
		}
		// add dummy
		pal=append(pal, Color{237,237,237})
		return pal, indices
	}
	// median cut to 255 colours
	pal := medianCut(colorsWork, pc.Pix, 255)
	// map
	for i,p := range pc.Pix {
		if p.A==0 { indices[i]=-1; continue }
		col:=CellColor{R:int(p.R),G:int(p.G),B:int(p.B)}
		indices[i]=nearestColor(col, pal, o)
	}
	pal=append(pal, Color{237,237,237})
	return pal, indices
}

func medianCut(colors []Color, pix []RGBA, maxColors int) []Color {
	type box struct{ cols []Color }
	if len(colors)==0 { return []Color{{0,0,0}} }
	boxes := []box{{cols: append([]Color{}, colors...)}}
	// filter transparent? caller passed all; keep but transparent pixels have 0 colour; filter them out for palette building
	// Rebuild boxes with only opaque
	var opaque []Color
	for i,c:=range colors { if pix[i].A!=0 { opaque=append(opaque,c) } }
	if len(opaque)==0 { return []Color{{0,0,0}} }
	boxes = []box{{cols: opaque}}
	for len(boxes) < maxColors {
		// find box with largest range
		bi:=-1; brange:=-1; bchan:=0
		for i,b:=range boxes {
			if len(b.cols)<=1 { continue }
			minr,ming,minb:=255,255,255; maxr,maxg,maxb:=0,0,0
			for _,c:=range b.cols { if c.R<minr{minr=c.R}; if c.R>maxr{maxr=c.R}; if c.G<ming{ming=c.G}; if c.G>maxg{maxg=c.G}; if c.B<minb{minb=c.B}; if c.B>maxb{maxb=c.B} }
			r:=maxr-minr; if maxg-ming>r { }; rng:=r; ch:=0
			if maxg-ming>rng { rng=maxg-ming; ch=1 }
			if maxb-minb>rng { rng=maxb-minb; ch=2 }
			if rng>brange { brange=rng; bi=i; bchan=ch }
		}
		if bi<0 || brange<=0 { break }
		b:=boxes[bi]
		// sort by channel
		cols:=append([]Color{}, b.cols...)
		// simple sort
		for i:=0;i<len(cols);i++ { for j:=i+1;j<len(cols);j++ { var vi,vj int; switch bchan{case 0: vi,vj=cols[i].R,cols[j].R; case 1: vi,vj=cols[i].G,cols[j].G; default: vi,vj=cols[i].B,cols[j].B}; if vj<vi { cols[i],cols[j]=cols[j],cols[i] } } }
		mid:=len(cols)/2
		boxes = append(boxes[:bi], boxes[bi+1:]...)
		boxes = append(boxes, box{cols[:mid]}, box{cols[mid:]})
	}
	var pal []Color
	for _,b:=range boxes {
		if len(b.cols)==0 { continue }
		var sr,sg,sb int
		for _,c:=range b.cols { sr+=c.R; sg+=c.G; sb+=c.B }
		pal=append(pal, Color{sr/len(b.cols), sg/len(b.cols), sb/len(b.cols)})
	}
	return pal
}

func encodeSixel(pc *PixelCanvas, o *Opts, resolved string, caps TermCaps) string {
	var sb strings.Builder
	if caps.SixelExtra {
		sb.WriteString("\x1b[?80l\x1b[?8452l")
	}
	pal, idxMap := sixelPaletteAndMap(pc, o, resolved)
	sb.WriteString(fmt.Sprintf("\x1bP0;1;0q\"1;1;%d;%d", pc.W, pc.H))
	// Palette definition: for 256 mode, original defines all 256 colours in xterm order (values as %)
	// For full/none/16 etc, define palette colours in order.
	if resolved=="256" {
		for i,c:=range pal {
			// Pal is xterm palette; define all 256
			sb.WriteString(fmt.Sprintf("#%d;2;%d;%d;%d", i, pct(c.R), pct(c.G), pct(c.B)))
		}
	} else if resolved=="240" {
		for i:=16;i<len(pal);i++ {
			c:=pal[i]
			sb.WriteString(fmt.Sprintf("#%d;2;%d;%d;%d", i, pct(c.R), pct(c.G), pct(c.B)))
		}
	} else {
		for i,c:=range pal {
			sb.WriteString(fmt.Sprintf("#%d;2;%d;%d;%d", i, pct(c.R), pct(c.G), pct(c.B)))
		}
	}
	// Raster bands
	nBands := (pc.H+5)/6
	for band:=0; band<nBands; band++ {
		// collect colors present in this band
		// For each color used in band (in palette order), encode
		// Build per color column data
		firstColor:=true
		// Determine if band is completely empty and it's not last band? Original skips some empty bands but still emits separators.
		// We'll follow original simplified: encode colors that have at least one pixel, or if none and band==last, encode color0 with empty?
		type colData struct{ idx int; chars []byte }
		var cols []colData
		for ci:= range pal {
			has:=false
			chars:=make([]byte, pc.W)
			for x:=0;x<pc.W;x++ {
				bits:=0
				for dy:=0; dy<6; dy++ {
					y:=band*6+dy; if y>=pc.H { break }
					if idxMap[y*pc.W+x]==ci { bits |= 1<<uint(dy); has=true }
				}
				chars[x]=byte(63+bits)
				_ = has
			}
			// decide include if any bit set
			any:=false; for _,ch:=range chars { if ch!=63 { any=true; break } }
			if any { cols=append(cols, colData{ci, chars}) }
		}
		if len(cols)==0 {
			if band==nBands-1 {
				// emit #0 with all ?
				sb.WriteString("#0")
				sb.WriteString(rleSixel(bytes.Repeat([]byte{'?'}, pc.W)))
				if band < nBands-1 { sb.WriteString("-") }
			} else {
				sb.WriteString("-")
			}
			continue
		}
		for ciPos, cd := range cols {
			if ciPos>0 { sb.WriteString("$") }
			_ = firstColor
			sb.WriteString(fmt.Sprintf("#%d", cd.idx))
			sb.WriteString(rleSixel(cd.chars))
		}
		if band < nBands-1 {
			sb.WriteString("-")
		}
	}
	sb.WriteString("\x1b\\")
	sb.WriteString("\n")
	return sb.String()
}
func pct(v int) int {
	// sixel percentages: round(v*100/255) approx - original uses (v*100+127)/255? for 254 ->100, 18->7
	return (v*100+127)/255
}
func rleSixel(data []byte) string {
	var sb strings.Builder
	for i:=0;i<len(data); {
		j:=i; for j<len(data) && data[j]==data[i] { j++ }
		run:=j-i
		if run>=4 {
			// Use !n char if beneficial? Original used ! for runs >=? Example !10~ for 10, !9? for 9. It uses RLE for repeates >=3? Check !20 etc.
			sb.WriteString(fmt.Sprintf("!%d%c", run, data[i]))
		} else if run==3 {
			// could be !3 or repeat 3 - original often uses ! for >=3?
			sb.WriteString(fmt.Sprintf("!%d%c", run, data[i]))
		} else {
			for k:=0;k<run;k++ { sb.WriteByte(data[i]) }
		}
		i=j
	}
	// Trim trailing '?' (? = empty) at end? Original kept !10? for whole width even if empty at end for last band, but for colour bands it may include trailing ? to fill width.
	// We'll keep full width as original does for many cases (they pad to width)
	return sb.String()
}

func encodeKitty(pc *PixelCanvas, o *Opts, resolved string) string {
	// raw RGBA bytes
	data := make([]byte, pc.W*pc.H*4)
	for i,p := range pc.Pix {
		data[i*4]=p.R; data[i*4+1]=p.G; data[i*4+2]=p.B; data[i*4+3]=p.A
	}
	var sb strings.Builder
	// Passthrough handling is done by caller wrapping sequences: kitty passthrough modifies header.
	// Build normal sequences chunks
	head := fmt.Sprintf("\x1b_Ga=T,f=32,s=%d,v=%d,c=%d,r=%d,m=1,q=2\x1b\\", pc.W, pc.H, pc.CellsW, pc.CellsH)
	sb.WriteString(head)
	// chunking 510 bytes raw
	chunkSize := 510
	if len(data)==0 {
		sb.WriteString("\x1b_Gm=0\x1b\\")
		sb.WriteString("\n")
		return sb.String()
	}
	for off:=0; off<len(data); off+=chunkSize {
		end:=off+chunkSize; if end>len(data){end=len(data)}
		enc := base64.StdEncoding.EncodeToString(data[off:end])
		sb.WriteString("\x1b_Gm=1;"+enc+"\x1b\\")
	}
	sb.WriteString("\x1b_Gm=0\x1b\\")
	sb.WriteString("\n")
	return sb.String()
}

func encodeITerm(pc *PixelCanvas, o *Opts, resolved string) string {
	tiff := encodeTIFF(pc)
	b64 := base64.StdEncoding.EncodeToString(tiff)
	return fmt.Sprintf("\x1b]1337;File=inline=1;width=%d;height=%d;preserveAspectRatio=0:%s\x07\n", pc.CellsW, pc.CellsH, b64)
}

func encodeTIFF(pc *PixelCanvas) []byte {
	// Little endian TIFF as observed
	var buf bytes.Buffer
	// header
	buf.Write([]byte{'I','I',42,0})
	ifdOff := 8 + pc.W*pc.H*4
	writeU32(&buf, uint32(ifdOff))
	// pixel data
	for _, p := range pc.Pix {
		buf.WriteByte(p.R); buf.WriteByte(p.G); buf.WriteByte(p.B); buf.WriteByte(p.A)
	}
	// IFD
	entries := []struct{tag, typ uint16; count uint32; value uint32}{
		{256,4,1,uint32(pc.W)},
		{257,4,1,uint32(pc.H)},
		{258,3,4,0}, // offset placeholder fill later
		{262,3,1,2},
		{273,4,1,8},
		{274,3,1,1},
		{277,3,1,4},
		{278,4,1,uint32(pc.H)},
		{279,4,1,uint32(pc.W*pc.H*4)},
		{284,3,1,1},
		{338,3,1,2},
	}
	// Bits offset after IFD: ifdOff + 2 + 11*12+4 = ifdOff+138
	bitsOff := ifdOff + 2 + len(entries)*12 + 4
	entries[2].value = uint32(bitsOff)
	writeU16(&buf, uint16(len(entries)))
	for _, e := range entries {
		writeU16(&buf, e.tag); writeU16(&buf, e.typ); writeU32(&buf, e.count)
		// value: if type short and count 1, value is in low bytes little endian with padding
		if e.typ==3 && e.count==1 {
			writeU16(&buf, uint16(e.value)); writeU16(&buf, 0)
		} else {
			writeU32(&buf, e.value)
		}
	}
	writeU32(&buf, 0) // next IFD
	// bits per sample 8,8,8,8
	for i:=0;i<4;i++ { writeU16(&buf, 8) }
	return buf.Bytes()
}
func writeU16(b *bytes.Buffer, v uint16) { b.WriteByte(byte(v)); b.WriteByte(byte(v>>8)) }
func writeU32(b *bytes.Buffer, v uint32) { b.WriteByte(byte(v)); b.WriteByte(byte(v>>8)); b.WriteByte(byte(v>>16)); b.WriteByte(byte(v>>24)) }
GO"}

