func rleSixel(data []byte) string {
	var sb strings.Builder
	for i:=0;i<len(data); {
		j:=i; for j<len(data) && data[j]==data[i] { j++ }
		run:=j-i
		if run>=4 {
			// Use !n char if beneficial? Original used ! for runs >=? Example !10~ for 10, !9? for 9. It uses RLE for repeates >=3? Check !20 etc.
			sb.WriteString(fmt.Sprintf("!%d%c", run, data[i]))
		} else if run==3 {
			// could be !3 or repeat 3 - original often uses ! for >=3?
			sb.WriteString(fmt.Sprintf("!%d%c", run, data[i]))
		} else {
			for k:=0;k<run;k++ { sb.WriteByte(data[i]) }
		}
		i=j
	}
	// Trim trailing '?' (? = empty) at end? Original kept !10? for whole width even if empty at end for last band, but for colour bands it may include trailing ? to fill width.
	// We'll keep full width as original does for many cases (they pad to width)
	return sb.String()
}

func encodeKitty(pc *PixelCanvas, o *Opts, resolved string) string {
	// raw RGBA bytes
	data := make([]byte, pc.W*pc.H*4)
	for i,p := range pc.Pix {
		data[i*4]=p.R; data[i*4+1]=p.G; data[i*4+2]=p.B; data[i*4+3]=p.A
	}
	var sb strings.Builder
	// Passthrough handling is done by caller wrapping sequences: kitty passthrough modifies header.
	// Build normal sequences chunks
	head := fmt.Sprintf("\x1b_Ga=T,f=32,s=%d,v=%d,c=%d,r=%d,m=1,q=2\x1b\\", pc.W, pc.H, pc.CellsW, pc.CellsH)
	sb.WriteString(head)
	// chunking 510 bytes raw
	chunkSize := 510
	if len(data)==0 {
		sb.WriteString("\x1b_Gm=0\x1b\\")
		sb.WriteString("\n")
		return sb.String()
	}
	for off:=0; off<len(data); off+=chunkSize {
		end:=off+chunkSize; if end>len(data){end=len(data)}
		enc := base64.StdEncoding.EncodeToString(data[off:end])
		sb.WriteString("\x1b_Gm=1;"+enc+"\x1b\\")
	}
	sb.WriteString("\x1b_Gm=0\x1b\\")
	sb.WriteString("\n")
	return sb.String()
}

func encodeITerm(pc *PixelCanvas, o *Opts, resolved string) string {
	tiff := encodeTIFF(pc)
	b64 := base64.StdEncoding.EncodeToString(tiff)
	return fmt.Sprintf("\x1b]1337;File=inline=1;width=%d;height=%d;preserveAspectRatio=0:%s\x07\n", pc.CellsW, pc.CellsH, b64)
}

func encodeTIFF(pc *PixelCanvas) []byte {
	// Little endian TIFF as observed
	var buf bytes.Buffer
	// header
	buf.Write([]byte{'I','I',42,0})
	ifdOff := 8 + pc.W*pc.H*4
	writeU32(&buf, uint32(ifdOff))
	// pixel data
	for _, p := range pc.Pix {
		buf.WriteByte(p.R); buf.WriteByte(p.G); buf.WriteByte(p.B); buf.WriteByte(p.A)
	}
	// IFD
	entries := []struct{tag, typ uint16; count uint32; value uint32}{
		{256,4,1,uint32(pc.W)},
		{257,4,1,uint32(pc.H)},
		{258,3,4,0}, // offset placeholder fill later
		{262,3,1,2},
		{273,4,1,8},
		{274,3,1,1},
		{277,3,1,4},
		{278,4,1,uint32(pc.H)},
		{279,4,1,uint32(pc.W*pc.H*4)},
		{284,3,1,1},
		{338,3,1,2},
	}
	// Bits offset after IFD: ifdOff + 2 + 11*12+4 = ifdOff+138
	bitsOff := ifdOff + 2 + len(entries)*12 + 4
	entries[2].value = uint32(bitsOff)
	writeU16(&buf, uint16(len(entries)))
	for _, e := range entries {
		writeU16(&buf, e.tag); writeU16(&buf, e.typ); writeU32(&buf, e.count)
		// value: if type short and count 1, value is in low bytes little endian with padding
		if e.typ==3 && e.count==1 {
			writeU16(&buf, uint16(e.value)); writeU16(&buf, 0)
		} else {
			writeU32(&buf, e.value)
		}
	}
	writeU32(&buf, 0) // next IFD
	// bits per sample 8,8,8,8
	for i:=0;i<4;i++ { writeU16(&buf, 8) }
	return buf.Bytes()
}
func writeU16(b *bytes.Buffer, v uint16) { b.WriteByte(byte(v)); b.WriteByte(byte(v>>8)) }
func writeU32(b *bytes.Buffer, v uint32) { b.WriteByte(byte(v)); b.WriteByte(byte(v>>8)); b.WriteByte(byte(v>>16)); b.WriteByte(byte(v>>24)) }
