		cols:=append([]Color{}, b.cols...)
		// simple sort
		for i:=0;i<len(cols);i++ { for j:=i+1;j<len(cols);j++ { var vi,vj int; switch bchan{case 0: vi,vj=cols[i].R,cols[j].R; case 1: vi,vj=cols[i].G,cols[j].G; default: vi,vj=cols[i].B,cols[j].B}; if vj<vi { cols[i],cols[j]=cols[j],cols[i] } } }
		mid:=len(cols)/2
		boxes = append(boxes[:bi], boxes[bi+1:]...)
		boxes = append(boxes, box{cols[:mid]}, box{cols[mid:]})
	}
	var pal []Color
	for _,b:=range boxes {
		if len(b.cols)==0 { continue }
		var sr,sg,sb int
		for _,c:=range b.cols { sr+=c.R; sg+=c.G; sb+=c.B }
		pal=append(pal, Color{sr/len(b.cols), sg/len(b.cols), sb/len(b.cols)})
	}
	return pal
}

func encodeSixel(pc *PixelCanvas, o *Opts, resolved string, caps TermCaps) string {
	var sb strings.Builder
	if caps.SixelExtra {
		sb.WriteString("\x1b[?80l\x1b[?8452l")
	}
	pal, idxMap := sixelPaletteAndMap(pc, o, resolved)
	sb.WriteString(fmt.Sprintf("\x1bP0;1;0q\"1;1;%d;%d", pc.W, pc.H))
	// Palette definition: for 256 mode, original defines all 256 colours in xterm order (values as %)
	// For full/none/16 etc, define palette colours in order.
	if resolved=="256" {
		for i,c:=range pal {
			// Pal is xterm palette; define all 256
			sb.WriteString(fmt.Sprintf("#%d;2;%d;%d;%d", i, pct(c.R), pct(c.G), pct(c.B)))
		}
	} else if resolved=="240" {
		for i:=16;i<len(pal);i++ {
			c:=pal[i]
			sb.WriteString(fmt.Sprintf("#%d;2;%d;%d;%d", i, pct(c.R), pct(c.G), pct(c.B)))
		}
	} else {
		for i,c:=range pal {
			sb.WriteString(fmt.Sprintf("#%d;2;%d;%d;%d", i, pct(c.R), pct(c.G), pct(c.B)))
		}
	}
	// Raster bands
	nBands := (pc.H+5)/6
	for band:=0; band<nBands; band++ {
		// collect colors present in this band
		// For each color used in band (in palette order), encode
		// Build per color column data
		firstColor:=true
		// Determine if band is completely empty and it's not last band? Original skips some empty bands but still emits separators.
		// We'll follow original simplified: encode colors that have at least one pixel, or if none and band==last, encode color0 with empty?
		type colData struct{ idx int; chars []byte }
		var cols []colData
		for ci:= range pal {
			has:=false
			chars:=make([]byte, pc.W)
			for x:=0;x<pc.W;x++ {
				bits:=0
				for dy:=0; dy<6; dy++ {
					y:=band*6+dy; if y>=pc.H { break }
					if idxMap[y*pc.W+x]==ci { bits |= 1<<uint(dy); has=true }
				}
				chars[x]=byte(63+bits)
				_ = has
			}
			// decide include if any bit set
			any:=false; for _,ch:=range chars { if ch!=63 { any=true; break } }
			if any { cols=append(cols, colData{ci, chars}) }
		}
		if len(cols)==0 {
			if band==nBands-1 {
				// emit #0 with all ?
				sb.WriteString("#0")
				sb.WriteString(rleSixel(bytes.Repeat([]byte{'?'}, pc.W)))
				if band < nBands-1 { sb.WriteString("-") }
			} else {
				sb.WriteString("-")
			}
			continue
		}
		for ciPos, cd := range cols {
			if ciPos>0 { sb.WriteString("$") }
			_ = firstColor
			sb.WriteString(fmt.Sprintf("#%d", cd.idx))
			sb.WriteString(rleSixel(cd.chars))
		}
		if band < nBands-1 {
			sb.WriteString("-")
		}
	}
	sb.WriteString("\x1b\\")
	sb.WriteString("\n")
	return sb.String()
}
func pct(v int) int {
	// sixel percentages: round(v*100/255) approx - original uses (v*100+127)/255? for 254 ->100, 18->7
	return (v*100+127)/255
}
func rleSixel(data []byte) string {
	var sb strings.Builder
	for i:=0;i<len(data); {
		j:=i; for j<len(data) && data[j]==data[i] { j++ }
		run:=j-i
		if run>=4 {
			// Use !n char if beneficial? Original used ! for runs >=? Example !10~ for 10, !9? for 9. It uses RLE for repeates >=3? Check !20 etc.
			sb.WriteString(fmt.Sprintf("!%d%c", run, data[i]))
		} else if run==3 {
			// could be !3 or repeat 3 - original often uses ! for >=3?
			sb.WriteString(fmt.Sprintf("!%d%c", run, data[i]))
		} else {
			for k:=0;k<run;k++ { sb.WriteByte(data[i]) }
		}
		i=j
	}
	// Trim trailing '?' (? = empty) at end? Original kept !10? for whole width even if empty at end for last band, but for colour bands it may include trailing ? to fill width.
	// We'll keep full width as original does for many cases (they pad to width)
	return sb.String()
}

func encodeKitty(pc *PixelCanvas, o *Opts, resolved string) string {
	// raw RGBA bytes
	data := make([]byte, pc.W*pc.H*4)
	for i,p := range pc.Pix {
		data[i*4]=p.R; data[i*4+1]=p.G; data[i*4+2]=p.B; data[i*4+3]=p.A
	}
	var sb strings.Builder
	// Passthrough handling is done by caller wrapping sequences: kitty passthrough modifies header.
	// Build normal sequences chunks
	head := fmt.Sprintf("\x1b_Ga=T,f=32,s=%d,v=%d,c=%d,r=%d,m=1,q=2\x1b\\", pc.W, pc.H, pc.CellsW, pc.CellsH)
	sb.WriteString(head)
	// chunking 510 bytes raw
	chunkSize := 510
	if len(data)==0 {
		sb.WriteString("\x1b_Gm=0\x1b\\")
		sb.WriteString("\n")
		return sb.String()
	}
	for off:=0; off<len(data); off+=chunkSize {
		end:=off+chunkSize; if end>len(data){end=len(data)}
		enc := base64.StdEncoding.EncodeToString(data[off:end])
		sb.WriteString("\x1b_Gm=1;"+enc+"\x1b\\")
	}
	sb.WriteString("\x1b_Gm=0\x1b\\")
	sb.WriteString("\n")
	return sb.String()
}

func encodeITerm(pc *PixelCanvas, o *Opts, resolved string) string {
	tiff := encodeTIFF(pc)
	b64 := base64.StdEncoding.EncodeToString(tiff)
	return fmt.Sprintf("\x1b]1337;File=inline=1;width=%d;height=%d;preserveAspectRatio=0:%s\x07\n", pc.CellsW, pc.CellsH, b64)
}

func encodeTIFF(pc *PixelCanvas) []byte {
	// Little endian TIFF as observed
	var buf bytes.Buffer
	// header
	buf.Write([]byte{'I','I',42,0})
	ifdOff := 8 + pc.W*pc.H*4
	writeU32(&buf, uint32(ifdOff))
	// pixel data
	for _, p := range pc.Pix {
		buf.WriteByte(p.R); buf.WriteByte(p.G); buf.WriteByte(p.B); buf.WriteByte(p.A)
	}
	// IFD
	entries := []struct{tag, typ uint16; count uint32; value uint32}{
		{256,4,1,uint32(pc.W)},
		{257,4,1,uint32(pc.H)},
		{258,3,4,0}, // offset placeholder fill later
		{262,3,1,2},
		{273,4,1,8},
		{274,3,1,1},
		{277,3,1,4},
		{278,4,1,uint32(pc.H)},
		{279,4,1,uint32(pc.W*pc.H*4)},
		{284,3,1,1},
		{338,3,1,2},
	}
	// Bits offset after IFD: ifdOff + 2 + 11*12+4 = ifdOff+138
	bitsOff := ifdOff + 2 + len(entries)*12 + 4
	entries[2].value = uint32(bitsOff)
	writeU16(&buf, uint16(len(entries)))
	for _, e := range entries {
		writeU16(&buf, e.tag); writeU16(&buf, e.typ); writeU32(&buf, e.count)
		// value: if type short and count 1, value is in low bytes little endian with padding
		if e.typ==3 && e.count==1 {
			writeU16(&buf, uint16(e.value)); writeU16(&buf, 0)
		} else {
			writeU32(&buf, e.value)
		}
	}
	writeU32(&buf, 0) // next IFD
	// bits per sample 8,8,8,8
	for i:=0;i<4;i++ { writeU16(&buf, 8) }
	return buf.Bytes()
}
func writeU16(b *bytes.Buffer, v uint16) { b.WriteByte(byte(v)); b.WriteByte(byte(v>>8)) }
func writeU32(b *bytes.Buffer, v uint32) { b.WriteByte(byte(v)); b.WriteByte(byte(v>>8)); b.WriteByte(byte(v>>16)); b.WriteByte(byte(v>>24)) }
GO"}

{"command":"cat > main.go <<'GO'
package main

import (
	"fmt"
	"math"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

var globalProg string
var hidePrinted bool
var politeGlobal bool
var colorResolvedGlobal string
var interrupted bool

func main() {
	prog := os.Args[0]
	globalProg = prog
	opts, err := parseArgs(prog, os.Args[1:])
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s: %s\n", prog, err.Error())
		os.Exit(2)
	}
	if opts.Help {
		fmt.Print(helpText(prog))
		return
	}
	if opts.Version {
		fmt.Print(versionText())
		return
	}
	// Signals: SIGINT should show cursor and exit 0 as original
	sigCh := make(chan os.Signal, 4)
	signal.Notify(sigCh, syscall.SIGINT)
	go func() {
		for range sigCh {
			interrupted = true
			if hidePrinted && !politeGlobal {
				// only if hiding was active? Original shows cursor even if interrupted during still duration.
				os.Stdout.WriteString("\x1b[?25h")
			}
			os.Exit(0)
		}
	}()
	exitCode := run(opts)
	os.Exit(exitCode)
}

func run(o *Opts) int {
	// Read files specs, validate dash and watch
	// Count dash usages
	dashCount := 0
	for _, p := range o.Positionals { if p=="-" { dashCount++ } }
	filesOptStdinUsed := false
	for _, fs := range o.FilesSpecs { if fs.Path=="-" { dashCount++; filesOptStdinUsed=true } }
	if dashCount > 1 {
		fmt.Fprintf(os.Stderr, "%s: Dash '-' to pipe from standard input can be used at most once.\n", o.Prog)
		return 2
	}
	// Read file lists (in order)
	var listEntries []string
	for _, fs := range o.FilesSpecs {
		var data []byte
		if fs.Path=="-" {
			b, _ := readAllStdin()
			data = b
		} else if fs.Path=="" {
			continue
		} else {
			b, err := os.ReadFile(fs.Path)
			if err != nil {
				continue
			}
			data = b
		}
		if fs.Zero {
			parts := strings.Split(string(data), "\x00")
			for _, p := range parts { if p!="" { listEntries = append(listEntries, p) } }
		} else {
			// split by \n, strip trailing \r
			s := string(data)
			parts := strings.Split(s, "\n")
			for _, p := range parts {
				p = strings.TrimSuffix(p, "\r")
				if p=="" { continue }
				listEntries = append(listEntries, p)
			}
		}
	}
	// Watch validation
	if o.Watch {
		// As deduced: using --files at all triggers exactly-one error; else check positional
		if len(o.FilesSpecs)>0 {
			fmt.Fprintf(os.Stderr, "%s: Can only use --watch with exactly one file.\n", o.Prog)
			return 2
		}
		if len(o.Positionals) > 1 {
			fmt.Fprintf(os.Stderr, "%s: Can only use --watch with exactly one file.\n", o.Prog)
			return 2
		}
		if len(o.Positionals)==0 || o.Positionals[0]=="-" {
			fmt.Fprintf(os.Stderr, "%s: Can only use --watch with a filename, not a pipe.\n", o.Prog)
			return 2
		}
	}
	// Combined files
	combined := []string{}
	combined = append(combined, listEntries...)
	combined = append(combined, o.Positionals...)
	if len(o.Positionals)==0 && !filesOptStdinUsed {
		// add default stdin if there is no positional (even if list entries exist)
		// But if combined is due to --files=- we already excluded. If files specs existed but were not stdin, still add (observed).
		// Exception: if FilesSpecs were present and all were ??? The observed behaviour for --files /tmp/list with no positional did add.
		combined = append(combined, "-")
	}
	// Resolve terminal caps, format, colour
	caps := detectTermCaps()
	format := o.FormatStr
	if !o.FormatSet { format = caps.Format }
	if format=="" { format="symbols" }
	resolvedColor := o.ColorsStr
	if !o.ColorsSet { resolvedColor = caps.Color }
	if resolvedColor=="" { resolvedColor="none" }
	colorResolvedGlobal = resolvedColor
	// Optimize default
	if !o.OptimizeSet {
		if resolvedColor=="none" { o.Optimize = 0 } else { o.Optimize = 5 }
	}
	// Preprocess default
	if !o.PreprocessSet {
		switch resolvedColor {
		case "none","2","8","16/8","16":
			o.Preprocess = true
		default:
			o.Preprocess = false
		}
	}
	// Dither default
	dither := o.DitherStr
	if dither=="" {
		if format=="sixels" { dither="noise" } else { dither="none" }
	}
	o.DitherStr = dither
	// Threads critical warning
	if o.ThreadsSet && o.Threads < -1 {
		// GLib critical: format with basename prog and pid and time
		now := time.Now()
		fmt.Fprintf(os.Stderr, "\n** (%s:%d): CRITICAL **: %02d:%02d:%02d.%03d: chafa_set_n_threads: assertion 'n >= -1' failed\n", filepath.Base(o.Prog), os.Getpid(), now.Hour(), now.Minute(), now.Second(), now.Nanosecond()/1e6)
	}
	politeGlobal = o.Polite
	// Hide cursor condition
	needHide := resolvedColor != "none" && !o.Polite
	// Grid mode separate
	if o.GridSet {
		// process grid and always exit 0 (except parse)
		if needHide { os.Stdout.WriteString("\x1b[?25l"); hidePrinted=true }
		renderGrid(o, caps, format, resolvedColor, combined)
		if needHide { os.Stdout.WriteString("\x1b[?25h"); hidePrinted=false }
		return 0
	}
	if needHide { os.Stdout.WriteString("\x1b[?25l"); hidePrinted=true }
	success := 0
	failures := 0
	// Watch mode single file
	if o.Watch {
		// single positional file
		fn := o.Positionals[0]
		// presentation loop for watch: render once, then poll for changes until duration expires (if set) or forever.
		// Implement: initial render as normal file (with duration handling inside renderFile but watch special)
		// If file fails to load, original exits 0 quietly after hide/show (observed). We'll do: try load, if fails return 0.
		frames, loadErrStr, ok := loadFile(fn, o)
		if !ok {
			_ = loadErrStr
			if needHide { os.Stdout.WriteString("\x1b[?25h"); hidePrinted=false }
			return 0
		}
		// Render with watch loop
		watchLoop(o, caps, format, resolvedColor, fn, frames)
		if needHide { os.Stdout.WriteString("\x1b[?25h"); hidePrinted=false }
		return 0
	}
	for idx, fn := range combined {
		if o.Clear {
			os.Stdout.WriteString("\x1b[2J\x1b[0H")
		}
		frames, reason, ok := loadFile(fn, o)
		if !ok {
			failures++
			fmt.Fprintf(os.Stderr, "%s: Failed to open '%s': %s\n", o.Prog, fn, reason)
			continue
		}
		// separator before successful file if it's not first attempted
		if idx > 0 {
			if o.Relative && format=="symbols" {
				// In relative mode, still after previous file's final terminator they add a down
				os.Stdout.WriteString("\x1bD")
			} else if format=="symbols" || true {
				// For pixel formats, separator is a newline as well? Pixel+pixel: check: still prints \n between? The frame encoding already ends with \n, separator is extra \n.
				// Our renderFile will print its own content ending with \n; separator is one extra "\n" printed before content.
				os.Stdout.WriteString("\n")
			}
		}
		success++
		renderFilePresentation(o, caps, format, resolvedColor, fn, frames, len(combined))
		// label after image (if not animated? Label also after animated (? We'll handle inside? For still, print label here)
		// Label handling is done inside? To avoid double for animations, we printed label in renderFilePresentation? No, handle here if presentation was still or after animation completes.
		// renderFilePresentation returns whether it was animated and already handled label? Simplify: label here if Label on and not in grid
		if o.Label {
			printLabel(o, fn, format)
		}
	}
	if needHide { os.Stdout.WriteString("\x1b[?25h"); hidePrinted=false }
	if success>0 && failures>0 { return 1 }
	if success==0 && failures>0 { return 2 }
	if failures>0 { return 2 }
	return 0
	_ = math.Inf
}

func readAllStdin() ([]byte, error) {
	// Read all stdin; Go's io.ReadAll
	return readAllFrom(os.Stdin)
}

func loadFile(fn string, o *Opts) (frames []*Frame, reason string, ok bool) {
	if fn=="-" {
		data, _ := readAllStdin()
		if len(data)==0 {
			return nil, "Could not cache input stream", false
		}
		frs, err := decodeImageData(data, fn)
		if err != nil { return nil, "Unknown file format", false }
		return frs, "", true
	}
	// Regular file
	f, err := os.Open(fn)
	if err != nil {
		return nil, errnoString(err), false
	}
	defer f.Close()
	info, err := f.Stat()
	if err == nil && info.IsDir() {
		return nil, "Unknown file format", false
	}
	data, err := readAllFrom(f)
	if err != nil {
		// Distinguish permission etc? If read fails due permission, errnoString
		// For directory read error in Go, it's Is a directory - we already handled.
		return nil, "Unknown file format", false
	}
	frs, err := decodeImageData(data, fn)
	if err != nil { return nil, "Unknown file format", false }
	return frs, "", true
}

func errnoString(err error) string {
	// Extract errno if possible
	if os.IsNotExist(err) { return "No such file or directory" }
	if os.IsPermission(err) { return "Permission denied" }
	// Try to parse from PathError
	if pe, ok := err.(*os.PathError); ok {
		if en, ok2 := pe.Err.(interface{ Error() string }); ok2 {
			s := en.Error()
			// capitalize first letter
			if len(s)>0 { s = strings.ToUpper(s[:1])+s[1:] }
			return s
		}
	}
	s := err.Error()
	// Go errors like "open x: no such file..." - strip prefix up to colon
	if idx:=strings.LastIndex(s, ": "); idx>=0 { s = s[idx+2:] }
	if len(s)>0 { s = strings.ToUpper(s[:1])+s[1:] }
	return s
}

func printLabel(o *Opts, fn string, format string) {
	// label is basename (or fn if '-')
	label := fn
	if fn != "-" {
		label = filepath.Base(fn)
	}
	// width padding: to view width -1? Original: 79 for 80 view. It's effViewW-1?
	effW,_,_,_ := effectiveView(o)
	width := effW-1
	if width < len([]rune(label)) { width = len([]rune(label)) }
	// Link handling
	isLink := false
	if o.LinkStr=="on" { isLink=true } else if o.LinkStr=="auto" { isLink=false } // auto off when not tty
	var sb strings.Builder
	if isLink && fn!="-" {
		abs, _ := filepath.Abs(fn)
		host, _ := os.Hostname()
		// file://hostname/abs
		sb.WriteString(fmt.Sprintf("\x1b]8;;file://%s%s\x1b\\%s\x1b]8;;\x1b\\", host, abs, label))
		visible := len([]rune(label))
		if width > visible { sb.WriteString(strings.Repeat(" ", width-visible)) }
		sb.WriteString("\n")
	} else {
		// padded with spaces to width
		sb.WriteString(label)
		visible := len([]rune(label))
		if width > visible { sb.WriteString(strings.Repeat(" ", width-visible)) }
		sb.WriteString("\n")
	}
	os.Stdout.WriteString(sb.String())
}

func versionText() string {
	return "Chafa version 1.19.0\n\nLoaders:  GIF JPEG PNG QOI SVG TIFF WebP XWD\nFeatures: mmx sse4.1 popcnt avx2\nApplying: mmx sse4.1 popcnt avx2\n\nCopyright (C) 2018-2025 Hans Petter Jansson et al.\nIncl. libnsgif copyright (C) 2004 Richard Wilson, copyright (C) 2008 Sean Fox\nIncl. LodePNG copyright (C) 2005-2018 Lode Vandevenne\nIncl. QOI decoder copyright (C) 2021 Dominic Szablewski\n\nThis is free software; see the source for copying conditions. There is NO\nwarranty; not even for MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.\n\n"
}
GO"}

