package main

import (
	"io"
	"math"
	"os"
	"strings"
	"time"
)

func readAllFrom(r io.Reader) ([]byte, error) {
	return io.ReadAll(r)
}

// Render a single file presentation (still or animated)
func renderFilePresentation(o *Opts, caps TermCaps, format string, resolvedColor string, filename string, frames []*Frame, totalFiles int) {
	if len(frames)==0 { return }
	isAnimated := len(frames)>1 && o.Animate
	if !isAnimated {
		// still: use first frame (what if GIF first frame blank? Original --animate off uses first frame)
		renderStill(o,caps,format,resolvedColor,frames[0], filename)
		// duration wait
		dur := resolvedDuration(o, totalFiles, false)
		if dur>0 {
			if math.IsInf(dur,1) {
				// wait until interrupt
				for { time.Sleep(100*time.Millisecond); if interrupted { return } }
			} else if dur>0 {
				time.Sleep(time.Duration(dur*float64(time.Second)))
			}
		}
		return
	}
	// animated
	renderAnimated(o,caps,format,resolvedColor,frames, totalFiles)
}

func resolvedDuration(o *Opts, totalFiles int, isAnim bool) float64 {
	if o.DurationSet { return o.Duration }
	if totalFiles != 1 { return 0 }
	if isAnim {
		if isTTY(os.Stdout) { return math.Inf(1) }
		return 0
	}
	return 0
}

