}
// to avoid import fmt in this file, we implement via recursion in encode? We'll instead use fmt in file header (added)

func relBetweenRows(w int) string { return "\x1b["+itoa(w)+"D\x1bD" }
func relFinalRow(w int) string { return "\x1bD\x1b["+itoa(w)+"D" }
func formatRelSep(w int, between bool) string {
