					}
				}
				os.Stdout.WriteString(wrapPassthrough(sb.String(), o, format))
			} else {
				pc := makePixelCanvas(fr, cellsW, cellsH, o, format, caps)
				out := encodePixelCanvas(pc, o, resolvedColor, format, caps)
				os.Stdout.WriteString(wrapPassthrough(out, o, format))
			}
			firstFrame = false
			// sleep for frame delay
			delay := frameDelay(fr, o)
			if delay>0 { time.Sleep(delay) }
			// after frame, check duration expiry
			elapsed := time.Since(start)
			shouldEnd := false
			if playOnceOnly {
				if idx==len(frames)-1 { shouldEnd=true }
			} else if !math.IsInf(dur,1) {
				// duration: at least one pass, then end when elapsed >= dur
				if elapsed >= time.Duration(dur*float64(time.Second)) {
					// But need at least one full pass: if we are in first pass and not finished, don't end yet? Original plays at least once.
					// One pass is complete when idx == len-1 or we already passed? If elapsed expires mid-pass at a frame that is not last, they still end (in -d3 mid-pass case they ended after 2nd frame of 2nd pass). For first pass, if dur is small (0.1), they still play whole first pass.
					// Determine pass number
					passComplete := isPassComplete(frameIdx, idx, len(frames))
					if frameIdx>0 || passComplete {
						shouldEnd=true
					} else if idx==len(frames)-1 {
						shouldEnd=true
					}
					// Our frameIdx counts frames rendered overall; passComplete logic simplified below:
					// Actually if elapsed>=dur and we have completed at least one pass OR we are beyond first pass, end.
					// We track passes outside.
					_ = passComplete
				}
			}
			// Better duration end handling using passes count: we maintain in outer loop variables? Simplified: if dur finite and elapsed>=dur and (total frames rendered >= len(frames)) then end.
			// total rendered = frameIdx+1 after increments below. We'll compute after inc.
			frameIdx++
			if playOnceOnly && idx==len(frames)-1 {
				// finalise symbol frame with newline
				finaliseAnimFrame(o, format)
				return
			}
			if !playOnceOnly && !math.IsInf(dur,1) && dur>=0 {
				if time.Since(start) >= time.Duration(dur*float64(time.Second)) && frameIdx >= len(frames) {
					finaliseAnimFrame(o, format)
					return
				}
				_ = shouldEnd
			}
			if interrupted { finaliseAnimFrame(o, format); return }
		}
		// end of a pass
		if playOnceOnly {
			finaliseAnimFrame(o, format); return
		}
		if math.IsInf(dur,1) {
			continue
		}
		if dur==0 {
			// duration 0 for animated means play once (handled)
			finaliseAnimFrame(o, format); return
		}
		if time.Since(start) >= time.Duration(dur*float64(time.Second)) {
			finaliseAnimFrame(o, format); return
		}
	}
}

func isPassComplete(totalFramesRendered, idx, n int) bool { return idx==n-1 }

func finaliseAnimFrame(o *Opts, format string) {
	if format=="symbols" {
		if o.Relative {
			// relative final frame already ended with \x1bD\x1b[wD; no extra newline
			return
		}
		os.Stdout.WriteString("\n")
	}
	// pixel formats already end with \n in their encoding
}

func frameDelay(fr *Frame, o *Opts) time.Duration {
	if o.SpeedMax {
		return 0
	}
	if o.SpeedFPS {
		if o.SpeedVal<=0 || math.IsInf(o.SpeedVal,1) { return 0 }
		return time.Duration(float64(time.Second)/o.SpeedVal)
	}
	// multiplier
	mult := o.SpeedVal
	if mult<=0 { mult=1 }
	if math.IsInf(mult,1) { return 0 }
	d := float64(fr.DelayMs)/mult
	if d<0 { d=0 }
	// GIF delays less than ... browsers min 10ms? Chafa may honour as is. Keep as is but if delay 0 use 100ms? GIF with 0 delay - many tools use 100ms. anim.gif has 500ms.
	if fr.DelayMs==0 { return 0 }
	return time.Duration(d*float64(time.Millisecond))
}

func encodePixelCanvas(pc *PixelCanvas, o *Opts, resolved string, format string, caps TermCaps) string {
	switch format {
	case "sixels":
		return encodeSixel(pc,o,resolved,caps)
	case "kitty":
		return encodeKitty(pc,o,resolved)
	case "iterm":
		return encodeITerm(pc,o,resolved)
	default:
		return ""
	}
}

func watchLoop(o *Opts, caps TermCaps, format string, resolved string, filename string, initialFrames []*Frame) {
	// Simple watch: render initial as still/animation with duration if set; then poll file.
	// Original watch with duration: it repeatedly renders until duration, like a refresh.
	// We'll implement: if duration set, loop rendering still every ~100ms until elapsed duration; else loop until interrupt, re-render on change.
	start := time.Now()
	dur := o.Duration
	hasDur := o.DurationSet
	// Initial presentation
	// Use renderFilePresentation logic but without extra waiting: render still/animation once
	if len(initialFrames)>1 && o.Animate {
		renderAnimated(o,caps,format,resolved,initialFrames,1)
	} else {
		renderStill(o,caps,format,resolved,initialFrames[0], filename)
		if format=="symbols" && !o.Relative {
			// still render already included newline
		}
	}
	// Get mod info
	lastInfo, _ := os.Stat(filename)
	var lastMod time.Time; var lastSize int64
	if lastInfo!=nil { lastMod=lastInfo.ModTime(); lastSize=lastInfo.Size() }
	for {
		if interrupted { return }
		if hasDur && !math.IsInf(dur,1) {
			if time.Since(start) >= time.Duration(dur*float64(time.Second)) { return }
		}
		time.Sleep(100*time.Millisecond)
		// If duration set and file is still, original seems to re-render periodically; we re-render on each poll if hasDur and still?
		// For anim case, renderAnimated already handled duration loop; return after it
		if len(initialFrames)>1 && o.Animate {
			// renderAnimated returned because duration expired or play once; if watch is on, we should continue watching for change.
			// Fall through to check change.
			if hasDur && !math.IsInf(dur,1) && time.Since(start) >= time.Duration(dur*float64(time.Second)) { return }
		}
		info, err := os.Stat(filename)
		changed := false
		if err==nil && lastInfo!=nil {
			if !info.ModTime().Equal(lastMod) || info.Size()!=lastSize { changed=true; lastMod=info.ModTime(); lastSize=info.Size() }
		}
		if changed {
			// cursor restore before re-render: original uses \x1b[u in some cases
			if format=="symbols" {
				os.Stdout.WriteString("\x1b[u")
			}
			frames, _, ok := loadFile(filename, o)
			if ok {
				if len(frames)>1 && o.Animate {
					// header already? For watch re-render of animation, they'd start new presentation - simplified render still frame
					renderStill(o,caps,format,resolved,frames[0],filename)
				} else {
					renderStill(o,caps,format,resolved,frames[0],filename)
				}
				initialFrames=frames
			}
		} else {
			// If still with duration, original watch re-renders repeatedly (observed many repeats). Re-render every poll for still+watch+duration case.
			if hasDur && len(initialFrames)==1 {
				if format=="symbols" { os.Stdout.WriteString("\x1b[u") }
				renderStill(o,caps,format,resolved,initialFrames[0],filename)
			}
		}
	}
}

func wrapPassthrough(s string, o *Opts, format string) string {
	mode := o.Passthrough
	if mode=="auto" { mode="none" }
	if mode=="none" { return s }
	if format=="symbols" { return s }
	if mode=="tmux" {
		// Wrap each graphics escape sequence as in original: sequences are identified by starting with ESC P (sixel), ESC _ (kitty), ESC ] (iterm - passthrough for iterm was unchanged?)
		// For iterm, original output was unchanged in tmux mode (1337 sequence not wrapped)
		if format=="iterm" { return s }
		// wrap whole content (which is one graphics sequence plus trailing newline): need to preserve trailing newline outside.
		// The original tmux wrapping: prefix \x1bPtmux; , double all ESC, replace closing? It appends \x1b\\ after doubled terminator.
		// Simplify: if s ends with "\n", separate
		suffix := ""
		if strings.HasSuffix(s,"\n") { suffix="\n"; s=strings.TrimSuffix(s,"\n") }
		doubled := strings.ReplaceAll(s, "\x1b", "\x1b\x1b")
		// doubled already includes final \x1b\x1b\\ (from original's \x1b\\ ), need add outer \x1b\\
		return "\x1bPtmux;" + doubled + "\x1b\\" + suffix
	}
	if mode=="screen" {
		if format=="iterm" { return s }
		// Screen wrapping is complex: it modifies kitty header to include U=1,i=... and wraps each sequence in \x1bP ... \x1b\\
		// For sixel: output is \x1bP + original + \x1bP\x1b\x1b\\\x1bP\\\x1b\\ + \n
		// Approximate for sixel:
		if format=="sixels" {
			suffix:=""
			if strings.HasSuffix(s,"\n") { suffix="\n"; s=strings.TrimSuffix(s,"\n") }
			return "\x1bP" + s + "\x1bP\x1b\x1b\\\x1bP\\\x1b\\" + suffix
		}
		// kitty under screen: header change not implemented; wrap chunks similarly: wrap each \x1b_G... sequence in \x1bP ... plus terminator segment
		// Simplify: wrap entire string (excluding trailing newline) with \x1bP prefix blocks per sequence: split by \x1b\\
		suffix:=""
		if strings.HasSuffix(s,"\n") { suffix="\n"; s=strings.TrimSuffix(s,"\n") }
		parts := strings.SplitAfter(s, "\x1b\\")
		var out strings.Builder
		for _, p := range parts {
			if p=="" { continue }
			out.WriteString("\x1bP"+p+"\x1bP\x1b\x1b\\\x1bP\\\x1b\\")
		}
		return out.String()+suffix
	}
	return s
}
GO"}

