new='''func errorFixed(grid [][]PixF, cx,cy int, sym *Symbol, fg,bg Color, o *Opts, sub int) float64 {
	// Scalar projection model: pixel effective colour projected onto FG-BG line.
	dx:=float64(fg.R-bg.R); dy:=float64(fg.G-bg.G); dz:=float64(fg.B-bg.B)
	den:=dx*dx+dy*dy+dz*dz
	if den==0 { return 0 }
	var err float64
	for sy:=0; sy<sub; sy++ {
		for sx:=0; sx<sub; sx++ {
			cov := covAt(sym,sx,sy,sub)
			y:=cy*sub+sy; x:=cx*sub+sx
			if y<0||y>=len(grid)||x<0||x>=len(grid[0]) { continue }
			p:=grid[y][x]
			af:=p.A/255.0
			er:=p.PR + float64(bg.R)*(1-af)
			eg:=p.PG + float64(bg.G)*(1-af)
			eb:=p.PB + float64(bg.B)*(1-af)
			// If pixel is transparent, effective is BG (af=0 -> er=bg)
			tt:=((er-float64(bg.R))*dx + (eg-float64(bg.G))*dy + (eb-float64(bg.B))*dz)/den
			// DIN99 note: scalar model still works in RGB projection.
			diff:=tt-cov
			err += diff*diff*den // scale back to RGB-ish squared units
		}
	}
	return err
}

func covAt(sym *Symbol, sx,sy,sub int) float64 {
	if sub==8 { return sym.Cov[sy*8+sx] }
	// average coverage of the 8-grid block corresponding to this subpixel
	x0:=sx*8/sub; x1:=(sx+1)*8/sub; y0:=sy*8/sub; y1:=(sy+1)*8/sub
	var sum float64; cnt:=0
	for y:=y0;y<y1;y++ { for x:=x0;x<x1;x++ { sum+=sym.Cov[y*8+x]; cnt++ } }
	if cnt==0 { return sym.Cov[(sy*8/sub)*8+(sx*8/sub)] }
