import pathlib
p=pathlib.Path('symbols_build.go'); t=p.read_text()
old_start=t.find('func covFrom5x7')
old_end=t.find('func buildASCII')
new='''func covFrom5x7(pat []string, lower bool) [64]float64 {
	// Render 5x7 font into 8x8 coverage by supersampling.
	// Glyph occupies width 7/8 of cell and height 7/8, with y offset for lowercase.
	var cov [64]float64
	const SS=4
	yoffCells := 0.0
	if lower { yoffCells = 1.0 }
	for cy:=0;cy<8;cy++ {
		for cx:=0;cx<8;cx++ {
			cnt:=0
			for sy:=0;sy<SS;sy++ {
				for sx:=0;sx<SS;sx++ {
					x:=(float64(cx)+(float64(sx)+0.5)/SS)/8.0
					y:=(float64(cy)+(float64(sy)+0.5)/SS)/8.0
					// Map to font space: glyph width 0.875, height 0.875 starting at yoffCells/8
					gy := y - yoffCells/8.0
					if x<0 || x>=0.875 || gy<0 || gy>=0.875 { continue }
					fx := int(x/0.875*5)
					fy := int(gy/0.875*7)
					if fy>=0 && fy < len(pat) && fx>=0 && fx < len(pat[fy]) && pat[fy][fx]=='#' { cnt++ }
				}
			}
			cov[cy*8+cx]=float64(cnt)/(SS*SS)
		}
	}
	return cov
}

