	// Parallelize by rows (candidate evaluation is independent per cell)
	{
		type rowJob struct{ y int }
		jobs := make(chan int, cellsH)
		workers := 8
		if cellsH < workers { workers = cellsH }
		if workers < 1 { workers = 1 }
		var wg sync_WaitGroup
		for w:=0; w<workers; w++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				for cy := range jobs {
					for cx:=0; cx<cellsW; cx++ {
